    if(!D&&v===0)for(let y=Math.round(Y(2.0*k));y<=Math.round(Y(1.78*k));y++)p.set(X(0),y,hex('#e8e0d0'));
    for(const sx of[-1,1]){p.set(X(sx*.085*k),Y(1.98*k),BLACK_);p.set(X(sx*.035*k),Y(1.69*k),FPAL.hoof[0]);}
    for(let x=Math.round(X(-.1*k));x<=Math.round(X(.1*k));x++)p.set(x,Math.round(Y(1.8*k)),FPAL.saddle[1]);
    E(0,2.08*k,.05*k,.04*k,Mn,.5);
