/* =========================================================
   Atlas
   ========================================================= */
const ATLAS=2048,SPR={};
function buildAtlas(){
  const list=[];
  for(let i=0;i<3;i++)list.push(['pine'+i,drawPine(100+i*31,i)]);
  for(let i=0;i<3;i++)list.push(['oak'+i,drawLeafy(200+i*37,{W:72,H:88,pal:OAK[i%2],trunkTop:50,trunkW:3.6,crown:{cx:35.5,cy:34,rx:32,ry:28},blobs:11})]);
  for(let i=0;i<2;i++)list.push(['birch'+i,drawLeafy(300+i*41,{W:40,H:100,pal:BIRCH_LEAF,birch:true,trunkTop:40,trunkW:2.2,crown:{cx:19.5,cy:36,rx:17,ry:31},blobs:9})]);
  list.push(['bush0',drawLeafy(400,{W:34,H:24,pal:BUSH,crown:{cx:16.5,cy:14,rx:15,ry:9},blobs:6})]);
  list.push(['bush1',drawLeafy(411,{W:34,H:24,pal:BUSH,crown:{cx:16.5,cy:14,rx:15,ry:9},blobs:7,berries:true})]);
  for(let i=0;i<4;i++)list.push(['grass'+i,drawGrass(500+i*13)]);
  [['#f2f0ea','#d9d4c6','#b8b2a2'],['#ffd23f','#e8b221','#b98314'],['#7ab8ff','#4f8fe0','#3765ad'],['#ff8ab0','#e2597f','#a83a5a']].forEach((c,i)=>list.push(['flower'+i,drawFlower(600+i,c)]));
  for(let i=0;i<3;i++)list.push(['tall'+i,drawGrass(520+i*17,18,18,MEADOW_GRASS,8,9)]);
  list.push(['reed0',drawReed(560)]);list.push(['reed1',drawReed(577)]);
  list.push(['fern0',drawFern(700)]);list.push(['fern1',drawFern(733)]);
  list.push(['rock0',drawRock(800,22,14)]);list.push(['rock1',drawRock(811,30,18)]);
  list.push(['stump0',drawStump(900)]);
  for(let i=0;i<3;i++)list.push(['wheat'+i,drawWheat(1000+i*7)]);
  for(let i=0;i<3;i++)list.push(['grave'+i,drawGrave(i)]);
  list.push(['hay',drawHay()]);eastSprites(list);craftSprites(list);frogSprites(list);desertSprites(list);part1Sprites(list);coachSprites(list);demonSprites(list);caveItemSprites(list);caveMobSprites(list);farSprites(list);jungleSprites(list);wildSprites(list);
  list.push(['coin',drawCoin()]);list.push(['silver',drawCoin(['#3e444c','#6a727c','#9aa3ad','#c9d0d8','#f2f5f8'])]);list.push(['copper',drawCoin(['#4a2210','#7a3a1c','#a8582c','#d07a46','#f0a878'])]);EQUIP_ICONS().forEach(e=>list.push(e));WEAPON_ICONS().forEach(e=>list.push(e));list.push(['dagger',drawDagger()]);list.push(['horseshoe',drawHorseshoe()]);list.push(['bread',drawBread()]);list.push(['meat',drawMeat()]);list.push(['trumpet',drawTrumpet()]);list.push(['bedroll',drawBedroll()]);list.push(['horsearmor',drawHorseArmor()]);list.push(['fur',drawFur()]);list.push(['antler',drawAntler()]);list.push(['mead',drawMead()]);
  for(let i=0;i<3;i++)list.push(['dpine'+i,drawPine(1200+i*29,i,DPINE[i])]);
  list.push(['dead0',drawDead(1300)]);list.push(['dead1',drawDead(1311)]);list.push(['eyes',drawEyes()]);list.push(['anvil',drawAnvil()]);
  VDEFS.forEach(d=>{for(let f=0;f<3;f++)list.push(['p'+d.id+'_'+f,drawPerson(d,f)]);});
  GUARD_LOOKS.forEach((g,i)=>{for(let f=0;f<3;f++)list.push(['g'+i+'_'+f,drawHero(g,f)]);});
  animalSprites(list);
  list.push(['stick',drawStick()]);list.push(['mushroom',drawMushroom()]);list.push(['stone',drawStone()]);list.push(['cone',drawCone()]);
  list.sort((a,b)=>b[1].height-a[1].height);
  const cv=document.createElement('canvas');cv.width=cv.height=ATLAS;const ctx=cv.getContext('2d');
  let x=2,y=2,rowH=0;
  for(const[name,c]of list){if(x+c.width+2>ATLAS){x=2;y+=rowH+3;rowH=0;}
    ctx.drawImage(c,x,y);SPR[name]={c,w:c.width,h:c.height,u:x/ATLAS,v:1-(y+c.height)/ATLAS,du:c.width/ATLAS,dv:c.height/ATLAS};
    x+=c.width+3;rowH=Math.max(rowH,c.height);}
  const tex=new THREE.CanvasTexture(cv);tex.magFilter=THREE.NearestFilter;tex.minFilter=THREE.NearestFilter;tex.generateMipmaps=false;
  return tex;
}

/* =========================================================
   World layout  — Wald (north), Ebene (twice the size), Dorf Coda (south)
   North is -z, south is +z.  Forest: z -120..120, Plain: 120..600, Coda: 600..840
   ========================================================= */
const SIZE=240,HALF=SIZE/2,ZMIN=-HALF,FOREST_END=120,PLAIN_END=600,ZMAX=840,CELL=2,SEGX=SIZE/CELL,SEGZ=(ZMAX-ZMIN)/CELL,R1=SEGX+1;
const BOUND=HALF-1.5,ZB0=ZMIN+14,ZB1=ZMAX-14,PATH_W=1.3,WATER=0;
// Der Tiefe Wald: 7x breiter, 5x länger als der Wald, nördlich davon
const NX0=-7*HALF,NX1=7*HALF,NZ0=ZMIN-5*SIZE,NCELL=2,NSX=(NX1-NX0)/NCELL,NSZ=(ZMIN-NZ0)/NCELL,NR1=NSX+1;
