  const leg=(x0,y0,kx,ky,fx,ph)=>{const sw=s*ph*2.2;const pts=[[x0,y0],[x0+kx+sw*.4,y0+ky],[x0+fx+sw,0.6]];
    for(let i=0;i<2;i++){const[a,b]=[pts[i],pts[i+1]],n=Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])*g*1.2);for(let k=0;k<=n;k++){const t=k/n,x=(a[0]+(b[0]-a[0])*t)*g,y=gy-(a[1]+(b[1]-a[1])*t)*g;p.set(x,y,B[1]);p.set(x,y-1,B[2]);if(g>1.1)p.set(x+1,y,B[0]);}}};
  // hintere Beinreihe
