  // Hinterleib, Taille, Brust, Kopf
  E(10,15,10,8.5,A,.55);for(let k=0;k<3;k++)for(let x=3+k*6;x<5+k*6;x++)for(let y=9;y<22;y++)if(((x*3+y)%5)===0)p.set(x*g,gy-y*g,A[0]);
  E(20.5,14,2.2,2.2,B,.5);E(27,15,6.5,3.6,B,.6);E(23.5,17,2.5,2.2,B,.55);
  if(q){E(13,17,12,10.5,A,.55);for(let x=3;x<24;x+=4)for(let y=8;y<27;y+=1)if(((x+y)%7)===0)p.set(x*g,gy-y*g,A[3]);}
  E(37+(big?1.5:0),17,big?6.5:5,big?5.2:4.2,B,.62);
  // Fühler
  for(const[ox,len]of[[0,1],[1.5,.85]]){const bx=38+ox,by=21;for(let k=0;k<9*len;k++){p.set((bx+k*.55)*g,gy-(by+k*.9)*g,B[2]);}for(let k=0;k<6*len;k++)p.set((bx+5*len+k*.8)*g,gy-(by+8*len-k*.3)*g,B[3]);}
  // Mandibeln
  const mx=42+(big?3:0),my=13;for(let k=0;k<(big?7:5);k++){p.set((mx+k*.8)*g,gy-(my+k*.25)*g,B[3]);p.set((mx+k*.8)*g,gy-(my-1.2+Math.sin(k*.7)*1.2)*g,B[2]);}
