  for(let dx=0;dx<2*g;dx++)for(let dy=0;dy<2*g;dy++)p.set(ex*g+dx,gy-ey*g+dy,hex(dx<1&&dy<1?ec[1]:dy>=g?ec[2]:ec[0]));
