  leg(23,12,-8,6,-13,1);leg(27,12,1,7,1,-1);leg(31,12,8,6,13,1);
  if(leaf){const L=pal(['#1a4a1a','#2a6a26','#3e8a34','#5aa648']);for(let y=0;y<12;y++)for(let x=0;x<14;x++){const dx=(x-7)/7,dy=(y-6)/5.5;if(dx*dx+dy*dy>1)continue;p.set((44+x*.9)*g,gy-(16+12-y)*g,L[shadeIdx(.6-dx*.3-dy*.2,L.length,x,y)]);}
    for(let k=0;k<10;k++)p.set((45+k*.9)*g,gy-(22-k*.25)*g,L[0]);}
