function drawAntEgg(){const p=new Px(10,12);for(let y=0;y<12;y++)for(let x=0;x<10;x++){const dx=(x-4.5)/4.6,dy=(y-6)/5.8;if(dx*dx+dy*dy>1)continue;p.set(x,y,hex(dx*dx+dy*dy<.3&&dx<0?'#ffffff':dy>.4?'#cfc6a8':'#efe8d2'));}outline(p);return p.done();}
