  {const b={x:-60,z:-1830,cos:1,sin:0};boxL(VM.stone,b,-6,6,STORM_TOP,STORM_TOP+16,-12,12,2,2,'FBLR');gable(VM.slate,VM.stone,b,-6,6,STORM_TOP+16,-12,12,7);tower(-60,-1815,3.2,STORM_TOP+34,12,VM.slate);}
