  const stone=pxTex(32,32,p=>{for(let y=0;y<32;y++){const row=y>>3,off=(row&1)?8:0;for(let x=0;x<32;x++){const bx=((x+off)>>4),mort=(y&7)===0||((x+off)&15)===0;
    p.set(x,y,mort?ST[0]:ST[shadeIdx(.55+(hash2(bx,row,303)-.5)*.5+(hash2(x,y,304)-.5)*.25+((y&7)===1?.15:0),ST.length,x,y)]);}}});
  const RT=pal(['#4e1c14','#6e2a1c','#8c3a26','#a84e32','#c06a48']);
  const tiles=pxTex(32,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<32;x++){const row=y>>2,off=(row&1)?2:0,ty=y&3,tx=(x+off)&3;
    p.set(x,y,RT[shadeIdx(.65-ty*.13-(tx===3?.2:0)+(hash2((x+off)>>2,row,305)-.5)*.3,RT.length,x,y)]);}});
  const SL=pal(['#20242c','#2e3440','#3e4656','#525c6e']);
  const slate=pxTex(32,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<32;x++){const row=y>>2,off=(row&1)?3:0,ty=y&3;
    p.set(x,y,SL[shadeIdx(.65-ty*.15-(((x+off)%6)===0?.25:0)+(hash2(((x+off)/6)|0,row,306)-.5)*.3,SL.length,x,y)]);}});
  const TH=pal(['#5c4520','#7a5e2c','#9a7a3a','#b8964c','#d0b064']);
  const thatch=pxTex(32,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<32;x++){p.set(x,y,TH[shadeIdx(.55+(hash2(x,y>>2,307)-.5)*.6-((y&7)===7?.3:0),TH.length,x,y)]);}});
  const WD=pal(['#2c1a0e','#43291a','#5e3b24','#7a5032','#946640']),RW=pal(['#3c1410','#5a1f18','#782c20','#94402c']);
  const planks=pxTex(32,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<32;x++){const k=x>>2;p.set(x,y,(x&3)===0?WD[0]:WD[shadeIdx(.55+(hash2(k,0,308)-.5)*.3+(vnoise(k*3,y*.3,309)-.5)*.4,WD.length,x,y)]);}});
  const barnW=pxTex(32,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<32;x++){const k=x>>2;p.set(x,y,(x&3)===0?RW[0]:RW[shadeIdx(.55+(hash2(k,0,310)-.5)*.3+(vnoise(k*3,y*.3,311)-.5)*.4,RW.length,x,y)]);}});
  const IRON=hex('#1d1d20');
