  const sign=pxTex(16,12,p=>{for(let y=0;y<12;y++)for(let x=0;x<16;x++){let c=x===0||x===15||y===0||y===11?WD[0]:WD[3];
    if(x>=5&&x<=9&&y>=3&&y<=9)c=y===3?hex('#f2ecd8'):hex('#c8902e');if(x===10&&y>=5&&y<=7)c=hex('#8a5e1e');if(x===11&&(y===5||y===7))c=hex('#8a5e1e');if(x===11&&y===6)c=hex('#8a5e1e');p.set(x,y,c);}});
  const sail=pxTex(8,32,p=>{for(let y=0;y<32;y++)for(let x=0;x<8;x++){if(x===0||x===7||y%4===0)p.set(x,y,WD[3]);else if(x===3)p.set(x,y,WD[2]);else p.set(x,y,hex(((x+y)&1)?'#e8e0cc':'#d6ccb4'));}});
