function decal(m,b,face,along,y,w,h,hw,hd){const e=.03,P=(x,yy,z)=>W3(b,x,yy,z);
  if(face==='F')quad(m,P(along-w/2,y,hd+e),P(along+w/2,y,hd+e),P(along+w/2,y+h,hd+e),P(along-w/2,y+h,hd+e));
  else if(face==='B')quad(m,P(along+w/2,y,-hd-e),P(along-w/2,y,-hd-e),P(along-w/2,y+h,-hd-e),P(along+w/2,y+h,-hd-e));
  else if(face==='R')quad(m,P(hw+e,y,along+w/2),P(hw+e,y,along-w/2),P(hw+e,y+h,along-w/2),P(hw+e,y+h,along+w/2));
  else quad(m,P(-hw-e,y,along-w/2),P(-hw-e,y,along+w/2),P(-hw-e,y+h,along+w/2),P(-hw-e,y+h,along-w/2));}
const COLL=[];  // oriented boxes {x,z,cos,sin,hw,z0,z1}
function addColl(b,x0,x1,z0,z1){const[cx,cz]=toW(b,(x0+x1)/2,(z0+z1)/2);COLL.push({x:cx,z:cz,cos:b.cos,sin:b.sin,hw:(x1-x0)/2,hd:(z1-z0)/2,top:b.ct});}
function footY(b,hw,z0,z1){let m=-1e9;for(const[lx,lz]of[[-hw,z0],[hw,z0],[hw,z1],[-hw,z1],[0,(z0+z1)/2]]){const[x,z]=toW(b,lx,lz);m=Math.max(m,getHeight(x,z));}return m;}
