let waterMat;
function buildWater(){
  const pos=[],idx=[];let base=0;
  const strip=pts=>{pts.forEach((q,k)=>{pos.push(...q);if(k%2===1&&k>1){const a=base+k-3;idx.push(a,a+1,a+2,a+1,a+3,a+2);}});base+=pts.length;};
  {const P_=[];for(let x=PR_X0;x<=HALF+40;x+=2){const zc=riverZ(x);P_.push([x,WATER,zc-7.5],[x,WATER,zc+7.5]);}strip(P_);}
  for(const rf of[riverX1,riverX2]){const P_=[];for(let z=WZ0-6;z<=WZ1;z+=2){const xc=rf(z);P_.push([xc-7.5,WATER,z],[xc+7.5,WATER,z]);}strip(P_);}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setIndex(idx);
  waterMat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,
    uniforms:{time:{value:0},light:{value:1},lightCol:{value:LIGHT_COL},fogColor:{value:SKY_HOR},fogNear:{value:scene.fog.near},fogFar:{value:scene.fog.far}},
    vertexShader:'varying vec3 vW;varying float vD;void main(){vW=position;vec4 mv=modelViewMatrix*vec4(position,1.0);vD=-mv.z;gl_Position=projectionMatrix*mv;}',
    fragmentShader:`uniform float time;uniform float light;uniform vec3 lightCol;uniform vec3 fogColor;uniform float fogNear;uniform float fogFar;varying vec3 vW;varying float vD;
      void main(){vec2 cell=floor(vW.xz*8.0);vec2 q=cell/8.0;
        float a=sin(q.x*1.3-time*1.8+sin(q.y*1.9+time*.7)*1.5);float b=sin(q.y*2.7+q.x*.4+time*1.1);
        float n=fract(sin(dot(cell,vec2(12.9898,78.233)))*43758.5453);float v=a*.55+b*.45+(n-.5)*.35;
        vec3 c=v<-.35?vec3(.13,.29,.40):v<.25?vec3(.18,.39,.50):v<.72?vec3(.29,.53,.62):vec3(.64,.81,.85);c*=light*lightCol;
        gl_FragColor=vec4(mix(c,fogColor,smoothstep(fogNear,fogFar,vD)),.84);}`});
  scene.add(new THREE.Mesh(g,waterMat));
}
function buildBridge(B){const deckY=z=>deckYb(B,z),BX=0,BZ=0,BR_Z0=-B.L,BR_Z1=B.L;
  const p=new Px(32,8),W=pal(['#3a2615','#54381f','#6e4b2a','#8a6236','#a77a45']);
  for(let y=0;y<8;y++)for(let x=0;x<32;x++){let L=.55+(vnoise(x*.3,y*1.5,61)-.5)*.5+(hash2(x,y,62)-.5)*.2;if(y===0)L+=.25;if(y===7)L=.05;if(hash2(x>>2,y,63)<.07)L-=.25;
    p.set(x,y,W[shadeIdx(L,W.length,x,y)]);}
  p.set(3,3,W[0]);p.set(28,4,W[0]);
  const tex=new THREE.CanvasTexture(p.done());tex.magFilter=tex.minFilter=THREE.NearestFilter;tex.generateMipmaps=false;
  const mats=[.78,.92,1.05].map(k=>new THREE.MeshPhongMaterial({map:tex,color:new THREE.Color(k,k,k),flatShading:true,shininess:0,specular:0x000000}));
  const dark=new THREE.MeshPhongMaterial({map:tex,color:new THREE.Color(.6,.55,.5),flatShading:true,shininess:0,specular:0x000000});
  const grp=new THREE.Group(),plank=new THREE.BoxGeometry(BR_HW*2+.2,.16,.44),beam=new THREE.BoxGeometry(.2,.26,.52);
  for(let z=BR_Z0+.25;z<BR_Z1;z+=.5){const y=deckY(z),ang=-Math.atan((deckY(z+.25)-deckY(z-.25))/.5);
    const m=new THREE.Mesh(plank,mats[(hash2((z*2)|0,1,3)*3)|0]);m.position.set(BX,y-.08,z);m.rotation.x=ang;grp.add(m);
    for(const s of[-1,1]){const b=new THREE.Mesh(beam,dark);b.position.set(BX+s*(BR_HW+.02),y-.26,z);b.rotation.x=ang;grp.add(b);}}
  const postG=new THREE.BoxGeometry(.18,1.1,.18),posts=[];
  for(let z=BR_Z0+1.4;z<=BR_Z1-1.39;z+=(BR_Z1-BR_Z0-2.8)/6)posts.push(z);
  for(const s of[-1,1]){
    posts.forEach(z=>{const m=new THREE.Mesh(postG,dark);m.position.set(BX+s*1.42,deckY(z)+.45,z);grp.add(m);});
    for(let i=0;i<posts.length-1;i++){const za=posts[i],zb=posts[i+1],ya=deckY(za)+.92,yb=deckY(zb)+.92,len=Math.hypot(zb-za,yb-ya);
      const r=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,len),mats[1]);r.position.set(BX+s*1.42,(ya+yb)/2,(za+zb)/2);r.rotation.x=-Math.atan2(yb-ya,zb-za);grp.add(r);}}
  for(const dz of[-4,4])for(const s of[-1,1]){const top=deckY(BZ+dz)-.25,bot=-2,h=top-bot;
    const m=new THREE.Mesh(new THREE.BoxGeometry(.32,h,.32),dark);m.position.set(BX+s*1.2,bot+h/2,BZ+dz);grp.add(m);}
  grp.position.set(B.x,0,B.z);grp.rotation.y=Math.atan2(B.ux,B.uz);scene.add(grp);
}

