  put(1500,F0,F1,(x,z,d,pd)=>{if(pd<PATH_W+.5||d<.45||nearTree(x,z,.8))return null;const w=.9+r()*.5;return{w,h:w*15/26,spr:'fern'+(r()*2|0),sway:.07,tint:.85+r()*.2};});
  put(900,F0,F1,(x,z,d,pd)=>{if(pd<PATH_W+.8||r()>.6||nearTree(x,z,1))return null;const w=1.3+r()*.8;return{w,h:w*24/34,spr:r()<.25?'bush1':'bush0',sway:.05,tint:.85+r()*.2,sink:.15};});
  put(160,F0,F1,(x,z,d,pd)=>{if(pd<PATH_W+.3||nearTree(x,z,1))return null;const big=r()<.35,w=big?1.6+r()*.6:.8+r()*.5;return{w,h:w*(big?18/30:14/22),spr:big?'rock1':'rock0',tint:.9+r()*.15,sink:.12};});
  put(40,F0,F1,(x,z,d,pd)=>{if(pd<PATH_W+1||nearTree(x,z,1.2))return null;return{w:.8,h:.56,spr:'stump0',tint:.95,sink:.08};});
  // Ebene
  const E0=FOREST_END+2,E1=PLAIN_END+4,dry=gh=>gh>WATER+.35;
  put(17000,E0,E1,(x,z,d,pd,gh)=>{if(pd<PATH_W*.7||!dry(gh)||r()<.25)return null;const w=.65+r()*.45;return{w,h:w,spr:'tall'+(r()*3|0),sway:.12,tint:.88+r()*.18};});
  put(6000,E0,E1,(x,z,d,pd,gh)=>{if(pd<PATH_W*.7||!dry(gh))return null;const w=.5+r()*.3;return{w,h:w*.75,spr:'grass'+(r()*4|0),sway:.08,tint:.95+r()*.15};});
  put(9000,E0,E1,(x,z,d,pd,gh)=>{if(pd<PATH_W||!dry(gh)||vnoise(x*.06,z*.06,71)<.48)return null;return{w:.28,h:.42,spr:'flower'+(r()*4|0),sway:.05,tint:1};});
  put(420,E0,E1,(x,z,d,pd,gh)=>{if(pd<PATH_W+.8||!dry(gh)||nearTree(x,z,1.2))return null;const w=1.3+r()*.9;return{w,h:w*24/34,spr:r()<.35?'bush1':'bush0',sway:.05,tint:.92+r()*.15,sink:.15};});
  put(220,E0,E1,(x,z,d,pd,gh)=>{if(pd<PATH_W+.3||gh<WATER-.2||nearTree(x,z,1))return null;const big=r()<.3,w=big?1.6+r()*.7:.7+r()*.5;return{w,h:w*(big?18/30:14/22),spr:big?'rock1':'rock0',tint:.95+r()*.12,sink:.12};});
  for(let i=0;i<4200;i++){const x=(r()*2-1)*(HALF-4),z=riverZ(x)+(r()*2-1)*7.5,gh=getHeight(x,z);
    if(onBridge(x,z)||gh<WATER-.45||gh>WATER+.6)continue;const w=.7+r()*.4;deco.push({x,z,y:gh-.1,w,h:w*26/14,spr:'reed'+(r()*2|0),sway:.1,tint:.9+r()*.15});}
  // Coda
  const C0=PLAIN_END+2,C1=ZMAX-4,free=(x,z)=>!(maskAt(x,z)&15)&&!(maskAt(x+.8,z)&15)&&!(maskAt(x-.8,z)&15)&&!(maskAt(x,z+.8)&15)&&!(maskAt(x,z-.8)&15);
  put(9000,C0,C1,(x,z,d,pd,gh)=>{if(!free(x,z)||pd<PATH_W)return null;const tall=r()<.5,w=tall?.6+r()*.4:.5+r()*.3;return{w,h:tall?w:w*.75,spr:tall?'tall'+(r()*3|0):'grass'+(r()*4|0),sway:.1,tint:.92+r()*.15};});
  put(2500,C0,C1,(x,z,d,pd,gh)=>{if(!free(x,z)||pd<PATH_W||vnoise(x*.07,z*.07,72)<.5)return null;return{w:.28,h:.42,spr:'flower'+(r()*4|0),sway:.05,tint:1};});
  put(160,C0,C1,(x,z,d,pd,gh)=>{if(!free(x,z)||(maskAt(x,z)&16)||nearTree(x,z,1.2)||Math.hypot(x-CODA.x,z-CODA.z)<16)return null;const w=1.2+r()*.8;return{w,h:w*24/34,spr:r()<.4?'bush1':'bush0',sway:.05,tint:.92+r()*.15,sink:.15};});
  put(70,C0,C1,(x,z,d,pd,gh)=>{if(!free(x,z)||(maskAt(x,z)&16)||nearTree(x,z,1))return null;const w=.7+r()*.5;return{w,h:w*14/22,spr:'rock0',tint:.95,sink:.1};});
  FIELDS.forEach(([x0,z0,x1,z1])=>{for(let z=z0+.4;z<z1-.2;z+=.72)for(let x=x0+.3;x<x1-.2;x+=.38+r()*.22){if(villagePathDist(x,z)<PATH_W+.3)continue;
    const w=.42+r()*.16;deco.push({x:x+(r()-.5)*.2,z:z+(r()-.5)*.25,y:getHeight(x,z)-.05,w,h:w*22/12,spr:'wheat'+(r()*3|0),sway:.13,tint:.9+r()*.16});}});
  {const[cx0,cz0,cx1,cz1]=CEM;for(let z=cz0+3;z<cz1-2;z+=3.2)for(let x=cx0+3.5;x<cx1-2;x+=2.6){if(r()<.22||Math.abs(z-716)<1.6)continue;
    const k=(r()*3)|0,s=SPR['grave'+k],h=k===0?.8:k===1?1.05:1.0,gx=x+(r()-.5)*.4,gz=z+(r()-.5)*.4;
    deco.push({x:gx,z:gz,y:getHeight(gx,gz)-.08,w:h*s.w/s.h,h,spr:'grave'+k,tint:.85+r()*.2});addProp(gx,gz,.28);}}
  [[-70,800],[-68,803],[-71,806],[-88,770],[-58,790],[29.5,669.5],[14.5,654.5],[35,657.5]].forEach(([x,z])=>{deco.push({x,z,y:getHeight(x,z)-.1,w:1.4,h:1.4*15/22,spr:'hay',tint:.95+r()*.1});addProp(x,z,.6);});
  villageProps.forEach(p=>deco.push(p));
  decorMat=bbMaterial(atlas,0,0);
  const B=new Map();for(const d of deco){const k=Math.floor((d.x+HALF)/60)*1000+Math.floor((d.z-ZMIN)/60);if(!B.has(k))B.set(k,[]);B.get(k).push(d);}
  for(const[k,list]of B){const m=makeBillboards(list,decorMat);decoBuckets.push({m,cx:Math.floor(k/1000)*60-HALF+30,cz:(k%1000)*60+ZMIN+30});scene.add(m);}

