  for(const k in ITEMS)ITEMS[k].icon=SPR[k].c.toDataURL();setTimeout(()=>{try{initFPItems();}catch(e){console.error(e);}},0);
  setupVillagers();setupGuards(atlas);setupAnimals(atlas);initDrops();initNord(atlas);initWest(atlas);initStorm(atlas);initEast(atlas);initFrogVillage(atlas);initDesert(atlas);initSigns();setupMerchants(atlas);setupCoaches(atlas);fixGisbertDialog();initStory(atlas);setupStoryDialogs();initInteriors(atlas);initWitch(atlas);initFurn(atlas);initCaveMobs(atlas);initCaveLights();placeCaveEntrances();buildCaveEntrances2(atlas);initWorldTorches(atlas);initAnts();initEggs();initParticles();placeBoulders();
