function addProp(x,z,r){const t={x,z,type:'prop',h:1,w:1,r};const k=gk(x,z);if(!tgrid.has(k))tgrid.set(k,[]);tgrid.get(k).push(t);}
function syncPickups(){const a=pickupMesh.geometry.attributes.size;pickups.forEach((p,i)=>{a.array[i*2]=p.active?p.w:0;a.array[i*2+1]=p.active?p.h:0;});a.needsUpdate=true;}
const SKY_DAY=[new THREE.Color('#4a7fc0'),new THREE.Color('#b9d6cc')],SKY_DARK=[new THREE.Color('#1f2a30'),new THREE.Color('#2e3833')];
const SKY_STORM=[new THREE.Color('#3f4c5a'),new THREE.Color('#8d99a3')];
function applyMood(nf,sf=0){const n=1-DN.day;
  SKY_TOP.copy(SKY_DAY[0]).lerp(SKY_DARK[0],nf).lerp(SKY_STORM[0],sf);SKY_HOR.copy(SKY_DAY[1]).lerp(SKY_DARK[1],nf).lerp(SKY_STORM[1],sf);
  SKY_HOR.lerp(DUSK_HOR,DN.dusk*(1-nf)*.75);SKY_TOP.lerp(DUSK_TOP,DN.dusk*(1-nf)*.45);SKY_TOP.lerp(DN.nightTop,n);SKY_HOR.lerp(DN.nightHor,n);scene.fog.color.copy(SKY_HOR);
  const dl=DN.day+n*DN.nightLight;hemi.color.copy(DN.hemiCol);sun.color.copy(DN.sunCol);
  hemi.intensity=((.62-.32*nf)*(1-sf)+.55*sf)*dl;sun.intensity=((.72-.46*nf)*(1-sf)+.5*sf)*DN.day+n*DN.moonLight;
  const L=((1-.38*nf)*(1-sf)+.9*sf)*(.1+.9*dl);LIGHT_COL.copy(DN.tint);
  for(const m of[decorMat,pickMat,villMat,nordMat,westMat,stormMat,guardMat,playerMat,animalMat,dropMat,waterMat,mountMesh&&mountMesh.material,riderMesh&&riderMesh.material,spyMesh&&spyMesh.material,miniMesh&&miniMesh.material,...EXTRA_BB])if(m&&m.uniforms.light)m.uniforms.light.value=L;
  if(mountainMat)mountainMat.uniforms.dark.value=Math.max(nf,n*.85);if(P.x>60000)interiorMood();else sky.visible=true;}
function setFog(near,far){const rd=settings.renderDist||140;far=Math.min(far,rd);near=Math.min(near,far*(P.x>60000?.45:.9));scene.fog.near=near;scene.fog.far=far;for(const m of[decorMat,pickMat,waterMat,villMat,nordMat,westMat,stormMat,guardMat,playerMat,animalMat,dropMat,mountMesh&&mountMesh.material,riderMesh&&riderMesh.material,spyMesh&&spyMesh.material,miniMesh&&miniMesh.material,...EXTRA_BB]){if(!m)continue;m.uniforms.fogNear.value=near;m.uniforms.fogFar.value=far;}}

