const FISHCOL={perch:['#2e4a22','#4a6e30','#7a9a44','#b8c870','#c8402a'],trout:['#3a4450','#6a7684','#a8b0b8','#e0e4e8','#d87890'],carp:['#4a3010','#7a5420','#a87a34','#d0a85a','#8a4a1a'],
  pike:['#1e3218','#34522a','#5a7a3a','#a8b870','#d8d0a0'],goldfish:['#8a3a08','#c86010','#f08a1a','#ffc040','#fff0a0']};
function drawFish(id){const long=id==='pike',W=long?20:16,H=long?8:10,p=new Px(W,H),C=pal(FISHCOL[id]),cy=H/2-.5,bl=long?13:10.5,rx=bl/2,ry=long?2.4:3.4,cx=1+rx;
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const dx=(x-cx)/rx,dy=(y-cy)/ry;if(dx*dx+dy*dy<=1){let L=.7-dy*.45+(hash2(x,y,5)-.5)*.12;
      if(id==='perch'&&x>2&&x<bl&&(x%3===0))L-=.35;if((id==='trout'||id==='pike')&&hash2(x>>1,y,id.length)<.2)L-=.3;if(id==='goldfish')L+=.1;
      p.set(x,y,C[Math.max(0,Math.min(3,Math.round(L*3)))]);}}
  // Schwanzflosse
  const tx=cx+rx;for(let k=0;k<4;k++){for(let o=-k-1;o<=k+1;o++)p.set(tx+k,cy+o*.8,C[k<2?2:1]);}
  // Rückenflosse
  for(let x=Math.round(cx-2);x<=Math.round(cx+1);x++)p.set(x,cy-ry-.6,hex(FISHCOL[id][4]));
  p.set(cx-rx*.62,cy-.8,hex('#101010'));p.set(cx-rx*.62+1,cy-.8,hex('#f0f0f0'));
  outline(p);return p.done();}
function drawRod(){const p=new Px(16,16),W=pal(['#3a2410','#6a4420','#9a6a34','#c89a5a']);
  for(let k=0;k<15;k++){const x=1+k,y=14-k;p.set(x,y,W[k<4?0:k<9?1:2]);if(k<6)p.set(x+1,y,W[1]);}
  p.set(4,11,hex('#888c94'));p.set(5,12,hex('#5a5e66'));p.set(4,12,hex('#aab0b8'));
  for(let y=1;y<12;y++)p.set(15,y,hex('#d8d8d8'));p.set(15,12,hex('#c83020'));p.set(15,13,hex('#f0f0f0'));
  outline(p);return p.done();}

