const FROG_SHORE=[];
for(let k=0;k<30;k++){const a=k/30*6.2832,x=FROG.x+Math.cos(a)*(FROG.r+1.6),z=FROG.z+Math.sin(a)*(FROG.r+1.6);if(x<riverX2(z)+10||frogClear(x,z))continue;FROG_SHORE.push({x,z});}
const frogs=[];let frogMesh=null,frogMat=null,frogFishers=[];
function frogSprites(list){
  list.push(['rod',drawRod2()]);for(const id of['perch','trout','carp','pike','goldfish'])list.push([id,drawFish(id)]);
  FROG_FOLK.forEach((f,i)=>{const L=frogLook(f),c0=drawHero(L,0);
    for(let fr=0;fr<3;fr++)list.push(['fg'+i+'_'+fr,fr?drawHero(L,fr):c0]);
    list.push(['fg'+i+'_c',squashCv(c0,1.14,.8)]);list.push(['fg'+i+'_l',squashCv(drawHero(L,1),.9,1.1)]);
    if(f[8]==='fish'){const cv=document.createElement('canvas');cv.width=44;cv.height=60;const ctx=cv.getContext('2d');ctx.drawImage(c0,0,0);
      const[hx,hy]=c0.handR,W=['#3a2410','#6a4420','#9a6a34'];for(let k=0;k<=24;k++){const t=k/24,x=Math.round(hx+(41-hx)*t),y=Math.round(hy+(6-hy)*t);ctx.fillStyle=W[t<.3?0:t<.7?1:2];ctx.fillRect(x,y,1,1);if(t<.3){ctx.fillStyle=W[0];ctx.fillRect(x,y+1,1,1);}}
      ctx.fillStyle='#888c94';ctx.fillRect(hx+1,hy-2,2,2);list.push(['fg'+i+'_r',cv]);list.push(['fg'+i+'_rc',squashCv(cv,1.08,.88)]);}});}
function squashCv(cv,sx,sy){const o=document.createElement('canvas');o.width=cv.width;o.height=cv.height;const ctx=o.getContext('2d');ctx.imageSmoothingEnabled=false;
  const w=Math.round(cv.width*sx),h=Math.round(cv.height*sy);ctx.drawImage(cv,Math.round((cv.width-w)/2),cv.height-h,w,h);
  for(const k of['headBox','waist','legTop','handL','handR'])if(cv[k]!=null)o[k]=cv[k];return o;}
function frogPortrait(L){const pc=portraitOf(L),o=document.createElement('canvas');o.width=o.height=22;const ctx=o.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(pc,0,0,22,22);return o;}

/* ---- Bauten: Seewasser, Seerosen, Hütten, Steg ---- */
function frogTex(c,rep){const t=new THREE.CanvasTexture(c);t.magFilter=THREE.NearestFilter;t.minFilter=THREE.NearestFilter;t.generateMipmaps=false;if(rep){t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rep[0],rep[1]);}return t;}
const LILY=pal(['#173c16','#245a20','#33782c','#4c9638','#6cb44c']);
function drawLilyPad(flower){const S=32,p=new Px(S,S),c=15.5;
  for(let y=0;y<S;y++)for(let x=0;x<S;x++){const dx=x-c,dy=y-c,d=Math.hypot(dx,dy);if(d>15)continue;const a=Math.atan2(dy,dx);if(Math.abs(a)<.22&&d>1.5)continue;
    let L=.62-(dx+dy)/60+(hash2(x,y,41)-.5)*.16;const va=((a+Math.PI)/(Math.PI*2)*9)%1;if(va<.06||va>.94)L-=.22;if(d>13.6)L-=.25;if(d<2)L-=.1;
    p.set(x,y,LILY[shadeIdx(L,LILY.length,x,y)]);}
  if(flower){const PK=pal(['#c06a8a','#e08aa8','#f4b8cc','#fff0f4']),fx=c-4,fy=c+2;
    for(let y=-4;y<=4;y++)for(let x=-4;x<=4;x++){const d=Math.hypot(x,y),a=Math.atan2(y,x),pet=.65+.35*Math.cos(a*6);if(d<4.2*pet)p.set(fx+x,fy+y,PK[shadeIdx(.8-d/6-(x+y)/14,PK.length,x,y)]);}
    for(let y=-1;y<=1;y++)for(let x=-1;x<=1;x++)p.set(fx+x,fy+y,hex(x||y?'#e8b020':'#ffe060'));}
  return p.done();}
function drawMud(){const W=64,H=32,p=new Px(W,H),M=pal(['#3a2614','#4e3520','#644630','#7a5a3c','#8e6c48']);
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){let L=.5+(vnoise(x*.12,y*.5,611)-.5)*.7+(hash2(x,y,612)-.5)*.25;if(y%8===0&&hash2(x>>2,y,613)<.7)L-=.25;
    p.set(x,y,M[shadeIdx(L,M.length,x,y)]);if(hash2(x,y,614)<.025)p.set(x,y,hex('#b8a060'));if(hash2(x,y,615)<.012)p.set(x,y,hex('#9a9890'));}
  return p.done();}
function drawLeafRoof(){const W=48,H=24,p=new Px(W,H);
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const cell=Math.floor(x/12)+Math.floor(y/12)*7,cx=Math.floor(x/12)*12+6+(hash2(cell,1,9)-.5)*4,cy=Math.floor(y/12)*12+6,d=Math.hypot(x-cx,y-cy);
    let L=.6+(hash2(x,y,621)-.5)*.2-d*.03;if(Math.abs(x-cx)<.6||Math.abs(y-cy)<.6)L-=.18;if(y%12===11)L-=.3;p.set(x,y,LILY[shadeIdx(L,LILY.length,x,y)]);}
  return p.done();}
function drawFrogDoor(){const p=new Px(16,24),D=hex('#140c06'),F=pal(['#2a1a0c','#3e2814','#55381e']);
  for(let y=0;y<24;y++)for(let x=0;x<16;x++){const dx=(x-7.5)/7.5,top=y<8?Math.sqrt(Math.max(0,1-((8-y)/8)**2)):1;if(Math.abs(dx)>top)continue;const edge=Math.abs(dx)>top-.22||y<1;p.set(x,y,edge?F[(hash2(x,y,3)*3)|0]:D);}
  return p.done();}
function drawPlanks(){const p=new Px(32,8),W=pal(['#3a2615','#54381f','#6e4b2a','#8a6236','#a77a45']);
  for(let y=0;y<8;y++)for(let x=0;x<32;x++){let L=.55+(vnoise(x*.3,y*1.5,61)-.5)*.5+(hash2(x,y,62)-.5)*.2;if(y===0)L+=.25;if(y===7)L=.05;p.set(x,y,W[shadeIdx(L,W.length,x,y)]);}
  return p.done();}
function frogProp(x,z,r,h){const t={x,z,type:'prop',h,w:1,r,frog:true};const k=gk(x,z);if(!tgrid.has(k))tgrid.set(k,[]);tgrid.get(k).push(t);}
let frogDecoMat=null;
function initFrogVillage(atlas){
  const ph=(o)=>new THREE.MeshPhongMaterial(Object.assign({flatShading:true,shininess:0,specular:0x000000},o));
  // Seewasser (an der Westseite bündig mit dem Fluss)
  {const pos=[FROG.x,WATER,FROG.z],idx=[],N=72,R=FROG.r+2;for(let k=0;k<N;k++){const a=k/N*6.2832,z=FROG.z+Math.sin(a)*R;let x=FROG.x+Math.cos(a)*R;x=Math.max(x,riverX2(z)+7.5);pos.push(x,WATER,z);idx.push(0,1+k,1+(k+1)%N);}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setIndex(idx);scene.add(new THREE.Mesh(g,waterMat));}
  // Seerosen
  {const mats=[false,true].map(f=>new THREE.MeshLambertMaterial({map:frogTex(drawLilyPad(f)),alphaTest:.5,side:THREE.DoubleSide}));
    for(const p of FROG_PADS){const g=new THREE.PlaneGeometry(p.r*2.15,p.r*2.15);g.rotateX(-Math.PI/2);g.rotateY(p.rot);const m=new THREE.Mesh(g,mats[p.fl?1:0]);m.position.set(p.x,FROG_PAD_Y,p.z);scene.add(m);}}
  // Hütten aus Lehm mit Seerosendach
  const mud=ph({map:frogTex(drawMud(),[3,1])}),mudS=ph({map:frogTex(drawMud(),[1,1])}),leaf=ph({map:frogTex(drawLeafRoof(),[4,1])}),leafS=ph({map:frogTex(drawLeafRoof(),[1,1])}),
    door=new THREE.MeshLambertMaterial({map:frogTex(drawFrogDoor()),alphaTest:.5,side:THREE.DoubleSide}),deco=[];
  for(const H of FROG_HUTS){const y0=getHeight(H.x,H.z)-.15,grp=new THREE.Group();grp.position.set(H.x,y0,H.z);
    const dome=new THREE.Mesh(new THREE.SphereGeometry(H.R,20,10,0,Math.PI*2,0,Math.PI/2),mud);dome.scale.y=1.15;grp.add(dome);
    const cap=new THREE.Mesh(new THREE.SphereGeometry(H.R*1.08,20,6,0,Math.PI*2,0,.82),leaf);cap.scale.y=1.12;cap.position.y=-.16;grp.add(cap);
    const rim=new THREE.Mesh(new THREE.CylinderGeometry(H.R*.82,H.R*.98,.14,20,1,true),leafS);rim.position.y=H.R*1.12*Math.cos(.82)-.22;grp.add(rim);
    const dx=FROG.x-H.x,dz=FROG.z-H.z,dl=Math.hypot(dx,dz),ux=dx/dl,uz=dz/dl,ry=Math.atan2(ux,uz),pd=H.R*.8;
    const porch=new THREE.Mesh(new THREE.BoxGeometry(1.35,1.75,1.3),mudS);porch.position.set(ux*pd,.87,uz*pd);porch.rotation.y=ry;grp.add(porch);
    const lid=new THREE.Mesh(new THREE.BoxGeometry(1.75,.14,1.6),leafS);lid.position.set(ux*(pd+.1),1.8,uz*(pd+.1));lid.rotation.y=ry;lid.rotation.x=.12;grp.add(lid);
    const dr=new THREE.Mesh(new THREE.PlaneGeometry(.85,1.3),door);dr.position.set(ux*(pd+.66),.7,uz*(pd+.66));dr.rotation.y=ry;grp.add(dr);
    scene.add(grp);frogProp(H.x,H.z,H.R*.95,H.R*1.15-.15);frogProp(H.x+ux*(pd+.25),H.z+uz*(pd+.25),.8,1.8);
    deco.push({x:H.x,z:H.z,y:y0+H.R*1.08*1.12-.22,w:.38,h:.5,spr:'flower'+(Math.abs(H.a*7|0)%4),sway:.04,tint:1});
    for(let k=0;k<5;k++){const a=H.a+Math.PI*.5+k*.45,x=H.x+Math.cos(a)*(H.R+.4),z=H.z+Math.sin(a)*(H.R+.4);deco.push({x,z,y:getHeight(x,z)-.08,w:.7,h:1.3,spr:'reed'+(k&1),sway:.1,tint:.95});}}
  // Steg
  {const tex=frogTex(drawPlanks()),mats=[.8,.92,1.04].map(k=>ph({map:tex,color:new THREE.Color(k,k,k)})),dark=ph({map:tex,color:new THREE.Color(.55,.5,.45)}),grp=new THREE.Group(),P_=FROG_PIER;
    grp.position.set(P_.x0,0,P_.z0);grp.rotation.y=Math.atan2(P_.dx,P_.dz);
    const plank=new THREE.BoxGeometry(P_.hw*2+.1,.12,.44);for(let s=.25;s<P_.L;s+=.5){const m=new THREE.Mesh(plank,mats[(hash2((s*2)|0,7,3)*3)|0]);m.position.set((hash2((s*2)|0,8,3)-.5)*.08,FROG.deck-.06,s);grp.add(m);}
    const post=new THREE.BoxGeometry(.2,2.9,.2);for(const s of[.6,3.8,7,P_.L-.3])for(const q of[-1,1]){const m=new THREE.Mesh(post,dark);m.position.set(q*(P_.hw-.05),FROG.deck-1.25+(s>P_.L-1?.35:0),s);grp.add(m);}
    const beam=new THREE.BoxGeometry(.14,.18,P_.L);for(const q of[-1,1]){const m=new THREE.Mesh(beam,dark);m.position.set(q*(P_.hw-.05),FROG.deck-.2,P_.L/2);grp.add(m);}
    scene.add(grp);
    const[cx,cz]=pierWorld(-1.2,2.1),crate=new THREE.Mesh(new THREE.BoxGeometry(.8,.7,.8),mats[1]);crate.position.set(cx,getHeight(cx,cz)+.3,cz);crate.rotation.y=grp.rotation.y;scene.add(crate);frogProp(cx,cz,.5,.65);}
  // ein paar Kisten-Fische am Stand
  {const[x,z]=pierWorld(-1.2,2.1),y=getHeight(x,z)+.62;for(let k=0;k<3;k++)deco.push({x:x+(k-1)*.18,z,y,w:.32,h:.2,spr:['perch','trout','carp'][k],tint:1});}
  frogDecoMat=bbMaterial(atlas,0,0);EXTRA_BB.push(frogDecoMat);scene.add(makeBillboards(deco,frogDecoMat));
  // Das Froschvolk
  const fishSpots=[[FROG_PIER.L-.55,0,FROG_PIER.L+4.5,0],[FROG_PIER.L-3.3,-.72,FROG_PIER.L-3.3,-4.6],[4.6,.72,4.6,4.4]];let fi=0;
  FROG_FOLK.forEach((f,i)=>{const L=frogLook(f),c0=SPR['fg'+i+'_0'].c,top=c0.headBox[2]-2,kid=f[2]==='kid',hh=(kid?1.08:1.62)*60/(60-top),v={i,name:f[0],role:f[3],job:f[8],kid,
      d:{kid,elder:f[2]==='old',id:'fg'+i},look:L,h:hh,w:hh*44/60,x:0,z:0,y:0,frame:'0',wait:Math.random()*3,anim:Math.random()*2,talk:0,chatCd:Math.random()*20,hop:null,walk:false,frog:true};
    v.portrait=frogPortrait(L);
    if(f[8]==='fish'){const[s,q,bs,bq]=fishSpots[fi++];[v.x,v.z]=pierWorld(s,q);v.y=FROG.deck;[v.bx,v.bz]=pierWorld(bs,bq);v.frame='r';v.biteT=8+Math.random()*25;frogFishers.push(v);}
    else if(f[8]==='trader'){[v.x,v.z]=pierWorld(-1.4,-1.9);v.ax=v.x;v.az=v.z;v.rad=1.6;}
    else{const S=FROG_SHORE[(i*7)%FROG_SHORE.length];v.x=S.x;v.z=S.z;}
    if(!v.y)v.y=groundAt(v.x,v.z,9);frogs.push(v);});
  frogMat=bbMaterial(atlas,0,0);EXTRA_BB.push(frogMat);
  frogMesh=makeBillboards(frogs.map(v=>({x:v.x,y:v.y,z:v.z,w:v.w,h:v.h,spr:'fg'+v.i+'_'+v.frame,tint:1})),frogMat);scene.add(frogMesh);
  // Schwimmer und Schnüre der Fischer
  const bobG=new THREE.SphereGeometry(.075,8,6),bobM=new THREE.MeshLambertMaterial({color:0xd8301e}),lineM=new THREE.LineBasicMaterial({color:0xe6e6e6,transparent:true,opacity:.75});
  for(const v of frogFishers){v.bob=new THREE.Mesh(bobG,bobM);v.bob.position.set(v.bx,WATER+.03,v.bz);scene.add(v.bob);
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(6),3));v.line=new THREE.Line(g,lineM);v.line.frustumCulled=false;scene.add(v.line);}
  initFishing(bobG,bobM,lineM);initPond();ITEMS.rod.fp=drawRodFP().toDataURL();
}
const _ft=new THREE.Vector3();
// Spitze der Angel im Billboard eines Fischers: Pixel (41,6) im 44×60-Bild
function fisherTip(v,out){const dx=camera.position.x-v.x,dz=camera.position.z-v.z,l=Math.hypot(dx,dz)||1,rx=dz/l,rz=-dx/l,ox=(41.5/44-.5)*v.w,oy=(1-6/60)*v.h;
  return out.set(v.x+rx*ox,v.y+oy,v.z+rz*ox);}
function frogSplash(x,z,n,y){for(let k=0;k<n;k++){const a=Math.random()*6.283,s=.4+Math.random()*1.1;spawnParticle(x,(y==null?WATER:y)+.05,z,Math.cos(a)*s,1.6+Math.random()*1.8,Math.sin(a)*s,0xd6ecf4,.45+Math.random()*.3);}}
function frogPlop(big){const c=Snd.ctx;if(!c)return;const t=c.currentTime,{o}=Snd.tone('sine',big?560:760,t,.13,big?.16:.08);o.frequency.exponentialRampToValueAtTime(big?150:280,t+.13);}
function frogQuak(){const c=Snd.ctx;if(!c)return;const t=c.currentTime;for(let k=0;k<2;k++){const{o}=Snd.tone('sawtooth',170+Math.random()*40,t+k*.16,.12,.03,null,700);o.frequency.exponentialRampToValueAtTime(110,t+k*.16+.12);}}

/* ---- Bewegung: Gehen und Hüpfen ---- */
function frogLandOK(x,z){if(getHeight(x,z)<WATER+.3)return false;for(const H of FROG_HUTS)if(Math.hypot(x-H.x,z-H.z)<H.R+.9)return false;const d=Math.hypot(x-FROG.x,z-FROG.z);return d>FROG.r+1&&d<FROG.r+19;}
function frogHop(v,x,z){const d=Math.hypot(x-v.x,z-v.z),ey=groundAt(x,z,9);v.hop={t:0,c:.22,air:.42+d*.05,sx:v.x,sz:v.z,sy:v.y,ex:x,ez:z,ey,ht:(v.kid?.45:.6)+d*.13};v.walk=false;}
function frogPlan(v){
  if(v.job==='trader'){if(Math.random()<.5){for(let k=0;k<6;k++){const a=Math.random()*6.283,r=Math.random()*v.rad,x=v.ax+Math.cos(a)*r,z=v.az+Math.sin(a)*r;if(getHeight(x,z)>WATER+.3){if(Math.random()<.5)frogHop(v,x,z);else{v.tx=x;v.tz=z;v.walk=true;}return;}}}v.wait=2+Math.random()*4;return;}
  const spots=[];const onWater=onFrogPad(v.x,v.z);
  if(v.job==='hop'&&(Math.random()<.85||onWater)){for(const p of FROG_PADS){const d=Math.hypot(p.x-v.x,p.z-v.z);if(d>1.4&&d<5.2)spots.push([p.x+(Math.random()-.5)*p.r*.6,p.z+(Math.random()-.5)*p.r*.6,3]);}
    for(const s of FROG_SHORE){const d=Math.hypot(s.x-v.x,s.z-v.z);if(d>1.4&&d<5.2)spots.push([s.x,s.z,1]);}
    if(spots.length){let tot=spots.reduce((a,s)=>a+s[2],0),r=Math.random()*tot;for(const s of spots){r-=s[2];if(r<=0){frogHop(v,s[0],s[1]);return;}}}
    if(!onWater){let best=null,bd=1e9;for(const s of FROG_SHORE){const d=Math.hypot(s.x-v.x,s.z-v.z);if(d<bd&&d>.5){bd=d;best=s;}}if(best){v.tx=best.x;v.tz=best.z;v.chain=true;frogStep(v);return;}}}
  if(onWater){let best=null,bd=1e9;for(const p of FROG_PADS.concat(FROG_SHORE)){const d=Math.hypot(p.x-v.x,p.z-v.z);if(d>1&&d<bd){bd=d;best=p;}}if(best){frogHop(v,best.x,best.z);return;}}
  for(let k=0;k<12;k++){const a=Math.random()*6.283,r=FROG.r+2+Math.random()*16,x=FROG.x+Math.cos(a)*r,z=FROG.z+Math.sin(a)*r;if(Math.hypot(x-v.x,z-v.z)>14||!frogLandOK(x,z))continue;
    v.tx=x;v.tz=z;if(Math.random()<(v.kid?.7:.4)){v.chain=true;frogStep(v);}else v.walk=true;return;}
  v.wait=1+Math.random()*2;}
function frogStep(v){const dx=v.tx-v.x,dz=v.tz-v.z,d=Math.hypot(dx,dz);if(d<.3){v.chain=false;v.wait=1+Math.random()*(v.kid?2:5);return;}
  const s=Math.min(d,(v.kid?2.2:2.6)+Math.random()*.9);frogHop(v,v.x+dx/d*s,v.z+dz/d*s);}
function frogPush(v){for(const H of FROG_HUTS){const dx=v.x-H.x,dz=v.z-H.z,d=Math.hypot(dx,dz),m=H.R+.35;if(d<m&&d>1e-3){v.x=H.x+dx/d*m;v.z=H.z+dz/d*m;}}}
function updateFrogs(dt){if(!frogMesh)return;
  const cx=camera.position.x,cz=camera.position.z,far=Math.hypot(cx-FROG.x,cz-FROG.z)>SIM()+FROG.r+30;if(far)return;
  const off=frogMesh.geometry.attributes.offset,uvr=frogMesh.geometry.attributes.uvr,near=Math.hypot(P.x-FROG.x,P.z-FROG.z)<FROG.r+30;
  for(const v of frogs){
    if(v.job==='fish'){v.biteT-=dt;let by=WATER+.03+Math.sin(time*2+v.i)*.012;
      if(v.biteT<0&&v.biteT>-1){by-=.08+Math.sin(time*28)*.03;}
      else if(v.biteT<=-1&&v.biteT>-1.5){v.frame='rc';if(!v.caught){v.caught=true;if(near){frogSplash(v.bx,v.bz,8);frogPlop(true);if(Math.random()<.4&&Math.hypot(P.x-v.x,P.z-v.z)<14)say(v,['Quaak! Ein Barsch!','Hab einen!','Eine Forelle! Quak!','Schon wieder nur ein kleiner ...'][(Math.random()*4)|0],2.5);}}}
      else if(v.biteT<=-1.5){v.biteT=12+Math.random()*30;v.frame='r';v.caught=false;}
      if(v.talk>0)v.talk-=dt;
      v.bob.position.y=by;fisherTip(v,_ft);const a=v.line.geometry.attributes.position.array;a[0]=_ft.x;a[1]=_ft.y;a[2]=_ft.z;a[3]=v.bx;a[4]=by+.06;a[5]=v.bz;v.line.geometry.attributes.position.needsUpdate=true;}
    else if(v.talk>0){v.talk-=dt;v.frame='0';v.hop=null;v.walk=false;}
    else if(v.hop){const H=v.hop;H.t+=dt;
      if(H.t<H.c)v.frame='c';
      else if(H.t<H.c+H.air){const u=(H.t-H.c)/H.air;v.x=H.sx+(H.ex-H.sx)*u;v.z=H.sz+(H.ez-H.sz)*u;v.y=H.sy+(H.ey-H.sy)*u+4*H.ht*u*(1-u);v.frame='l';}
      else if(H.t<H.c+H.air+.15){if(!H.landed){H.landed=true;v.x=H.ex;v.z=H.ez;frogPush(v);v.y=H.ey;if(near&&H.ey<WATER+.2&&Math.random()<.5)frogSplash(v.x,v.z,3,H.ey);}v.frame='c';}
      else{v.hop=null;v.frame='0';if(v.chain){v.wait=.12+Math.random()*.35;}else v.wait=.6+Math.random()*(v.kid?1.5:4);}}
    else if(v.wait>0){v.wait-=dt;v.frame='0';if(v.wait<=0){if(v.chain)frogStep(v);else frogPlan(v);}}
    else if(v.walk){const dx=v.tx-v.x,dz=v.tz-v.z,d=Math.hypot(dx,dz);
      if(d<.25){v.walk=false;v.wait=1+Math.random()*5;v.frame='0';}
      else{const st=Math.min(d,(v.kid?1.3:.85)*dt),ox=v.x,oz=v.z;v.x+=dx/d*st;v.z+=dz/d*st;frogPush(v);if(Math.hypot(P.x-v.x,P.z-v.z)<.62){v.x=ox;v.z=oz;}
        if(Math.hypot(v.x-ox,v.z-oz)<st*.3){v.stuck=(v.stuck||0)+dt;if(v.stuck>.8){v.stuck=0;v.walk=false;v.wait=.5;}}else v.stuck=0;
        v.anim+=st*2.2;v.frame=String(1+(Math.floor(v.anim)%2));v.y=groundAt(v.x,v.z,v.y+.5);}}
    else frogPlan(v);
    // Plaudern
    if(near&&state==='playing'&&!v.talk){v.chatCd-=dt;if(v.chatCd<=0){v.chatCd=6+Math.random()*10;const d=Math.hypot(P.x-v.x,P.z-v.z);
      if(d<7&&Math.random()<.35&&!bubbles.some(b=>b.v===v)){const L=LINES[v.role]||LINES.Froschmann;say(v,L[(Math.random()*L.length)|0],3);if(Math.random()<.6)frogQuak();}}}
    const k=v.i;off.array[k*3]=v.x;off.array[k*3+1]=v.y-.03;off.array[k*3+2]=v.z;const s=SPR['fg'+k+'_'+v.frame]||SPR['fg'+k+'_0'];uvr.array[k*4]=s.u;uvr.array[k*4+1]=s.v;}
  off.needsUpdate=true;uvr.needsUpdate=true;}
function frogLooked(){if(Math.abs(P.x-FROG.x)>FROG.r+40||Math.abs(P.z-FROG.z)>FROG.r+40)return null;const dir=lookDir(),ex=P.x,ey=P.y+P.eye,ez=P.z;let best=3.2,hit=null;
  for(const v of frogs){const dx=v.x-ex,dy=v.y+v.h*.45-ey,dz=v.z-ez,d=Math.hypot(dx,dy,dz);if(d>best)continue;if((dx*dir.x+dy*dir.y+dz*dir.z)/d<.8)continue;best=d;hit=v;}return hit;}

/* ---- Angeln ---- */
const fish={st:'none',x:0,z:0,sx:0,sy:0,sz:0,t:0,wait:0,bite:0};let fishBob=null,fishLine=null;const _rt=new THREE.Vector3();
function initFishing(bobG,bobM,lineM){fishBob=new THREE.Mesh(bobG,bobM);fishBob.visible=false;scene.add(fishBob);
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(6),3));fishLine=new THREE.Line(g,lineM);fishLine.frustumCulled=false;fishLine.visible=false;scene.add(fishLine);}
function rodTip(out){if(!(P.view||0)){camera.updateMatrixWorld();if(fpRodTip(out))return out;out.set(.34,.12,-.95);return camera.localToWorld(out);}
  const s=Math.sin(P.yaw),c=Math.cos(P.yaw),sz=P.mods?P.mods.size:1;return out.set(P.x+c*.5-s*.6,P.y+1.9*sz,P.z-s*.5-c*.6);}
function useRod(){P.lastAction=time;
  if(fish.st==='bite'){catchFish();return;}
  if(fish.st!=='none'){fish.st='none';Snd.click();return;}
  if(P.riding){toast('Vom Sattel aus kannst du nicht angeln');return;}
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw);let tx=null,tz=0;
  for(let d=8;d>=2.5;d-=.5){const x=P.x+fx*d,z=P.z+fz*d;if(nearWater(x,z)&&getHeight(x,z)<WATER-.25&&!onFrogPad(x,z)){tx=x;tz=z;break;}}
  if(tx===null){toast('Hier ist kein Wasser zum Angeln');return;}
  rodTip(_rt);fish.sx=_rt.x;fish.sy=_rt.y;fish.sz=_rt.z;fish.x=tx;fish.z=tz;fish.st='cast';fish.t=0;Snd.jump();}
function catchFish(){let r=Math.random()*100,id='perch';for(const[k,w]of FISH_TABLE){if(r<w){id=k;break;}r-=w;}
  if(addItem(id,1))spawnDrop(id,1,P.x,P.y+1,P.z);frogSplash(fish.x,fish.z,14);frogPlop(true);Snd.pickup();fish.st='none';
  toast((id==='goldfish'?'Ein Goldfisch! ':'')+ITEMS[id].name+' gefangen!');gainXP(id==='goldfish'?25:id==='pike'?10:5);wearTool();}
function updateFishing(dt){if(!fishBob)return;const h=inv[HOT0+sel];
  if(fish.st!=='none'&&(!h||h.id!=='rod'||state==='menu'||P.riding||Math.hypot(fish.x-P.x,fish.z-P.z)>14))fish.st='none';
  const on=fish.st!=='none';fishBob.visible=fishLine.visible=on;if(!on)return;
  fish.t+=dt;let bx=fish.x,bz=fish.z,by=WATER+.03;
  if(fish.st==='cast'){const u=Math.min(1,fish.t/.55);bx=fish.sx+(fish.x-fish.sx)*u;bz=fish.sz+(fish.z-fish.sz)*u;by=fish.sy+(WATER+.03-fish.sy)*u+2.4*u*(1-u);
    if(u>=1){fish.st='wait';fish.wait=4+Math.random()*9;frogSplash(fish.x,fish.z,6);frogPlop(false);}}
  else if(fish.st==='wait'){fish.wait-=dt;by+=Math.sin(time*2.3)*.014;if(fish.wait<1.4)by-=Math.max(0,Math.sin(time*19))*.025;
    if(fish.wait<=0){fish.st='bite';fish.bite=1.05+Math.random()*.4;frogSplash(fish.x,fish.z,6);frogPlop(true);}}
  else if(fish.st==='bite'){fish.bite-=dt;by-=.11+Math.sin(time*30)*.035;if(Math.random()<dt*10)frogSplash(fish.x,fish.z,1);if(fish.bite<=0){fish.st='wait';fish.wait=3+Math.random()*8;}}
  fishBob.position.set(bx,by,bz);rodTip(_rt);const a=fishLine.geometry.attributes.position.array;a[0]=_rt.x;a[1]=_rt.y;a[2]=_rt.z;a[3]=bx;a[4]=by+.06;a[5]=bz;fishLine.geometry.attributes.position.needsUpdate=true;}

/* ---- Quorg, der Händler ---- */
DIALOGS.Quorg={start:()=>'hello',nodes:{
  hello:()=>({text:FLAGS.metQuorg?'Quaak! Wieder da, Langbein? Der See ist heute voller Fische.':'Quaak! Ein Langbein im Froschdorf! Ich bin Quorg, der Älteste hier und Händler obendrein. Wir sind ein friedliches Volk. Wir hüpfen, wir fischen, und nachts singen wir.',
    enter:()=>{FLAGS.metQuorg=1;},
    opts:[{label:'Lass uns handeln.',act:()=>{openShop('Quorg');return null;}},{label:'Wie angelt man hier?',go:'fish'},{label:'Erzähl mir vom Froschdorf.',go:'village'},{label:'Leb wohl.',go:null}]}),
  fish:()=>({text:'Mit einer Angel aus meinem Schilf! Stell dich ans Ufer oder auf den Steg und wirf aus. Wenn der Schwimmer zuckt und untertaucht, holst du sofort ein. Zu langsam, und der Fisch lacht dich aus.',
    opts:[{label:'Und welche Fische kaufst du?',go:'buyfish'},{label:'Zurück',go:'hello'}]}),
  buyfish:()=>({text:'Alle! Barsche, Forellen, Karpfen. Ein Hecht ist selten. Und wer einen Goldfisch fängt, hat Glück für ein ganzes Jahr. Den bezahle ich fürstlich.',opts:[{label:'Zurück',go:'hello'}]}),
  village:()=>({text:'Unsere Hütten bauen wir aus Lehm vom Seegrund, die Dächer aus Seerosenblättern. Das hält trocken und riecht nach Zuhause. Die Kinder hüpfen den ganzen Tag über die Seerosen. Ihr Langbeine könnt das auch, wenn ihr euch traut.',
    opts:[{label:'Zurück',go:'hello'}]})}};

/* ---- Angel: schöneres Symbol und eigene Ansicht in der Hand ---- */
function drawRod2(){const p=new Px(16,16),W=pal(['#3a2410','#5e3c1c','#86582c','#b07c44']),CK=pal(['#7a5a34','#a07a4a','#c8a06a']),G=hex('#b8bcc4');
  for(let k=0;k<12;k++){const x=3+k,y=12-k;p.set(x,y,W[k<5?1:2]);}
  for(let k=0;k<4;k++){p.set(1+k,15-k,CK[(k&1)?1:2]);p.set(2+k,15-k,CK[0]);}
  p.set(4,13,hex('#5a5e66'));p.set(5,14,hex('#8a8e96'));p.set(4,14,G);
  p.set(7,8,G);p.set(10,5,G);p.set(15,0,W[3]);
  for(let y=1;y<10;y++)p.set(15,y,hex('#e2e2e2'));p.set(15,10,hex('#d23020'));p.set(15,11,hex('#f4f4f4'));
  outline(p);return p.done();}
function drawRodFP(){const W=44,H=64,p=new Px(W,H),WD=pal(['#2e1c0c','#4a2e16','#6e4624','#94643a','#b88a56']),CK=pal(['#6a4a28','#8e6a40','#b08a5a','#cfac7c']),MT=pal(['#2a2c30','#4e5258','#7a8088','#b0b6be']);
  const A=[41,63],B=[1,1],len=Math.hypot(B[0]-A[0],B[1]-A[1]);
  for(let i=0;i<=len;i+=.5){const t=i/len,x=A[0]+(B[0]-A[0])*t,y=A[1]+(B[1]-A[1])*t,th=t<.28?3.2:t<.55?2:t<.8?1.4:1;
    for(let o=-th/2;o<=th/2;o+=.5){const px=x+o*.85,py=y-o*.55,lit=o<0?.75:.4;
      if(t<.28){const band=Math.floor(i/2.2)%2;p.set(px,py,CK[shadeIdx(lit+(band?.1:-.1),CK.length,px|0,py|0)]);}
      else p.set(px,py,WD[shadeIdx(lit+(t>.9?.2:0),WD.length,px|0,py|0)]);}}
  // Wicklung zwischen Griff und Rute
  for(let i=0;i<4;i++){const t=.28+i*.01,x=A[0]+(B[0]-A[0])*t,y=A[1]+(B[1]-A[1])*t;for(let o=-1.5;o<=1.5;o+=.5)p.set(x+o*.85,y-o*.55,hex(i%2?'#7a1a14':'#a42a1e'));}
  // Rolle
  const rx=A[0]+(B[0]-A[0])*.2+5,ry=A[1]+(B[1]-A[1])*.2+1;for(let y=-5;y<=5;y++)for(let x=-4;x<=4;x++){const d=Math.hypot(x/4,y/5);if(d<=1)p.set(rx+x,ry+y,MT[shadeIdx(.7-x*.06-y*.05+(d>.75?-.3:0),MT.length,x,y)]);}
  for(let y=-2;y<=2;y++)p.set(rx,ry+y,MT[0]);p.set(rx+4,ry-2,MT[3]);p.set(rx+5,ry-3,MT[3]);p.set(rx+6,ry-3,hex('#3a2a1a'));p.set(rx+6,ry-4,hex('#3a2a1a'));
  for(let k=0;k<3;k++){p.set(rx-4-k,ry-3-k,MT[2]);}
  // Ringe
  for(const t of[.42,.58,.72,.85,.95]){const x=A[0]+(B[0]-A[0])*t,y=A[1]+(B[1]-A[1])*t;p.set(x+1.2,y+.6,MT[3]);p.set(x+1.8,y+1.2,MT[2]);}
  // Schnur von der Rolle an der Rute entlang
  for(let i=0;i<len*.78;i+=1){const t=.2+i/len,x=A[0]+(B[0]-A[0])*t+1.5,y=A[1]+(B[1]-A[1])*t+.9;if(t<.98)p.set(x,y,hex('#e8e8e8'));}
  outline(p);return p.done();}
function fpRodTip(out){const r=hand.getBoundingClientRect();if(!r.width)return null;const L=hand.classList.contains('left'),sx=L?r.right-r.width*.04:r.left+r.width*.04,sy=r.top+r.height*.03;
  out.set(sx/innerWidth*2-1,-(sy/innerHeight)*2+1,.5).unproject(camera).sub(camera.position).normalize().multiplyScalar(.8).add(camera.position);return out;}

/* ---- Kaulquappen und Froschleich ---- */
function drawSpawn(){const S=32,p=new Px(S,S),r=mulberry32(77);const eggs=[];
  for(let i=0;i<90;i++){const a=r()*6.283,d=Math.sqrt(r())*12,x=16+Math.cos(a)*d*1.15,y=16+Math.sin(a)*d*.85;eggs.push([x,y]);}
  for(const[x,y]of eggs){for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){if(dx*dx+dy*dy>4.5)continue;p.set(x+dx,y+dy,hex(dx+dy<-1?'#e8f0e0':'#b8c8b0'));}}
  for(const[x,y]of eggs){p.set(x,y,hex('#141810'));if(r()<.4)p.set(x+1,y,hex('#141810'));}
  return p.done();}
function drawTadpole(f){const p=new Px(16,8),B=pal(['#14100c','#2a2018','#3e3226']);
  for(let y=0;y<8;y++)for(let x=0;x<7;x++){const dx=(x-3.2)/3.2,dy=(y-3.5)/3;if(dx*dx+dy*dy<=1)p.set(x,y,B[dy<-.3?2:dx<-.2?1:0]);}
  for(let x=6;x<16;x++){const t=(x-6)/10,y=3.5+Math.sin(t*3.2+(f?Math.PI:0))*t*2.2,w=t<.5?1:0;for(let o=0;o<=w;o++)p.set(x,y+o,B[1]);}
  p.set(1,2,hex('#d8d0a0'));return p.done();}
const tadpoles=[];let tadMats=null,tadT=0;
function initPond(){
  const lam=c=>new THREE.MeshLambertMaterial({map:frogTex(c),alphaTest:.5,side:THREE.DoubleSide,transparent:false});
  // Froschleich am flachen Ufer
  const sm=lam(drawSpawn()),r=mulberry32(31337);let n=0;
  for(let i=0;i<200&&n<7;i++){const a=r()*6.283,d=FROG.r-2.5-r()*3,x=FROG.x+Math.cos(a)*d,z=FROG.z+Math.sin(a)*d;if(x<riverX2(z)+10||onFrogPad(x,z))continue;
    const[s,q]=pierLocal(x,z);if(s>-1&&s<FROG_PIER.L+1&&Math.abs(q)<2.5)continue;const sz=.9+r()*.7,g=new THREE.PlaneGeometry(sz,sz);g.rotateX(-Math.PI/2);g.rotateY(r()*6.28);
    const m=new THREE.Mesh(g,sm);m.position.set(x,WATER+.025,z);scene.add(m);n++;}
  // Kaulquappen
  tadMats=[lam(drawTadpole(0)),lam(drawTadpole(1))];const g=new THREE.PlaneGeometry(.5,.25);g.rotateX(-Math.PI/2);
  for(let w=0;w<9;w++){const a=r()*6.283,d=5+r()*(FROG.r-10);let cx=FROG.x+Math.cos(a)*d,cz=FROG.z+Math.sin(a)*d;if(cx<riverX2(cz)+11)cx=FROG.x+4;
    for(let i=0;i<6;i++){const m=new THREE.Mesh(g,tadMats[i&1]),t={x:cx+(r()-.5)*1.6,z:cz+(r()-.5)*1.6,h:r()*6.28,sp:.4+r()*.5,ph:r()*6,m,sw:w};m.position.set(t.x,WATER+.018,t.z);scene.add(m);tadpoles.push(t);}}}
function updatePond(dt){if(!tadMats||Math.hypot(camera.position.x-FROG.x,camera.position.z-FROG.z)>SIM()+FROG.r)return;tadT+=dt;
  const SW={};for(const t of tadpoles){const c=SW[t.sw]||(SW[t.sw]={x:0,z:0,n:0});c.x+=t.x;c.z+=t.z;c.n++;}
  for(const t of tadpoles){const pd=Math.hypot(P.x-t.x,P.z-t.z);let sp=t.sp;
    {const c=SW[t.sw],gx=c.x/c.n-t.x,gz=c.z/c.n-t.z;if(Math.hypot(gx,gz)>1.2){const ah=Math.atan2(gz,gx);t.h+=Math.atan2(Math.sin(ah-t.h),Math.cos(ah-t.h))*Math.min(1,dt*1.5);}}
    if(pd<2.6&&P.y<WATER+1.5){const ah=Math.atan2(t.z-P.z,t.x-P.x);t.h+=Math.atan2(Math.sin(ah-t.h),Math.cos(ah-t.h))*Math.min(1,dt*6);sp=2.2;}
    else t.h+=(Math.sin(tadT*.7+t.ph)*.9+(Math.random()-.5)*.8)*dt;
    const d=Math.hypot(t.x-FROG.x,t.z-FROG.z);if(d>FROG.r-3||t.x<riverX2(t.z)+10){const ah=Math.atan2(FROG.z-t.z,FROG.x-t.x);t.h+=Math.atan2(Math.sin(ah-t.h),Math.cos(ah-t.h))*Math.min(1,dt*3);}
    const v=sp*(.6+.4*Math.max(0,Math.sin(tadT*5+t.ph)));t.x+=Math.cos(t.h)*v*dt;t.z+=Math.sin(t.h)*v*dt;
    t.m.position.x=t.x;t.m.position.z=t.z;t.m.rotation.y=t.h+Math.PI;t.m.material=tadMats[(Math.floor(tadT*(sp>1?14:7)+t.ph*3)&1)];}}

/* ---- Schleichen: gebeugte Knie ---- */
function sneakCv(cv){const W=cv.width,H=cv.height,lt=cv.legTop,lh=H-lt,nl=Math.round(lh*.55),dy=lh-nl,o=document.createElement('canvas');o.width=W;o.height=H;const c=o.getContext('2d');c.imageSmoothingEnabled=false;
  c.drawImage(cv,0,0,W,lt,1,dy,W,lt);const ww=Math.round(W*1.12);c.drawImage(cv,0,lt,W,lh,Math.round((W-ww)/2),H-nl,ww,nl);
  for(const k of['headBox','waist','legTop','handL','handR'])if(cv[k]!=null)o[k]=cv[k];return o;}

