      LIN=pal(['#544a34','#746a4c','#958864','#b4a47a','#cdbe92']),MSK=pal(['#36363a','#4c4c52','#64646c']),GOLD=pal(['#6a4a0c','#9a6e14','#c8961e','#e8b830','#ffe070']),LAPIS=pal(['#0c1a4a','#16307a','#2448a8','#3a68d0']);
