function drawCactus(v){const W=32,H=62,p=new Px(W,H),C=pal(['#183216','#22461e','#2e5c28','#3e7432','#52903e']),cx=16,SP=hex('#e2dcb0');
  const col=(x0,x1,y0,y1)=>{for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){if(y<=y0+1&&(x===x0||x===x1))continue;const nx=(x-(x0+x1)/2)/Math.max(1,(x1-x0)/2);let L=.64-nx*.42-(y-y0<2?-.1:0);if(((x-x0)&1)===1)L-=.2;p.set(x,y,C[shadeIdx(L,C.length,x,y)]);}};
  col(cx-3,cx+3,6,H-1);
  if(v!==2){const ay=36;col(cx-10,cx-4,ay,ay+4);col(cx-11,cx-7,ay-15,ay+4);}
  if(v===0){const ay=28;col(cx+4,cx+10,ay,ay+4);col(cx+7,cx+11,ay-12,ay+4);}
  for(let y=4;y<H;y+=3)for(let x=0;x<W;x++)if(p.d[(y*W+x)*4+3]&&hash2(x,y,881)<.07)p.set(x,y,SP);
  if(v===1){p.set(cx,4,hex('#e85a8a'));p.set(cx-1,5,hex('#f08aaa'));p.set(cx+1,5,hex('#f08aaa'));p.set(cx,5,hex('#ffe060'));}
  outline(p);return p.done();}
function drawBarrel(){const p=new Px(18,15),C=pal(['#1e3a1a','#2c5224','#3e6a2e','#548a3a']);
  for(let y=2;y<15;y++)for(let x=1;x<17;x++){const dx=(x-8.5)/8,dy=(y-9)/6.5;if(dx*dx+dy*dy>1)continue;let L=.62-dx*.35-dy*.2;if(Math.round(x*1.0)%3===0)L-=.25;p.set(x,y,C[shadeIdx(L,C.length,x,y)]);}
  for(const x of[6,8,10,12])p.set(x,2,hex(x%4?'#ffd040':'#ff7a3a'));p.set(9,1,hex('#ffd040'));outline(p);return p.done();}
function drawShrub(){const p=new Px(28,15),r=mulberry32(661),B=pal(['#4a3420','#6a4c2c','#8a6a40','#a88654']);
  for(let k=0;k<16;k++){let x=14+(r()-.5)*4,y=14;const a=-Math.PI/2+(r()-.5)*2.4,l=6+r()*8;for(let i=0;i<l;i++){x+=Math.cos(a)*.9+(r()-.5)*.6;y+=Math.sin(a)*.9;p.set(x,y,B[(r()*4)|0]);}}
  outline(p);return p.done();}
function drawBones(){const p=new Px(24,11),W=pal(['#9a9078','#c4baa0','#e2dac4','#f4eedc']);
  for(let y=1;y<8;y++)for(let x=2;x<9;x++){const dx=(x-5.5)/3.6,dy=(y-4)/3.4;if(dx*dx+dy*dy<=1)p.set(x,y,W[shadeIdx(.7-dx*.3-dy*.3,4,x,y)]);}
  p.set(4,4,hex('#2a2418'));p.set(7,4,hex('#2a2418'));p.set(5,6,hex('#2a2418'));for(let x=4;x<8;x++)p.set(x,8,W[2]);
  for(let x=10;x<23;x++){p.set(x,8,W[2]);p.set(x,9,W[1]);}p.set(10,7,W[3]);p.set(22,7,W[3]);p.set(10,10,W[1]);p.set(22,10,W[1]);
  for(let k=0;k<4;k++)for(let y=3;y<8;y++)p.set(12+k*3,y-(k&1),W[(y+k)%3+1]);outline(p);return p.done();}
function drawSRock(big){const W=big?34:20,H=big?20:12,p=new Px(W,H);
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){const dx=(x-W/2+.5)/(W/2),dy=(y-H+.5)/H;if(dx*dx+dy*dy*1.1>1)continue;let L=.6-dx*.3-(y/H)*.1+(Math.floor(y/3)%2?.08:-.08)+(hash2(x,y,671)-.5)*.2;p.set(x,y,SSTONE[shadeIdx(L,SSTONE.length,x,y)]);}
  outline(p);return p.done();}
function drawPot(broken){const W=broken?14:11,H=broken?8:15,p=new Px(W,H),T=pal(['#5a2a14','#7a3c1c','#9a5228','#b86a36','#d08a50']);
  if(!broken){for(let y=0;y<H;y++){const w=y<2?1.5:y<4?1:y<12?1+Math.sin((y-3)/9*Math.PI)*3.6:1.6;for(let x=Math.round(5-w);x<=Math.round(5+w);x++)p.set(x,y,T[shadeIdx(.65-(x-5)/w*.35+(y===7?-.2:0),T.length,x,y)]);}p.set(5,0,T[0]);}
  else{for(let y=2;y<H;y++)for(let x=1;x<W-1;x++){const dx=(x-6.5)/6,dy=(y-H)/6;if(dx*dx+dy*dy<=1&&!(y<4&&hash2(x,0,3)<.5))p.set(x,y,T[shadeIdx(.6-dx*.3,T.length,x,y)]);}for(let x=4;x<10;x++)p.set(x,3,T[0]);}
  outline(p);return p.done();}
function drawPalm(seed){const W=56,H=96,p=new Px(W,H),r=mulberry32(seed),TR=pal(['#4a3018','#6a4824','#8a6232','#a87c44']),LF=pal(['#1c3a14','#2a5a1c','#3a7426','#509032','#6aa83e']);
  let x=28,y=H-1;const bend=(r()-.5)*.5;for(let k=0;k<70;k++){const t=k/70;x+=bend+Math.sin(t*3)*.15;y-=1;for(let o=-2.5+t;o<=2.5-t;o++)p.set(x+o,y,TR[(k%4===0)?0:shadeIdx(.6-o*.15,TR.length,x+o|0,y)]);}
  const tx=x,ty=y;for(let f=0;f<9;f++){const a=-Math.PI+f/8*Math.PI+(r()-.5)*.25,len=18+r()*8;for(let i=0;i<len;i++){const t=i/len,fx=tx+Math.cos(a)*i,fy=ty+Math.sin(a)*i*.55+t*t*12;
      for(let o=-2;o<=2;o++){if(Math.abs(o)>2.4*(1-t)+.4)continue;p.set(fx-Math.sin(a)*o*.4,fy+o*.6,LF[shadeIdx(.6-t*.25+(o<0?.1:-.1),LF.length,i,o+3)]);}}}
  for(let k=0;k<4;k++)p.set(tx-2+k,ty+2,hex('#5a3a1a'));outline(p);return p.done();}
function drawObelisk(){const W=18,H=100,p=new Px(W,H);
  for(let y=0;y<H;y++){const t=y/H,hw=Math.max(.6,t<.08?(t/.08)*4.5:4.5+t*3);for(let x=Math.round(9-hw);x<=Math.round(9+hw);x++){const nx=(x-9)/hw;let c=t<.08?GOLD[shadeIdx(.75-nx*.3,GOLD.length,x,y)]:SSTONE[shadeIdx(.66-nx*.35,SSTONE.length,x,y)];
    if(t>.12&&t<.9&&Math.abs(nx)<.55&&hash2(x,y>>1,701)<.25&&(y%4)!==0)c=SSTONE[0];p.set(x,y,c);}}
  outline(p);return p.done();}
function drawCampfire(){const p=new Px(22,18),L=pal(['#3a2410','#5a3a1c']),F=[hex('#ffe68a'),hex('#ffb030'),hex('#ff6a1a'),hex('#c83010')];
  for(let k=0;k<3;k++)for(let x=2;x<20;x++)p.set(x,15+((x+k*5)%6<3?k-1:1-k)*.5+k*.6,L[(x+k)&1]);
  for(let y=3;y<15;y++){const t=(y-3)/12,w=1+t*5;for(let x=Math.round(11-w);x<=Math.round(11+w);x++){const d=Math.abs(x-11)/w;if(hash2(x,y,9)<.15&&y<8)continue;p.set(x,y,F[Math.min(3,Math.floor(d*2.2+(1-t)*1.6))]);}}
  outline(p);return p.done();}
function drawGlowEyes(col){const p=new Px(10,3),c=hex(col),w=hex('#ffffff');p.set(1,1,c);p.set(2,1,c);p.set(7,1,c);p.set(8,1,c);p.set(1,0,c);p.set(8,0,c);p.set(2,1,w);p.set(7,1,w);return p.done();}
function drawScarab(silver){const p=new Px(14,14),C=silver?pal(['#4a4e56','#7a808a','#aab0ba','#d8dee6','#ffffff']):GOLD;
  for(let y=2;y<13;y++)for(let x=2;x<12;x++){const dx=(x-6.5)/4.6,dy=(y-7.5)/5.2;if(dx*dx+dy*dy>1)continue;let L=.68-dx*.35-dy*.3;if(x===6||x===7)L-=y>5?.35:0;p.set(x,y,C[shadeIdx(L,C.length,x,y)]);}
  for(let x=5;x<9;x++){p.set(x,1,C[2]);p.set(x,2,C[1]);}p.set(5,1,C[3]);
  for(const[a,b]of[[1,5],[1,8],[1,11],[12,5],[12,8],[12,11]])p.set(a,b,C[1]);p.set(4,0,C[2]);p.set(9,0,C[2]);
  if(!silver){p.set(6,8,hex('#3a68d0'));p.set(7,8,hex('#3a68d0'));}outline(p);return p.done();}
function drawLinen(){const p=new Px(14,12);for(let y=1;y<11;y++)for(let x=1;x<13;x++){const dx=(x-6.5)/6,dy=(y-6)/5;if(dx*dx+dy*dy>1)continue;let L=.6-dx*.3+((Math.floor((y+x*.5)/2))%2?.12:-.12);p.set(x,y,LIN[shadeIdx(L,LIN.length,x,y)]);}
  for(let k=0;k<5;k++)p.set(12+(k>2?1:0),6+k,LIN[2]);outline(p);return p.done();}
function drawMask(){const p=new Px(16,18);for(let y=0;y<18;y++)for(let x=0;x<16;x++){const dx=(x-7.5)/7.5;let w=y<11?1:1-(y-11)/9;if(Math.abs(dx)>w)continue;const band=y>11&&(y%2===0);
    p.set(x,y,band?LAPIS[2]:Math.abs(dx)>.62&&y>3?(y%2?LAPIS[1]:GOLD[3]):GOLD[shadeIdx(.75-dx*.3-y*.01,GOLD.length,x,y)]);}
  for(const ex of[5,10]){p.set(ex,6,hex('#101010'));p.set(ex-1,6,hex('#f0f0f0'));p.set(ex-1,5,LAPIS[0]);p.set(ex,5,LAPIS[0]);}p.set(7,8,GOLD[1]);for(let x=6;x<10;x++)p.set(x,10,GOLD[0]);
  outline(p);return p.done();}
// Mumie (Frontansicht). ph = Pharao
function drawMummy(f,ph){const S=ph?1.5:1,W=Math.round(40*S),H=Math.round(62*S),p=new Px(W,H),cx=Math.floor(W/2),R=v=>Math.round(v*S),atk=f==='a',cast=f==='c';
  const lL=f===1?R(1):0,rL=f===2?R(1):0,legTop=H-R(15),waist=legTop-1,tTop=waist-R(19),hb=tTop-1,ht=hb-R(10)+1,hw=R(5),tw=R(6);
  const wrap=(x,y,ex)=>{const b=R(3),k=y+Math.floor(x*.5),band=Math.floor(k/b);let L=.62-(x-cx)/W*.9+ex+(hash2(band,x>>2,5)-.5)*.3;if(k%b===0)L-=.32;
    if(!ph&&hash2(x>>1,y>>1,11)<.06)return MSK[1+(hash2(x,y,12)<.5?1:0)];return LIN[shadeIdx(L,LIN.length,x,y)];};
  const lw=R(3);for(const[s,lift]of[[-1,lL],[1,rL]]){const x0=s<0?cx-lw-R(1):cx+R(1),x1=x0+lw;for(let y=legTop;y<=H-1-lift;y++)for(let x=x0;x<=x1;x++)p.set(x,y,y>H-3-lift?MSK[0]:wrap(x,y,-.05));}
  for(let y=tTop;y<=waist+(ph?R(4):0);y++){const w=tw+(y<tTop+R(2)?-1:0)+(ph&&y>waist?R(1):0);for(let x=cx-w;x<=cx+w;x++)p.set(x,y,ph&&y>=waist-R(1)?(y<=waist?GOLD[shadeIdx(.7-(x-cx)/w*.3,GOLD.length,x,y)]:((x+y)%3?GOLD[3]:LAPIS[2])):wrap(x,y,0));}
  const aw=R(2.6);
  for(const s of[-1,1]){const x0=s<0?cx-tw-aw:cx+tw+1,x1=x0+aw-1;
    if(atk||cast){const top=ht-R(atk?5:1);for(let y=top;y<=tTop+R(4);y++)for(let x=x0;x<=x1;x++)p.set(x,y,wrap(x,y,-.1));for(let y=top-R(2);y<top;y++)for(let x=x0;x<=x1;x++)p.set(x,y,MSK[2]);}
    else{const sw=(f===1?-1:f===2?1:0)*s;for(let y=tTop+1;y<=waist-R(2)+sw;y++)for(let x=x0;x<=x1;x++)p.set(x,y,wrap(x,y,-.12));for(let y=waist-R(1)+sw;y<=waist+R(1)+sw;y++)for(let x=x0;x<=x1;x++)p.set(x,y,MSK[1+(x===x0?0:1)]);}}
  // lose Binden
  if(!ph){const r=mulberry32(77+(typeof f==='number'?f:9));for(let k=0;k<4;k++){const sx=cx-tw+((r()*tw*2)|0),sy=tTop+5+((r()*12)|0),l=3+((r()*4)|0);for(let i=0;i<l;i++)p.set(sx+(i>2?(k&1?1:-1):0),sy+i,LIN[2+(i&1)]);}}
  // Kopf
  for(let y=ht;y<=hb;y++)for(let x=cx-hw;x<=cx+hw-1;x++){if((y===ht||y===hb)&&(x===cx-hw||x===cx+hw-1))continue;p.set(x,y,ph?GOLD[shadeIdx(.78-(x-cx)/hw*.3-(y-ht)*.01,GOLD.length,x,y)]:wrap(x,y,.05));}
  const ey=ht+R(4),eyeC=hex(ph?'#7ad8ff':'#ffd23a');
  if(ph){ // Nemes-Kopftuch, Bart, Kragen, Krummstab und Geißel
    for(let y=ht-R(3);y<=hb+R(7);y++){const t=(y-(ht-R(3)))/(hb+R(7)-(ht-R(3))),w=hw+R(1)+Math.round(t*R(4));for(let x=cx-w-1;x<=cx+w;x++){const inFace=y>=ht&&y<=hb&&x>=cx-hw&&x<=cx+hw-1;if(inFace)continue;if(y>hb&&Math.abs(x-cx)<tw-1)continue;
      p.set(x,y,(Math.floor((y-ht)/R(2))%2)?LAPIS[shadeIdx(.6-(x-cx)/w*.3,LAPIS.length,x,y)]:GOLD[shadeIdx(.7-(x-cx)/w*.3,GOLD.length,x,y)]);}}
    for(let x=cx-hw;x<=cx+hw-1;x++){p.set(x,ht-R(3),GOLD[4]);}p.set(cx-1,ht-R(4),GOLD[3]);p.set(cx,ht-R(4),GOLD[3]);p.set(cx,ht-R(5),LAPIS[2]);
    for(let y=hb+1;y<=hb+R(4);y++){p.set(cx-1,y,y%2?GOLD[2]:LAPIS[2]);p.set(cx,y,y%2?GOLD[3]:LAPIS[1]);}
    for(let y=tTop;y<=tTop+R(5);y++){const w=tw+1-Math.floor((y-tTop)*.6);for(let x=cx-w;x<=cx+w;x++){const ring=Math.floor(Math.hypot(x-cx,(y-tTop+3)*1.4)/2)%3;p.set(x,y,ring===0?GOLD[3]:ring===1?LAPIS[2]:hex('#b8302a'));}}
    if(!atk&&!cast){for(let k=0;k<R(12);k++){p.set(cx-R(5)+k,tTop+R(15)-k,GOLD[3]);p.set(cx+R(5)-k,tTop+R(15)-k,k%3?LAPIS[2]:GOLD[2]);}
      for(let k=0;k<4;k++){p.set(cx-R(5)-k%2,tTop+R(4)-k,GOLD[4]);}for(let k=0;k<5;k++){p.set(cx+R(6)+k%2,tTop+R(4)+k,LAPIS[2]);p.set(cx+R(7)+k%2,tTop+R(4)+k,GOLD[2]);}}
    for(let x=cx-hw+1;x<=cx+hw-2;x++)p.set(x,ey,GOLD[0]);
    for(const ex of[cx-R(3),cx+R(1)]){p.set(ex,ey,eyeC);p.set(ex+1,ey,eyeC);p.set(ex,ey-1,LAPIS[0]);p.set(ex+1,ey-1,LAPIS[0]);}
    p.set(cx-1,ey+R(3),GOLD[0]);p.set(cx,ey+R(3),GOLD[0]);}
  else{for(let x=cx-hw+1;x<=cx+hw-2;x++)p.set(x,ey,hex('#16140e'));for(const ex of[cx-3,cx+1]){p.set(ex,ey,eyeC);p.set(ex+1,ey,eyeC);}
    for(let x=cx-2;x<=cx+1;x++)if(hash2(x,1,4)<.6)p.set(x,ey+3,hex('#2a2418'));}
  outline(p);const c=p.done();c.eyeY=ey;return c;}
function desertSprites(list){for(let v=0;v<3;v++)list.push(['cactus'+v,drawCactus(v)]);list.push(['bcactus',drawBarrel()]);list.push(['dshrub',drawShrub()]);list.push(['bones',drawBones()]);
  list.push(['srock0',drawSRock(true)]);list.push(['srock1',drawSRock(false)]);list.push(['pot',drawPot(false)]);list.push(['potb',drawPot(true)]);list.push(['palm0',drawPalm(81)]);list.push(['palm1',drawPalm(97)]);
  list.push(['obelisk',drawObelisk()]);list.push(['campfire',drawCampfire()]);list.push(['meyes',drawGlowEyes("#ffd23a")]);list.push(['peyes',drawGlowEyes("#7ad8ff")]);
  list.push(['silverscarab',drawScarab(true)]);list.push(['goldscarab',drawScarab(false)]);list.push(['linen',drawLinen()]);list.push(['pharaohmask',drawMask()]);
  for(const f of[0,1,2,'a']){list.push(['mum_'+f,drawMummy(f,false)]);}for(const f of[0,1,2,'a','c'])list.push(['pha_'+f,drawMummy(f,true)]);
  const pr={race:'human',sex:'m',age:'old',skin:3,hair:'none',hairColor:'black',beard:'short',cloth:'robe',clothColor:'cream',pants:'brown',eyes:'black'};for(let f=0;f<3;f++)list.push(['sefu'+f,drawHero(pr,f)]);DPRIEST.look=pr;}

/* ---- Höhen & Chunks ---- */
const DCH=80,dchunks=[];let desertMat=null;
const siteDist=(x,z)=>Math.min(...DSITES.map(S=>Math.hypot(x-S.x,z-S.z)-S.r));
function desertData(ch){const r=mulberry32(12000+ch.i*131+ch.j*1931),deco=[];
  const put=(n,fn)=>{for(let i=0;i<n;i++){const x=ch.x0+r()*DCH,z=ch.z0+r()*DCH;if(x<DX0+2||x>DX1-1||z<DZ0+2||z>DZ1-1)continue;const sb=smooth(clamp((x-DX0)/45,0,1))*smooth(clamp((z-DZ0)/45,0,1));
    const gh=getHeight(x,z);if(gh<WATER+.3)continue;const o=fn(x,z,gh,sb,siteDist(x,z));if(o){o.x=x;o.z=z;o.y=gh-(o.sink||.06);deco.push(o);}}};
  put(4,(x,z,gh,sb,sd)=>{if(sb<.6||sd<4||r()>.55)return null;const v=(r()*3)|0,h=2.6+r()*2.2,w=h*32/62;frogProp(x,z,.4,h);return{w,h,spr:'cactus'+v,tint:.9+r()*.15,sink:.15};});
  put(5,(x,z,gh,sb,sd)=>{if(sb<.5||sd<2)return null;const w=.5+r()*.25;return{w,h:w*15/18,spr:'bcactus',tint:.95};});
  put(10,(x,z,gh,sb,sd)=>{const w=.8+r()*.6;return{w,h:w*15/28,spr:'dshrub',sway:.05,tint:.9+r()*.2};});
  put(2,(x,z,gh,sb,sd)=>{if(sb<.7||r()>.5)return null;const w=.9;return{w,h:w*11/24,spr:'bones',tint:1};});
  put(4,(x,z,gh,sb,sd)=>{if(sd<3)return null;const big=r()<.35,w=big?1.5+r()*1.2:.6+r()*.5;return{w,h:w*(big?20/34:12/20),spr:big?'srock0':'srock1',tint:.92+r()*.15,sink:.12};});
  put(70,(x,z,gh,sb,sd)=>{if(sb>.85||r()>1-sb*.9)return null;const w=.5+r()*.35;return{w,h:w,spr:'tall'+(r()*3|0),sway:.12,tint:1.15};});
  return{deco};}
function desertTexture(ch){const T=512,ES=DCH/T,cv=document.createElement('canvas');cv.width=cv.height=T;const ctx=cv.getContext('2d'),img=ctx.createImageData(T,T),d=img.data;
  const gx0=Math.round((ch.x0-DX0)/ES),gy0=Math.round((ch.z0-DZ0)/ES);
  for(let py=0;py<T;py++){const wz=ch.z0+(py+.5)*ES,gy=py+gy0;for(let px=0;px<T;px++){const wx=ch.x0+(px+.5)*ES,gxx=px+gx0,h=hash2(gxx,gy,931);let c=null;
    const sb=smooth(clamp((wx-DX0)/45,0,1))*smooth(clamp((wz-DZ0)/45,0,1));
    if(pSand(wx,wz)<.999&&(c=seamColDesert(wx,wz,gxx,gy))){}
    else if(wx<HALF+80&&riverDist(wx,wz)<9.5+(h-.5)){const cr=(Math.abs(Math.sin(wx*2.1+vnoise(wx*.5,wz*.5,933)*6))<.12||Math.abs(Math.sin(wz*2.3+vnoise(wx*.4,wz*.4,934)*6))<.1);c=cr?GP.MUD[0]:GP.SAND[shadeIdx(.45+(h-.5)*.4,GP.SAND.length,gxx,gy)];}
    else{const dv=Math.hypot(wx-DVIL.x,wz-DVIL.z),dt=Math.hypot(wx-DTOMB.x,wz-DTOMB.z);
      if(dv<11&&!(((wx-DVIL.x+40)%2.2<.18)||((wz-DVIL.z+40)%2.2<.18))&&hash2(gxx>>2,gy>>2,935)<.85)c=SSTONE[shadeIdx(.5+(h-.5)*.4+(hash2(Math.floor(wx/2.2),Math.floor(wz/2.2),936)-.5)*.4,SSTONE.length,gxx,gy)];
      else if(dt<DTOMB.r-6&&wx<DTOMB.x+20&&Math.abs(wz-DTOMB.z)<16&&hash2(gxx>>2,gy>>2,937)<.9){const sx=Math.floor(wx/3),sz=Math.floor(wz/1.8);const edge=((wx+60)%3<.2)||((wz+60)%1.8<.15);
        c=edge?SSTONE[0]:SSTONE[shadeIdx(.62+(hash2(sx,sz,938)-.5)*.3+(h-.5)*.2,SSTONE.length,gxx,gy)];}
      else{const rip=Math.sin((wx*.95+wz*.4)*2.4+vnoise(wx*.06,wz*.06,939)*9);let L=.56+rip*.1+(vnoise(wx*.035,wz*.035,940)-.5)*.5+(h-.5)*.16;if(dv<DVIL.r)L-=.12;
        c=SANDP[shadeIdx(L,SANDP.length,gxx,gy)];if(hash2(gxx,gy,941)<.004)c=SSTONE[0];{const t=Math.max((wx-860)/140,wx>600?(190-wz)/70:0)+(vnoise(wx*.035,wz*.035,1403)-.5)*.55;if(t>0&&hash2(gxx>>1,gy>>1,1405)<t*t*.85)c=(t>.75&&hash2(gxx>>2,gy>>2,1406)<.4?FP_.SAV:FP_.STEP)[shadeIdx(L,6,gxx,gy)];}}}
    const i=(py*T+px)*4;d[i]=c[0];d[i+1]=c[1];d[i+2]=c[2];d[i+3]=255;}}
  ctx.putImageData(img,0,0);const tex=new THREE.CanvasTexture(cv);tex.magFilter=THREE.NearestFilter;tex.minFilter=THREE.NearestMipmapNearestFilter;return tex;}
function desertBuild(ch){const N=DCH/NCELL,geo=new THREE.PlaneGeometry(DCH,DCH,N,N),pos=geo.attributes.position,gx0=(ch.x0-DX0)/NCELL,gz0=(ch.z0-DZ0)/NCELL;
  for(let k=0;k<pos.count;k++){const ix=k%(N+1),iy=Math.floor(k/(N+1));pos.setZ(k,heightsD[(gz0+iy)*DR1+gx0+ix]);}
  geo.rotateX(-Math.PI/2);geo.translate(ch.cx,0,ch.cz);geo.computeVertexNormals();
  ch.ground=new THREE.Mesh(geo,new THREE.MeshPhongMaterial({map:desertTexture(ch),flatShading:true,shininess:0,specular:0x000000}));scene.add(ch.ground);
  ch.bb=makeBillboards(ch.data.deco,desertMat);scene.add(ch.bb);}
function desertFree(ch){scene.remove(ch.ground);ch.ground.geometry.dispose();ch.ground.material.map.dispose();ch.ground.material.dispose();scene.remove(ch.bb);ch.bb.geometry.dispose();ch.ground=null;ch.bb=null;}
function updateDesert(){const rd=settings.renderDist||140;streamChunks(dchunks,rd+50,rd+10,rd+90,desertData,desertBuild,desertFree);}

/* ---- Bauten ---- */
const DWALLS=[];
function drawBrick(adobe){const p=new Px(32,32);for(let y=0;y<32;y++)for(let x=0;x<32;x++){const row=Math.floor(y/(adobe?16:8)),bx=Math.floor((x+(row%2)*(adobe?0:8))/16),mort=!adobe&&(y%8===0||(x+(row%2)*8)%16===0);
    let L=.58+(hash2(bx,row,951)-.5)*.25+(hash2(x,y,952)-.5)*.16+(vnoise(x*.2,y*.2,953)-.5)*.3;if(mort)L-=.3;if(adobe&&hash2(x>>1,y>>1,954)<.04)L-=.35;p.set(x,y,(adobe?SANDP:SSTONE)[shadeIdx(L,6,x,y)]);}
  for(let k=0;k<(adobe?5:2);k++){const r=mulberry32(960+k+(adobe?20:0));let x=r()*32,y=r()*32;for(let i=0;i<10;i++){x+=(r()-.5)*2;y+=1;p.set(((x%32)+32)%32,y%32,SSTONE[0]);}}
  return p.done();}
function texRep(c){const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.NearestFilter;t.minFilter=THREE.NearestMipmapNearestFilter;return t;}
function boxUV(w,h,d,S){const g=new THREE.BoxGeometry(w,h,d),uv=g.attributes.uv,dims=[[d,h],[d,h],[w,d],[w,d],[w,h],[w,h]];
  for(let f=0;f<6;f++)for(let k=0;k<4;k++){const i=f*4+k;uv.setXY(i,uv.getX(i)*dims[f][0]/S,uv.getY(i)*dims[f][1]/S);}return g;}
function dWall(grp,mat,x,z,w,d,h,y0){const m=new THREE.Mesh(boxUV(w,h,d,2),mat);m.position.set(x,y0+h/2,z);grp.add(m);const c={x,z,cos:1,sin:0,hw:w/2,hd:d/2,h,top:y0+h};COLL.push(c);DWALLS.push(c);return m;}
let DSARCO=null,sarcoLid=null;
function initDesert(atlas){desertMat=bbMaterial(atlas,0,0);EXTRA_BB.push(desertMat);
  for(let j=0;j<(DZ1-DZ0)/DCH;j++)for(let i=0;i<(DX1-DX0)/DCH;i++){const x0=DX0+i*DCH,z0=DZ0+j*DCH;dchunks.push({i,j,x0,z0,cx:x0+DCH/2,cz:z0+DCH/2,data:null,ground:null,bb:null});}
  const ph=o=>new THREE.MeshPhongMaterial(Object.assign({flatShading:true,shininess:0,specular:0x000000},o));
  const adobe=ph({map:texRep(drawBrick(true))}),stone=ph({map:texRep(drawBrick(false))}),gold=ph({color:0xe8b830,emissive:0x302008}),dark=new THREE.MeshBasicMaterial({color:0x0c0806}),grp=new THREE.Group(),deco=[];
  // Das verlassene Dorf: Lehmhäuser um einen Platz mit Brunnen
  const r=mulberry32(4401),y0=DVIL.base-.15;
  for(let k=0;k<9;k++){const a=k/9*Math.PI*2+(r()-.5)*.3,dist=17+r()*10,cx=DVIL.x+Math.cos(a)*dist,cz=DVIL.z+Math.sin(a)*dist,w=5+r()*3,d=5+r()*2.5,ruin=r()<.55,H=3+r()*.6,T=.4;
    const dx=DVIL.x-cx,dz=DVIL.z-cz,doorSide=Math.abs(dx)>Math.abs(dz)?(dx>0?'e':'w'):(dz>0?'s':'n');
    const wall=(side)=>{const along=side==='n'||side==='s',L=along?w:d,ox=side==='e'?w/2-T/2:side==='w'?-w/2+T/2:0,oz=side==='s'?d/2-T/2:side==='n'?-d/2+T/2:0,segs=[];
      if(side===doorSide){const g=1.3;segs.push([-L/2,-g/2],[g/2,L/2]);}else segs.push([-L/2,L/2]);
      for(const[s0,s1]of segs){if(ruin){for(let s=s0;s<s1-.01;s+=1){const e=Math.min(s1,s+1),hh=H*(.25+.75*Math.max(0,vnoise(cx+s*.7,cz+side.charCodeAt(0),970)*1.3-.15));if(hh<.35)continue;const m=(s+e)/2;
          along?dWall(grp,adobe,cx+m,cz+oz,e-s,T,hh,y0):dWall(grp,adobe,cx+ox,cz+m,T,e-s,hh,y0);}}
        else{const m=(s0+s1)/2,l=s1-s0;along?dWall(grp,adobe,cx+m,cz+oz,l,T,H,y0):dWall(grp,adobe,cx+ox,cz+m,T,l,H,y0);}}
      if(side===doorSide&&!ruin){const lt=new THREE.Mesh(boxUV(along?1.3:T,H-2.2,along?T:1.3,2),adobe);lt.position.set(cx+ox,y0+2.2+(H-2.2)/2,cz+oz);grp.add(lt);}};
    for(const s of['n','s','e','w'])wall(s);
    if(!ruin){const roof=new THREE.Mesh(boxUV(w+.3,.3,d+.3,2),adobe);roof.position.set(cx,y0+H+.15,cz);grp.add(roof);
      for(let q=0;q<3;q++){const b=new THREE.Mesh(new THREE.BoxGeometry(.18,.18,.6),ph({color:0x5a3a1c}));b.position.set(cx-w/2+1+q*(w-2)/2,y0+H-.25,cz+(d/2+.2)*(doorSide==='n'?-1:1));grp.add(b);}}
    for(let q=0;q<3;q++){const px=cx+(r()-.5)*(w-1.6),pz=cz+(r()-.5)*(d-1.6);deco.push({x:px,z:pz,y:y0+.1,w:r()<.5?.5:.62,h:r()<.5?.68:.36,spr:r()<.5?'pot':'potb',tint:.9+r()*.15});}
    const ox=cx+(doorSide==='e'?w/2+1.2:doorSide==='w'?-w/2-1.2:(r()-.5)*2),oz=cz+(doorSide==='s'?d/2+1.2:doorSide==='n'?-d/2-1.2:(r()-.5)*2);deco.push({x:ox,z:oz,y:y0+.1,w:.62,h:.36,spr:'potb',tint:1});}
  // Brunnen
  {const ring=new THREE.Mesh(new THREE.CylinderGeometry(1.15,1.25,.9,10,1,true),stone);ring.position.set(DVIL.x,y0+.45,DVIL.z);grp.add(ring);ring.material.side=THREE.DoubleSide;
    const hole=new THREE.Mesh(new THREE.CircleGeometry(1.1,10),dark);hole.rotation.x=-Math.PI/2;hole.position.set(DVIL.x,y0+.55,DVIL.z);grp.add(hole);
    for(const s of[-1,1]){const pst=new THREE.Mesh(boxUV(.22,2.1,.22,2),stone);pst.position.set(DVIL.x+s*1.05,y0+1.05,DVIL.z);grp.add(pst);}
    const bm=new THREE.Mesh(new THREE.BoxGeometry(2.4,.16,.16),ph({color:0x5a3a1c}));bm.position.set(DVIL.x,y0+2.1,DVIL.z);grp.add(bm);frogProp(DVIL.x,DVIL.z,1.3,.9);}
  for(let k=0;k<14;k++){const a=r()*6.28,dd=8+r()*30,x=DVIL.x+Math.cos(a)*dd,z=DVIL.z+Math.sin(a)*dd;if(DWALLS.some(w=>Math.abs(x-w.x)<w.hw+.5&&Math.abs(z-w.z)<w.hd+.5))continue;
    const t=r();deco.push(t<.35?{x,z,y:y0,w:1.1,h:1.1*15/28,spr:'dshrub',sway:.05,tint:1}:t<.55?{x,z,y:y0,w:.9,h:.41,spr:'bones',tint:1}:t<.8?{x,z,y:y0-.1,w:4,h:6,spr:'dead'+(k&1),tint:.85}:{x,z,y:y0,w:.62,h:.36,spr:'potb',tint:1});}
  // Grabstätte des Pharaos: Stufenpyramide, Obelisken, Sarkophag
  {const T=DTOMB,px=T.x+14,pz=T.z,b=T.base-.2;for(let i=0;i<4;i++){const s=24-i*5.5,m=new THREE.Mesh(boxUV(s,2.6,s,2),stone);m.position.set(px,b+1.3+i*2.6,pz);grp.add(m);
      {const c={x:px,z:pz,cos:1,sin:0,hw:s/2,hd:s/2,h:2.6*(i+1),top:b+2.6*(i+1)};COLL.push(c);if(i===0)DWALLS.push(c);}}COLL.push({x:px,z:pz,cos:1,sin:0,hw:1.2,hd:1.2,h:12,top:b+12});
    const cap=new THREE.Mesh(new THREE.BoxGeometry(2.4,1.6,2.4),gold);cap.position.set(px,b+10.4+.8,pz);grp.add(cap);
    const door=new THREE.Mesh(new THREE.PlaneGeometry(2.2,2.3),dark);door.rotation.y=-Math.PI/2;door.position.set(px-12.02,b+1.15,pz);grp.add(door);
    const lint=new THREE.Mesh(boxUV(.5,.5,3.2,2),stone);lint.position.set(px-12.1,b+2.5,pz);grp.add(lint);
    const dais=new THREE.Mesh(boxUV(3.6,.45,2.4,2),stone);dais.position.set(T.x-4,b+.22,pz);grp.add(dais);
    const sc=document.createElement('canvas');sc.width=32;sc.height=16;const sx=sc.getContext('2d');sx.fillStyle='#c8961e';sx.fillRect(0,0,32,16);for(let x=0;x<32;x+=4){sx.fillStyle='#2448a8';sx.fillRect(x,0,2,16);}
    sx.fillStyle='#e8b830';sx.fillRect(0,5,32,6);sx.fillStyle='#16307a';sx.fillRect(3,6,2,2);sx.fillRect(8,6,2,2);
    const smat=ph({map:frogTex(sc)}),base=new THREE.Mesh(new THREE.BoxGeometry(2.7,.8,1.15),smat);base.position.set(T.x-4,b+.45+.4,pz);grp.add(base);
    sarcoLid=new THREE.Mesh(new THREE.BoxGeometry(2.8,.28,1.25),smat);sarcoLid.position.set(T.x-4,b+.45+.8+.14,pz);grp.add(sarcoLid);
    const face=new THREE.Mesh(new THREE.BoxGeometry(.5,.18,.6),gold);face.position.set(-1.0,.2,0);sarcoLid.add(face);
    DSARCO={x:T.x-4,z:pz,y:b+.45,lid0:sarcoLid.position.clone()};frogProp(DSARCO.x,DSARCO.z,1.3,1.4);
    for(const s of[-1,1]){deco.push({x:T.x-11,z:pz+s*7.5,y:b,w:1.7,h:9.4,spr:'obelisk',tint:1});frogProp(T.x-11,pz+s*7.5,.8,9);}
    for(let k=0;k<8;k++){const a=r()*6.28,dd=14+r()*16,x=T.x+Math.cos(a)*dd-6,z=pz+Math.sin(a)*dd;if(Math.abs(x-px)<14&&Math.abs(z-pz)<14)continue;deco.push({x,z,y:getHeight(x,z)-.1,w:1.4,h:.82,spr:'srock0',tint:1});}}
  // Sefus Lager: Zelt, Feuer, Palmen
  {const C=DCAMP,cl=document.createElement('canvas');cl.width=32;cl.height=16;const cx2=cl.getContext('2d');for(let x=0;x<32;x+=4){cx2.fillStyle=(x/4)%2?'#e8dcc0':'#a83a2a';cx2.fillRect(x,0,4,16);}
    const tent=new THREE.Mesh(new THREE.ConeGeometry(2.4,3,8,1,true),ph({map:frogTex(cl),side:THREE.DoubleSide}));tent.position.set(C.x+3,C.base+1.4,C.z-2);grp.add(tent);frogProp(C.x+3,C.z-2,2.2,2.6);
    const tdoor=new THREE.Mesh(new THREE.PlaneGeometry(1,1.5),dark);tdoor.position.set(C.x+3,C.base+.7,C.z-2+1.75);grp.add(tdoor);
    deco.push({x:C.x,z:C.z+2,y:C.base-.05,w:.9,h:.74,spr:'campfire',tint:1.3});DPRIEST.fire={x:C.x,z:C.z+2,y:C.base};
    for(const[dx,dz,v]of[[-6,-4,0],[8,3,1],[-4,7,1],[5,-8,0]]){const h=7+((dx*7+dz)&3);deco.push({x:C.x+dx,z:C.z+dz,y:C.base-.2,w:h*56/96,h,spr:'palm'+v,sway:.05,tint:1});frogProp(C.x+dx,C.z+dz,.35,h*.7);}}
  scene.add(grp);scene.add(makeBillboards(deco,desertMat));
  // Sefu
  {const C=DCAMP,s=SPR.sefu0,h=1.78*60/(60-s.c.headBox[2]+1);Object.assign(DPRIEST,{x:C.x-1.5,z:C.z+.5,y:C.base,h,w:h*44/60});DPRIEST.portrait=frogPortrait(DPRIEST.look);
    DPRIEST.mesh=makeBillboards([{x:DPRIEST.x,y:DPRIEST.y,z:DPRIEST.z,w:DPRIEST.w,h:DPRIEST.h,spr:'sefu0',tint:1}],desertMat);scene.add(DPRIEST.mesh);}
  initMummies(atlas);}

/* ---- Sichtlinie: Mauern über Augenhöhe blockieren den Blick ---- */
function desertLOS(ax,az,bx,bz){const x0=Math.min(ax,bx)-1,x1=Math.max(ax,bx)+1,z0=Math.min(az,bz)-1,z1=Math.max(az,bz)+1,W=DWALLS.filter(w=>w.h>1.5&&w.x+w.hw>x0&&w.x-w.hw<x1&&w.z+w.hd>z0&&w.z-w.hd<z1);
  if(!W.length)return true;const d=Math.hypot(bx-ax,bz-az),n=Math.ceil(d/.35);for(let i=1;i<n;i++){const t=i/n,x=ax+(bx-ax)*t,z=az+(bz-az)*t;for(const w of W)if(Math.abs(x-w.x)<w.hw&&Math.abs(z-w.z)<w.hd)return false;}return true;}
const inWall=(x,z,m)=>DWALLS.some(w=>Math.abs(x-w.x)<w.hw+m&&Math.abs(z-w.z)<w.hd+m);

/* ---- Mumien ---- */
const MUM_N=14,mummies=[];let mumMesh=null,mumEyes=null,mumEyeMat=null,mumNight=null,phEyeMat=null;
const MUM={hp:70,dmg:12,walk:.55,run:1.9,aggro:15,leash:30,lose:4};
function initMummies(atlas){const s=SPR.mum_0,h=1.9,w=h*s.w/s.h;
  for(let i=0;i<MUM_N;i++)mummies.push({i,x:0,y:-50,z:0,h,w,st:'off',hp:MUM.hp,frame:0,anim:0,t:0});
  mumMesh=makeBillboards(mummies.map(m=>({x:0,y:-50,z:0,w,h,spr:'mum_0',tint:1})),desertMat);scene.add(mumMesh);
  mumEyeMat=bbMaterial(atlas,0,0);mumEyes=makeBillboards(mummies.map(m=>({x:0,y:-50,z:0,w:.27,h:.08,spr:'meyes',tint:1.6})),mumEyeMat);scene.add(mumEyes);
  initPharaoh(atlas);}
function mumSpot(){for(let k=0;k<30;k++){const a=Math.random()*6.283,d=4+Math.random()*(DVIL.r-8),x=DVIL.x+Math.cos(a)*d,z=DVIL.z+Math.sin(a)*d;if(!inWall(x,z,.8))return[x,z];}return[DVIL.x+3,DVIL.z+3];}
function raiseMummy(x,z,add){const m=mummies.find(q=>q.st==='off');if(!m)return null;Object.assign(m,{x,z,y:getHeight(x,z),st:'rise',t:0,hp:MUM.hp,add:!!add,dead:false,atkT:0,lostT:0,hurt:0,tx:x,tz:z,wait:1,rot:0});
  for(let k=0;k<14;k++)spawnParticle(x+(Math.random()-.5),m.y+.1,z+(Math.random()-.5),(Math.random()-.5)*2,1+Math.random()*2,(Math.random()-.5)*2,0xd8b070,1.2,.3);return m;}
function hurtMummy(m,n){if(m.dead||m.st==='off'||m.st==='rise'||m.st==='sink')return;m.hp-=n;m.hurt=.22;if(m.st==='wander'){m.st='chase';m.lostT=0;m.lx=P.x;m.lz=P.z;mumGroan(m);}
  if(m.hp<=0){m.dead=true;m.st='dead';m.t=0;m.fallDir=Math.random()<.5?-1:1;Snd.thud();gainXP(20);
    if(Math.random()<.01)spawnDrop('silverscarab',1,m.x,m.y+.5,m.z);if(Math.random()<.45)spawnDrop('linen',1+(Math.random()<.3?1:0),m.x,m.y+.5,m.z);if(Math.random()<.2)spawnDrop('bones',1,m.x,m.y+.5,m.z);}}
function mumGroan(m){const c=Snd.ctx;if(!c)return;const d=Math.hypot(P.x-m.x,P.z-m.z),v=Math.max(0,1-d/35);if(v<.05)return;const t=c.currentTime,{o}=Snd.tone('sawtooth',95+Math.random()*25,t,.9,.05*v,null,420);o.frequency.linearRampToValueAtTime(70,t+.9);}
function updateMummies(dt){if(!mumMesh)return;const night=isNight(),pv=Math.hypot(P.x-DVIL.x,P.z-DVIL.z);
  const key=(FLAGS.day||0)-(FLAGS.clock<330?1:0);
  if(night&&mumNight!==key&&pv<170){mumNight=key;for(let k=0;k<9;k++){const[x,z]=mumSpot();const m=raiseMummy(x,z,false);if(m)m.t=-Math.random()*3;}}
  if(!night)mumNight=null;
  const near=Math.hypot(camera.position.x-DVIL.x,camera.position.z-DVIL.z)<SIM()+80||(pharaoh&&pharaoh.awake);
  const off=mumMesh.geometry.attributes.offset,uvr=mumMesh.geometry.attributes.uvr,rot=mumMesh.geometry.attributes.rot,tint=mumMesh.geometry.attributes.tint,eo=mumEyes.geometry.attributes.offset,es=mumEyes.geometry.attributes.size;
  const cdx=camera.position.x,cdz=camera.position.z;
  for(const m of mummies){const i=m.i;let yo=0;
    if(m.st==='off'){off.array[i*3+1]=-50;eo.array[i*3+1]=-50;continue;}
    if(!near&&m.st!=='dead'){continue;}
    if(!night&&!m.add&&m.st!=='dead'&&m.st!=='sink'){m.st='sink';m.t=0;}
    m.t+=dt;if(m.atkT>0)m.atkT-=dt;if(m.hurt>0)m.hurt-=dt;
    const dp=Math.hypot(P.x-m.x,P.z-m.z),alive=state!=='dead';
    if(m.st==='rise'){if(m.t<0){yo=-m.h;}else{const u=Math.min(1,m.t/2.2);yo=-m.h*(1-u);if(Math.random()<dt*14)spawnParticle(m.x+(Math.random()-.5),m.y+.05,m.z+(Math.random()-.5),(Math.random()-.5),1+Math.random(),(Math.random()-.5),0xd8b070,.8,.3);if(u>=1){m.st=m.add?'chase':'wander';m.lx=P.x;m.lz=P.z;m.lostT=0;if(m.add)mumGroan(m);}}m.frame=0;}
    else if(m.st==='sink'){const u=Math.min(1,m.t/2.5);yo=-m.h*u;m.frame=0;if(u>=1)m.st='off';}
    else if(m.st==='dead'){const k=Math.min(1,m.t/.5);m.rot=m.fallDir*k*k*Math.PI/2;if(m.t>4)yo=-Math.min(1,(m.t-4)/1.5)*.8;if(m.t>5.5){m.st='off';m.rot=0;}m.frame=0;}
    else{ // Wahrnehmung
      m.losT=(m.losT||0)-dt;if(m.losT<=0){m.losT=.2;m.sees=alive&&dp<MUM.leash&&desertLOS(m.x,m.z,P.x,P.z);}
      if(m.st==='wander'&&m.sees&&dp<MUM.aggro){m.st='chase';m.lostT=0;mumGroan(m);}
      if(m.st==='chase'){if(m.sees){m.lx=P.x;m.lz=P.z;m.lostT=0;}else m.lostT+=dt;
        if(m.lostT>MUM.lose||dp>MUM.leash||!alive){m.st='wander';m.wait=1.5;m.tx=m.x;m.tz=m.z;}}
      let tx,tz,sp;
      if(m.st==='chase'){tx=m.lx;tz=m.lz;sp=MUM.run;}
      else{if(m.wait>0){m.wait-=dt;tx=m.x;tz=m.z;sp=0;}else{tx=m.tx;tz=m.tz;sp=MUM.walk;if(Math.hypot(tx-m.x,tz-m.z)<.4){m.wait=2+Math.random()*5;[m.tx,m.tz]=m.add?[m.x,m.z]:mumSpot();if(Math.random()<.15)mumGroan(m);}}}
      const dx=tx-m.x,dz=tz-m.z,d=Math.hypot(dx,dz);
      if(m.st==='chase'&&dp<1.25){sp=0;if(m.sees&&m.atkT<=0){m.atkT=1.5;m.swing=.45;}}
      if(m.swing>0){m.swing-=dt;if(m.swing<=0&&dp<1.7&&m.sees&&state==='playing'){takeDamage(MUM.dmg);Snd.hit('sword');}}
      if(sp>0&&d>.05){const st=Math.min(d,sp*dt);m.x+=dx/d*st;m.z+=dz/d*st;collideColl(m,.3);collideTreesObj(m,.3);if(dp<.7){const qx=m.x-P.x,qz=m.z-P.z,ql=Math.hypot(qx,qz)||1;m.x=P.x+qx/ql*.7;m.z=P.z+qz/ql*.7;}
        m.anim+=st*1.6;m.frame=1+(Math.floor(m.anim)%2);}else m.frame=0;
      if(m.swing>0)m.frame='a';
      m.y=getHeight(m.x,m.z);}
    off.array[i*3]=m.x;off.array[i*3+1]=m.y+yo-.03;off.array[i*3+2]=m.z;rot.array[i]=m.rot||0;tint.array[i]=m.hurt>0?-1.3:m.st==='dead'?.75:1;
    const s=SPR['mum_'+m.frame];uvr.array[i*4]=s.u;uvr.array[i*4+1]=s.v;
    // leuchtende Augen, knapp vor dem Gesicht
    const ex=cdx-m.x,ez=cdz-m.z,el=Math.hypot(ex,ez)||1,showE=m.st!=='dead'&&m.st!=='sink';eo.array[i*3]=m.x+ex/el*.08;eo.array[i*3+2]=m.z+ez/el*.08;
    eo.array[i*3+1]=showE?m.y+yo+m.h*(1-(SPR.mum_0.c.eyeY+1)/SPR.mum_0.h)-.05:-50;es.array[i*2]=showE?.27:0;}
  off.needsUpdate=uvr.needsUpdate=rot.needsUpdate=tint.needsUpdate=eo.needsUpdate=es.needsUpdate=true;}

/* ---- Der Pharao ---- */
let pharaoh=null,phMesh=null,phEyes=null;const PH_HP=1400,PH_NAME='Pharao Kreakhotep',sandBolts=[];
function initPharaoh(atlas){const s=SPR.pha_0,h=3.4,w=h*s.w/s.h;pharaoh={x:DSARCO.x,z:DSARCO.z,y:DSARCO.y,h,w,hp:PH_HP,awake:false,dead:false,st:'sleep',t:0,frame:0,anim:0};
  phMesh=makeBillboards([{x:0,y:-80,z:0,w,h,spr:'pha_0',tint:1}],desertMat);scene.add(phMesh);
  phEyeMat=bbMaterial(atlas,0,0);phEyes=makeBillboards([{x:0,y:-80,z:0,w:.42,h:.13,spr:'peyes',tint:1.7}],phEyeMat);scene.add(phEyes);}
function sarcoLooked(){if(!DSARCO||Math.abs(P.x-DSARCO.x)>4||Math.abs(P.z-DSARCO.z)>4)return false;const dx=DSARCO.x-P.x,dz=DSARCO.z-P.z,d=Math.hypot(dx,dz);if(d>3.4)return false;
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw);return d<1||(dx*fx+dz*fz)/d>.5;}
function useSarco(){if(pharaoh.awake){return;}if(countItem('goldscarab')<1){toast('Der Sarkophag ist versiegelt. Eine Vertiefung im Deckel hat die Form eines Käfers.');Snd.click();return;}
  removeItem('goldscarab',1);awakenPharaoh();}
function awakenPharaoh(){const p=pharaoh;Object.assign(p,{x:DSARCO.x,z:DSARCO.z,y:DSARCO.y,hp:PH_HP,awake:true,dead:false,st:'rise',t:0,summon:[false,false],blastT:6,atkT:0,swing:0});
  Snd.queenRoar();toast('Der goldene Skarabäus versinkt im Deckel …');for(let k=0;k<60;k++)spawnParticle(p.x+(Math.random()-.5)*3,p.y+1,p.z+(Math.random()-.5)*2,(Math.random()-.5)*4,2+Math.random()*4,(Math.random()-.5)*4,Math.random()<.3?0xe8b830:0xd8b070,1.8,.35);
  $('bossName').textContent=PH_NAME;const b=$('bossBar');b.classList.remove('open');b.hidden=false;$('bossFill').style.width='100%';$('bossHp').textContent=`${PH_HP} / ${PH_HP}`;
  const ab=$('areaBanner');ab.hidden=true;areaAnim=null;requestAnimationFrame(()=>requestAnimationFrame(()=>b.classList.add('open')));}
function phBarClose(){const b=$('bossBar');b.classList.remove('open');setTimeout(()=>{if(!(pharaoh&&pharaoh.awake&&!pharaoh.dead)&&!(boss&&!boss.dead))b.hidden=true;},900);}
function hurtPharaoh(n){const p=pharaoh;if(!p.awake||p.dead||p.st==='rise')return;p.hp-=n;p.hurt=.22;
  if(p.hp<=0){p.dead=true;p.st='dead';p.t=0;Snd.queenRoar();gainXP(800);spawnDrop('coin',8,p.x,p.y+1,p.z);spawnDrop('pharaohmask',1,p.x,p.y+1,p.z);spawnDrop('linen',4,p.x,p.y+1,p.z);
    toast(PH_NAME+' ist besiegt!');phBarClose();for(const m of mummies)if(m.add&&!m.dead&&m.st!=='off'){m.st='sink';m.t=0;}}}
function updatePharaoh(dt){const p=pharaoh;if(!p)return;const g=phMesh.geometry.attributes,eg=phEyes.geometry.attributes;
  if(sarcoLid){const want=p.awake&&!p.dead?1:(p.dead&&p.t<25?1:0);sarcoLid.userData.k=(sarcoLid.userData.k||0)+(want-(sarcoLid.userData.k||0))*Math.min(1,dt*1.5);const k=sarcoLid.userData.k;
    sarcoLid.position.set(DSARCO.lid0.x,DSARCO.lid0.y+k*.1,DSARCO.lid0.z+k*1.3);sarcoLid.rotation.x=k*.5;}
  updateBolts(dt);
  if(!p.awake){g.offset.array[1]=-80;eg.offset.array[1]=-80;g.offset.needsUpdate=eg.offset.needsUpdate=true;return;}
  p.t+=dt;if(p.hurt>0)p.hurt-=dt;let yo=0;const dp=Math.hypot(P.x-p.x,P.z-p.z),dTomb=Math.hypot(P.x-DTOMB.x,P.z-DTOMB.z);
  if(p.st==='rise'){const u=Math.min(1,p.t/3);yo=-p.h*.8*(1-u);p.frame='c';if(u>=1){p.st='fight';}}
  else if(p.st==='dead'){const k=Math.min(1,p.t/.7);p.rot=k*k*Math.PI/2;if(p.t>6)yo=-Math.min(1,(p.t-6)/2)*1.5;if(p.t>8.5){p.awake=false;p.rot=0;}}
  else if(p.st==='leave'){const u=Math.min(1,p.t/2.5);p.x+=(DSARCO.x-p.x)*Math.min(1,dt*3);p.z+=(DSARCO.z-p.z)*Math.min(1,dt*3);yo=-p.h*u;p.frame='c';if(u>=1){p.awake=false;}}
  else{ // Kampf
    if(state==='dead'||dTomb>55){p.st='leave';p.t=0;toast('Der Pharao kehrt in seinen Sarkophag zurück.');phBarClose();for(const m of mummies)if(m.add&&!m.dead&&m.st!=='off'){m.st='sink';m.t=0;}}
    else{const frac=p.hp/PH_HP;[.7,.35].forEach((th,k)=>{if(frac<th&&!p.summon[k]){p.summon[k]=true;Snd.queenRoar();for(let n=0;n<3;n++){const a=Math.random()*6.283;let x=p.x+Math.cos(a)*4,z=p.z+Math.sin(a)*4;if(inWall(x,z,.6)){x=p.x-4;z=p.z+(n-1)*2.5;}raiseMummy(x,z,true);}}});
      if(p.atkT>0)p.atkT-=dt;p.blastT-=dt;
      if(p.swing>0){p.swing-=dt;p.frame='a';if(p.swing<=0&&dp<3)takeDamage(28),Snd.hit('axe');}
      else if(p.cast>0){p.cast-=dt;p.frame='c';if(p.cast<=0)fireBolt(p);}
      else if(dp<2.4&&p.atkT<=0){p.swing=.6;p.atkT=1.8;}
      else if(p.blastT<=0&&dp>4&&dp<28){p.blastT=6+Math.random()*4;p.cast=.7;}
      else if(dp>2){const st=Math.min(dp-2,1.75*dt),ox=p.x,oz=p.z;p.x+=(P.x-p.x)/dp*st;p.z+=(P.z-p.z)/dp*st;collideColl(p,.6);p.anim+=Math.hypot(p.x-ox,p.z-oz)*1.1;p.frame=1+(Math.floor(p.anim)%2);}
      else p.frame=0;
      const bf=$('bossFill');bf.style.width=Math.max(0,frac*100).toFixed(1)+'%';const ht=`${Math.max(0,Math.ceil(p.hp))} / ${PH_HP}`,he=$('bossHp');if(he.textContent!==ht)he.textContent=ht;}
    p.y=getHeight(p.x,p.z);}
  g.offset.array[0]=p.x;g.offset.array[1]=p.y+yo-.03;g.offset.array[2]=p.z;g.rot.array[0]=p.rot||0;g.tint.array[0]=p.hurt>0?-1.3:p.st==='dead'?.75:1;
  const s=SPR['pha_'+p.frame];g.uvr.array[0]=s.u;g.uvr.array[1]=s.v;g.offset.needsUpdate=g.rot.needsUpdate=g.tint.needsUpdate=g.uvr.needsUpdate=true;
  const ex=camera.position.x-p.x,ez=camera.position.z-p.z,el=Math.hypot(ex,ez)||1,showE=p.st!=='dead';
  eg.offset.array[0]=p.x+ex/el*.1;eg.offset.array[2]=p.z+ez/el*.1;eg.offset.array[1]=showE?p.y+yo+p.h*(1-(SPR.pha_0.c.eyeY+1)/SPR.pha_0.h)-.06:-80;eg.offset.needsUpdate=true;}
function fireBolt(p){const ey=p.y+p.h*.6,dx=P.x-p.x,dz=P.z-p.z,dy=P.y+1-ey,d=Math.hypot(dx,dy,dz)||1;sandBolts.push({x:p.x,y:ey,z:p.z,vx:dx/d*11,vy:dy/d*11,vz:dz/d*11,t:0});Snd.jump();}
function updateBolts(dt){for(let i=sandBolts.length-1;i>=0;i--){const b=sandBolts[i];b.t+=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.z+=b.vz*dt;
  for(let k=0;k<3;k++)spawnParticle(b.x+(Math.random()-.5)*.6,b.y+(Math.random()-.5)*.6,b.z+(Math.random()-.5)*.6,(Math.random()-.5),(Math.random()-.5),(Math.random()-.5),k?0xd8b070:0xe8c88a,.5,.4);
  const hit=Math.hypot(b.x-P.x,b.z-P.z)<1.1&&Math.abs(b.y-(P.y+1))<1.3;if(hit&&state==='playing'){takeDamage(18);P.vx+=b.vx*.5;P.vz+=b.vz*.5;}
  if(hit||b.t>3||b.y<getHeight(b.x,b.z)||inWall(b.x,b.z,0)){for(let k=0;k<16;k++)spawnParticle(b.x,b.y,b.z,(Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4,0xd8b070,.8,.35);sandBolts.splice(i,1);}}}
const phAwake=()=>!!(pharaoh&&pharaoh.awake&&!pharaoh.dead);

/* ---- Sefu, der Sonnenpriester ---- */
const DPRIEST={name:'Sefu',role:'Sonnenpriester',d:{id:'sefu'},talk:0,x:0,y:0,z:0,h:1.8,w:1.3};
function desertLooked(){const v=DPRIEST;if(!v.mesh||Math.abs(P.x-v.x)>5||Math.abs(P.z-v.z)>5)return null;const dir=lookDir(),dx=v.x-P.x,dy=v.y+v.h*.5-(P.y+P.eye),dz=v.z-P.z,d=Math.hypot(dx,dy,dz);
  if(d>3.4||(dx*dir.x+dy*dir.y+dz*dir.z)/d<.75)return null;return v;}
let sefuT=0;function updatePriest(dt){const v=DPRIEST;if(!v.mesh)return;if(v.talk>0)v.talk-=dt;sefuT+=dt;
  if(v.fire&&Math.hypot(camera.position.x-v.x,camera.position.z-v.z)<80&&Math.random()<dt*8)spawnParticle(v.fire.x+(Math.random()-.5)*.3,v.fire.y+.5,v.fire.z+(Math.random()-.5)*.3,(Math.random()-.5)*.3,1.2+Math.random(),(Math.random()-.5)*.3,0xffa030,.9,.2);}
DIALOGS.Sefu={start:()=>'hello',nodes:{
  hello:()=>({text:FLAGS.metSefu?'Die Sonne mit dir, Wanderer. Was führt dich zurück in mein Lager?':'Ein Wanderer, so weit draußen? Setz dich ans Feuer. Ich bin Sefu, der letzte Priester der Sonne. Ich hüte dieses Land, seit die Menschen es verlassen haben.',
    enter:()=>{FLAGS.metSefu=1;},
    opts:[{label:'Was ist das für eine Wüste?',go:'desert'},{label:'Was hat es mit den Mumien auf sich?',go:'mummies'},{label:'Wer war der Pharao?',go:'pharaoh'},
      ...(countItem('silverscarab')>0?[{label:'Ich habe einen silbernen Skarabäus.',go:'scarab'}]:[]),
      {label:'Lass uns handeln.',act:()=>{openShop('Sefu');return null;}},{label:'Leb wohl.',go:null}]}),
  desert:()=>({text:'Einst war hier grünes Land. Dann kam der Sand und begrub alles. Tief im Osten liegt ein Dorf, das niemand mehr bewohnt, zumindest keiner, der noch atmet. Und weit im Nordosten ruht der Pharao in seiner Grabstätte.',opts:[{label:'Zurück',go:'hello'}]}),
  mummies:()=>({text:'Wenn die Sonne sinkt, steigen die Toten des Dorfes aus dem Sand. Sie sind langsam und dumm, aber ihre gelben Augen sehen weit. Brich ihren Blick, versteck dich hinter einer Mauer, und sie vergessen dich bald. Manche tragen noch silberne Skarabäen bei sich.',opts:[{label:'Zurück',go:'hello'}]}),
  pharaoh:()=>({text:'Pharao Kreakhotep. Er herrschte über dieses Land, bis der Sand kam. Sein Sarkophag ist mit einem Siegel verschlossen, das nur ein goldener Skarabäus bricht. Und einen goldenen Skarabäus kann nur ein Priester der Sonne weihen.',
    opts:[{label:'Kannst du mir einen weihen?',go:'how'},{label:'Zurück',go:'hello'}]}),
  how:()=>({text:'Bring mir einen silbernen Skarabäus, wie ihn die Mumien tragen. Dazu 8 Kreaker, denn das Gold muss irgendwoher kommen. Aber bedenke: Wer den Pharao weckt, muss gegen ihn bestehen.',opts:[{label:'Zurück',go:'hello'}]}),
  scarab:()=>({text:wallet()>=2400?'Ein silberner Skarabäus! Lange habe ich keinen mehr gesehen. Gib mir dazu 8 Kreaker, und ich weihe dir einen goldenen.':'Ein silberner Skarabäus, tatsächlich. Aber ohne 8 Kreaker für das Gold kann ich ihn nicht weihen.',
    trade:true,opts:[{label:'Hier, nimm beides. (8 Kreaker)',on:wallet()>=2400,act:()=>{removeItem('silverscarab',1);setWallet(wallet()-2400);if(addItem('goldscarab',1))spawnDrop('goldscarab',1,P.x,P.y+1,P.z);Snd.coin();FLAGS.scarabs=(FLAGS.scarabs||0)+1;return null;},go:'blessed'},
      {label:'Noch nicht.',go:'hello'}]}),
  blessed:()=>({text:'(Sefu hält den Käfer ins Feuer. Das Silber schmilzt, und Gold fließt über seine Flügel.) Nimm ihn. Leg ihn in die Vertiefung auf dem Sarkophag. Und möge die Sonne dich schützen.',opts:[{label:'Danke, Sefu.',go:'hello'}]})}};

/* =========================================================
   Wegweiser und Ortsschilder im Wald und in der Ebene
   ========================================================= */
const SIGN_WOOD=['#7a5430','#9a6e40','#bb8f5a','#d2a872'];
function drawSignBoard(text,dist,tip){const W=256,H=48,cv=document.createElement('canvas');cv.width=W;cv.height=H;const c=cv.getContext('2d');
  const body=tip==='r'?[[0,4],[W-30,4],[W-2,H/2],[W-30,H-4],[0,H-4]]:tip==='l'?[[W,4],[30,4],[2,H/2],[30,H-4],[W,H-4]]:[[0,4],[W,4],[W,H-4],[0,H-4]];
  c.beginPath();body.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=SIGN_WOOD[2];c.fill();
  c.save();c.clip();const r=mulberry32(text.length*31+(dist|0));for(let y=4;y<H-4;y+=2){c.fillStyle=r()<.5?SIGN_WOOD[1]:SIGN_WOOD[3];c.globalAlpha=.35;c.fillRect(0,y,W,1);}c.globalAlpha=1;
  for(let k=0;k<5;k++){c.fillStyle=SIGN_WOOD[0];c.fillRect(r()*W,6+r()*(H-12),6+r()*14,1);}c.restore();
  c.lineWidth=3;c.strokeStyle='#3a2410';c.stroke();
  const x0=tip==='l'?36:12,x1=tip==='r'?W-36:W-12;c.fillStyle='#1e0e04';c.textBaseline='middle';
  c.font='bold 27px Georgia, "Times New Roman", serif';c.textAlign='left';c.fillText(text,x0,H/2+1,(x1-x0)*(dist?.72:1));
  if(dist){c.font='bold 18px Georgia, serif';c.textAlign='right';c.fillText(dist<1000?Math.round(dist/10)*10+' m':(dist/1000).toFixed(1).replace('.',',')+' km',x1,H/2+1);}
  // Nägel
  c.fillStyle='#2a2a2a';const nx=tip==='l'?W-10:10;c.fillRect(nx-1,H/2-2,3,3);
  const t=new THREE.CanvasTexture(cv);t.magFilter=THREE.NearestFilter;t.minFilter=THREE.LinearFilter;t.generateMipmaps=false;return t;}
const SIGNS=[];
const treeNear=(x,z,r)=>trees.some(t=>t.r>0&&Math.hypot(t.x-x,t.z-z)<r+t.r);
function signPost(x,z,boards){for(const[ox,oz]of[[0,0],[1.6,0],[-1.6,0],[0,1.6],[0,-1.6],[2.4,2.4],[-2.4,-2.4]]){if(!treeNear(x+ox,z+oz,1.6)){x+=ox;z+=oz;break;}}
  const g=new THREE.Group(),y=getHeight(x,z)-.1;g.position.set(x,y,z);
  const wood=new THREE.MeshLambertMaterial({color:0x6a4626});
  const post=new THREE.Mesh(new THREE.BoxGeometry(.17,2.75,.17),wood);post.position.y=1.37;g.add(post);
  const cap=new THREE.Mesh(new THREE.BoxGeometry(.24,.08,.24),wood);cap.position.y=2.78;g.add(cap);
  boards.forEach(([label,tx,tz,fx,fz],i)=>{const a=Math.atan2(tz-z,tx-x),dist=fx==null?0:Math.hypot(fx-x,fz-z)*1.08;
    const b=new THREE.Group();b.rotation.y=-a;b.position.y=2.5-i*.5;g.add(b);
    const geo=new THREE.PlaneGeometry(2.1,.4);
    const f=new THREE.Mesh(geo,new THREE.MeshLambertMaterial({map:drawSignBoard(label,dist,'r'),transparent:true,alphaTest:.5}));f.position.set(1.12,0,.06);b.add(f);
    const bk=new THREE.Mesh(geo,new THREE.MeshLambertMaterial({map:drawSignBoard(label,dist,'l'),transparent:true,alphaTest:.5}));bk.rotation.y=Math.PI;bk.position.set(1.12,0,.03);b.add(bk);});
  scene.add(g);addProp(x,z,.25);SIGNS.push({x,z,g});}
function townSign(x,z,face,title,sub){for(const ox of[0,2,-2,4,-4]){if(!treeNear(x+ox,z,2)){x+=ox;break;}}const g=new THREE.Group(),y=getHeight(x,z)-.1;g.position.set(x,y,z);g.rotation.y=face;
  const wood=new THREE.MeshLambertMaterial({color:0x6a4626});for(const s of[-1,1]){const p=new THREE.Mesh(new THREE.BoxGeometry(.18,2.3,.18),wood);p.position.set(s*1.25,1.15,0);g.add(p);}
  const cv=document.createElement('canvas');cv.width=256;cv.height=104;const c=cv.getContext('2d');c.fillStyle=SIGN_WOOD[2];c.fillRect(0,0,256,104);
  for(let y=0;y<104;y+=2){c.fillStyle=y%6?SIGN_WOOD[1]:SIGN_WOOD[3];c.globalAlpha=.3;c.fillRect(0,y,256,1);}c.globalAlpha=1;c.strokeStyle='#3a2410';c.lineWidth=6;c.strokeRect(3,3,250,98);
  c.fillStyle='#2a1608';c.textAlign='center';c.textBaseline='middle';c.font='bold 42px Georgia, serif';c.fillText(title,128,sub?42:54,230);if(sub){c.font='italic 18px Georgia, serif';c.fillText(sub,128,80,230);}
  const t=new THREE.CanvasTexture(cv);t.magFilter=THREE.NearestFilter;t.minFilter=THREE.LinearFilter;t.generateMipmaps=false;
  const m=new THREE.MeshLambertMaterial({map:t});const bd=new THREE.Mesh(new THREE.BoxGeometry(2.6,1.05,.1),[wood,wood,wood,wood,m,m]);bd.position.y=1.75;g.add(bd);
  scene.add(g);addProp(x-Math.cos(face)*1.25,z+Math.sin(face)*1.25,.2);addProp(x+Math.cos(face)*1.25,z-Math.sin(face)*1.25,.2);}
function initSigns(){
  // Kreuzung im Wald: Nord-Süd-Pfad trifft den Ost-West-Pfad
  let cx=20,best=1e9;for(let x=-10;x<=50;x+=.25){const d=Math.abs(x-pathX(pathZ(x)));if(d<best){best=d;cx=x;}}const cz=pathZ(cx);
  const CODA_P=[0,690],PLAIN_P=[pathX(330),330],RED_P=[180,pathZ(180)],WEST_P=[-520,pathZW(-520)],NORD_P=[pathX(-300),-300],STORM_P=[0,WALL_Z+14],
    FROG_P=[FROG.x,FROG.z],COAST_P=[coastX(pathZW(-1000))+20,pathZW(-1000)],DES_P=[300,330],CAMP_P=[DCAMP.x,DCAMP.z],SP=[SPAWN.x,SPAWN.z];
  const S=(dx,dz)=>[cx+dx,cz+dz];
  signPost(cx+3,cz+3,[['Coda',...S(pathX(cz+40)-cx,40),...CODA_P],['Die Wüste',...S(pathX(cz+40)-cx,40),...DES_P],['Der Redwood',...S(40,pathZ(cx+40)-cz),...RED_P],
    ['Westwald',...S(-40,pathZ(cx-40)-cz),...WEST_P],['Nordwald',...S(pathX(cz-40)-cx,-40),...NORD_P]]);
  // Waldrand Westen
  {const x=-112,z=pathZW(x)+2.8;signPost(x,z,[['Froschdorf',x-40,pathZW(x-40),...FROG_P],['Die Küste',x-40,pathZW(x-40),...COAST_P],['Westwald',x-40,pathZW(x-40),...WEST_P],['Coda',x+40,pathZ(x+40),...CODA_P]]);}
  // Abzweig zum Froschdorf
  {const tz=FROG_TZ0+4,tx=frogTrailX(tz)+3;signPost(tx,tz,[['Froschdorf',frogTrailX(tz+30),tz+30,...FROG_P],['Die Küste',tx-40,pathZW(tx-40),...COAST_P],['Der Wald',tx+40,pathZW(tx+40),...SP]]);}
  // Waldrand Osten
  {const x=108,z=pathZ(x)+2.8;signPost(x,z,[['Der Redwood',x+40,pathZ(x+40),...RED_P],['Der Wald',x-40,pathZ(x-40),...SP]]);}
  // Waldrand Norden
  {const z=ZMIN+14,x=pathX(z)+2.8;signPost(x,z,[['Nordwald',pathX(z-40),z-40,...NORD_P],['Sturmburg',pathX(z-40),z-40,...STORM_P],['Coda',pathX(z+40),z+40,...CODA_P]]);}
  // Ebene: Waldausgang
  {const z=FOREST_END+16,x=pathX(z)+2.8;signPost(x,z,[['Coda',pathX(z+40),z+40,...CODA_P],['Die Wüste',x+40,z+30,...DES_P],['Der Wald',pathX(z-40),z-40,...SP]]);}
  // Ebene: vor der Brücke
  {const z=BR_Z0-8,x=pathX(z)+2.8;signPost(x,z,[['Coda',pathX(z+40),z+40,...CODA_P],['Die Wüste',x+40,z,...DES_P],['Der Wald',pathX(z-40),z-40,...SP]]);}
  // Ebene: Süden, Abzweig zu Sefus Lager
  {const z=476,x=pathX(z)+2.8;signPost(x,z,[['Coda',pathX(z+40),z+40,...CODA_P],['Sefus Lager',x+40,z,...CAMP_P],['Die Wüste',x+40,z,...DES_P],['Der Wald',pathX(z-40),z-40,...SP]]);}
  // Ortsschild Coda
  {const z=598,x=pathX(z)-3.4;townSign(x,z,0,'Coda','Gemeinde im Süden');}
  // Ortsschild Froschdorf
  {const z=FROG.z-13,x=frogTrailX(z)+2.6;townSign(x,z,0,'Froschdorf','Quaak!');}
}

