const POTIONS={hpot:{name:'Heiltrank',col:'#d8302a',heal:60,desc:'Heilt 60 Leben'},hpot2:{name:'Großer Heiltrank',col:'#a8101a',heal:150,big:1,desc:'Heilt 150 Leben'},
  pstr:{name:'Stärketrank',col:'#e8781a',buff:'str',dur:120,desc:'+50 % Schaden für 2 Minuten'},pspeed:{name:'Schnelligkeitstrank',col:'#3ad0e8',buff:'speed',dur:120,desc:'+35 % Tempo für 2 Minuten'},
  pregen:{name:'Regenerationstrank',col:'#e85aa8',buff:'regen',dur:45,desc:'+4 Leben pro Sekunde für 45 Sekunden'},pstam:{name:'Ausdauertrank',col:'#5ac83a',stam:1,desc:'Füllt die Ausdauer sofort auf'},
  pmana:{name:'Manatrank',col:'#2a5ae8',mana:1,desc:'Füllt das Mana sofort auf'},pmregen:{name:'Trank der Manaquelle',col:'#8a3ae0',buff:'mregen',dur:90,desc:'+3 Mana pro Sekunde für 90 Sekunden'}};
