function doorLooked(){if(P.x>IN_X){for(const d of INT_DOORS)if(Math.hypot(d.x-P.x,d.z-P.z)<2.4&&lookingAt(d.x,interiorFloor(d.x,d.z)+1.1,d.z,3,.6))return d;return null;}
  if(tavOut&&Math.hypot(tavOut.x-P.x,tavOut.z-P.z)<2.6&&lookingAt(tavOut.x,getHeight(tavOut.x,tavOut.z)+1.1,tavOut.z,3.2,.6))return{kind:'tavernEnter'};
  return typeof caveDoorLooked==='function'?caveDoorLooked():null;}
function useDoor(d){const T=TAVI,R=ROOMI;
  if(d.kind==='tavernEnter')enterInterior(T.x,T.z+T.d/2-1.2,0);
  else if(d.kind==='tavernExit'){const x=tavOut.x+tavOut.nx*1.6,z=tavOut.z+tavOut.nz*1.6;P.x=x;P.z=z;P.y=getHeight(x,z)+.05;P.vx=P.vy=P.vz=0;P.yaw=Math.atan2(-tavOut.nx,-tavOut.nz)+Math.PI;P.safe=[x,z];curArea=null;setTimeout(checkArea,150);Snd.click();}
  else if(d.kind==='room'){if(!FLAGS.room){toast('Abgeschlossen. Frag Hagen nach einem Zimmer.');Snd.click();return;}enterInterior(R.x-R.w/2+1.1,R.z,-Math.PI/2);}
  else if(d.kind==='roomExit')enterInterior(T.x+T.w/2-1.2,T.z+2.5,Math.PI/2);
  else if(typeof useCaveDoor==='function')useCaveDoor(d);}
