/* ---- Effekte von Rüstung und Edelsteinen ---- */
function armorFactor(){let d=0;for(const k of['helm','armor','boots']){const s=equip[k];if(s&&ITEMS[s.id].def)d+=ITEMS[s.id].def;}return 1-Math.min(.8,d);}
function gemList(){const L=[],h=inv[HOT0+sel];if(h&&h.gem)L.push(h.gem);for(const k of EQUIP_KEYS){const s=equip[k];if(s&&s.gem)L.push(s.gem);}return L;}
const gemCount=g=>gemList().filter(x=>x===g).length;
function weaponMult(target){const h=inv[HOT0+sel];let m=1;if(h&&h.gem==='ruby')m*=1.25;if(h&&h.gem==='diamond')m*=1.1;if(h&&h.gem==='blackdia')m*=1.4;
  const it=h&&ITEMS[h.id];if(it&&it.mat==='silver'&&target&&(target.kind==='mummy'||target.kind==='pharaoh'||(target.kind==='cavemob'&&target.type==='skeleton')))m*=MATS.silver.undead;return m;}
function gemRegen(dt){const S=P.stats;if(!S)return;const e=gemCount('emerald'),s=gemCount('sapphire');if(e&&S.hp<S.maxHp)S.hp=Math.min(S.maxHp,S.hp+1.5*e*dt);if(s&&S.mp<S.maxMp)S.mp=Math.min(S.maxMp,S.mp+2*s*dt);}
function trySocket(i){const s=inv[i];if(!cursor||!s||!ITEMS[cursor.id].gem)return false;const it=ITEMS[s.id];if(!(it.weapon||it.tool||it.slot)||it.gem||it.potion)return false;
  if(s.gem){toast('Da sitzt schon ein '+ITEMS[s.gem].name);return true;}s.gem=cursor.id;cursor.n--;if(!cursor.n)cursor=null;Snd.levelUp();toast(ITEMS[s.gem].name+' eingesetzt: '+GEMS[s.gem].fx);renderInv();renderCursor();return true;}
const itemLabel=s=>s?ITEMS[s.id].name+(s.gem?' ('+ITEMS[s.gem].name+')':'')+(s.n>1?' · '+s.n:''):'';
/* ---- Symbole ---- */
function drawOre(k){const p=new Px(14,12),R=pal(['#2a2a2e','#45464c','#62646a','#7e8086']),c=hex(ORES[k].col),c2=hex(shadeHex(ORES[k].col,.35));
  for(let y=1;y<12;y++)for(let x=1;x<13;x++){const dx=(x-6.5)/6,dy=(y-6.5)/5.2;if(dx*dx+dy*dy>1)continue;p.set(x,y,R[shadeIdx(.7-dx*.3-dy*.35,4,x,y)]);if(hash2(x,y,k.length*7)<(k==='coal'?.5:.28))p.set(x,y,(x+y)&1?c:c2);}
  outline(p);return p.done();}
function drawGem(k){const C=pal(GEMS[k].col),p=new Px(12,12);for(let y=1;y<11;y++)for(let x=1;x<11;x++){const dx=Math.abs(x-5.5),dy=y-4;if(y<4?dx>2+y*.8:dx>(11-y)*.85)continue;
    let L=.5+(y<4?.3:0)-(x-5.5)*.06+((x+y)%3===0?.2:0);if(k==='opal')p.set(x,y,hex(['#ffd0e8','#c0f0ff','#fff0c0','#e0d0ff'][(x+y*3)%4]));else p.set(x,y,C[shadeIdx(L,4,x,y)]);}
  p.set(4,2,hex('#ffffff'));outline(p);return p.done();}
function drawIngot(k){const M=k==='gold_ingot'?GOLD:pal(MATS[INGOTS[k][1]].pal),p=new Px(16,10);for(let y=2;y<9;y++){const ins=y<4?(4-y):0;for(let x=1+ins;x<15-ins;x++)p.set(x,y,M[y<4?3:shadeIdx(.6-(x-8)/20-(y-5)/10,M.length,x,y)]);}outline(p);return p.done();}
function drawMatIcon(m,t){const M=pal(MATS[m].pal),H=pal(['#3a2212','#5e3a1e','#86562c']),p=new Px(16,16);
  if(t==='pick'||t==='axe'||t==='sword'){const c=drawToolIcon(t==='pick'?'pick':t==='axe'?'axe':'sword','stone');const ctx=c.getContext('2d'),img=ctx.getImageData(0,0,16,16),d=img.data,ST=pal(['#3a3c40','#5c5f64','#82868c','#a8acb2']);
    for(let i=0;i<d.length;i+=4){for(let s=0;s<4;s++)if(d[i]===ST[s][0]&&d[i+1]===ST[s][1]&&d[i+2]===ST[s][2]){d[i]=M[s][0];d[i+1]=M[s][1];d[i+2]=M[s][2];}}ctx.putImageData(img,0,0);return c;}
  if(t==='helm'){for(let y=3;y<13;y++)for(let x=2;x<14;x++){const dx=(x-7.5)/5.5,dy=(y-9)/6;if(dy<0&&dx*dx+dy*dy>1)continue;if(y>10&&x>5&&x<10)continue;p.set(x,y,M[shadeIdx(.7-dx*.3-dy*.2,4,x,y)]);}for(let x=2;x<14;x++)p.set(x,11,M[0]);}
  else if(t==='armor'){for(let y=1;y<15;y++)for(let x=1;x<15;x++){const sh=y<5&&(x<3||x>12);const body=x>3&&x<12;if(!(sh||body||(y<7&&x>1&&x<14)))continue;if(y<3&&x>5&&x<10)continue;p.set(x,y,M[shadeIdx(.65-(x-7.5)/14-(y-7)/30+((x+y)&1?.08:0),4,x,y)]);}}
  else{for(let y=3;y<15;y++)for(let x=2;x<14;x++){const leg=(x<7&&y<11),foot=y>=11&&(x<7||(x>=9));if(x>=7&&x<9&&y<11)continue;if(!(leg||foot||(x>=9&&y<11)))continue;p.set(x,y,M[shadeIdx(.6-(y-9)/20,4,x,y)]);}}
  outline(p);return p.done();}
function drawTorchIcon(){const p=new Px(8,16);for(let y=6;y<16;y++){p.set(3,y,FW[2]);p.set(4,y,FW[1]);}for(let y=5;y<7;y++)for(let x=2;x<6;x++)p.set(x,y,hex('#3a3a3a'));
  const F=[hex('#fff4c0'),hex('#ffd060'),hex('#ff9a20'),hex('#d84a10')];for(let y=0;y<5;y++)for(let x=1;x<7;x++){const d=Math.abs(x-3.5)/(1+y*.5);if(d<1)p.set(x,y,F[Math.min(3,Math.floor(d*2+(4-y)*.4))]);}return p.done();}
function drawFurnace(){const p=new Px(26,30),S=pal(['#3a3634','#55504c','#706a64','#8a847c']);for(let y=0;y<30;y++)for(let x=0;x<26;x++){const brick=(y%5===0)||((x+(Math.floor(y/5)%2)*4)%8===0);if(y<6&&(x<8||x>17))continue;p.set(x,y,S[brick?0:shadeIdx(.6-(x-13)/30,4,x,y)]);}
  for(let y=16;y<26;y++)for(let x=7;x<19;x++){const t=(y-16)/10;p.set(x,y,hex(t<.3?'#2a1408':t<.6?'#c84a10':t<.85?'#ff9a20':'#ffe060'));}outline(p);return p.done();}
function caveItemSprites(list){for(let v=0;v<3;v++)list.push(['caveent'+v,drawCaveEntrance(v)]);for(const k in ORES)list.push(['node_'+k,drawOreNode(k)]);for(const k in GEMS)list.push(['node_'+k,drawOreNode(k)]);for(const k in ORES)list.push([k,drawOre(k)]);for(const k in GEMS)list.push([k,drawGem(k)]);for(const k in INGOTS)list.push([k,drawIngot(k)]);
  for(const[id,m,t]of MAT_ITEMS)list.push([id,drawMatIcon(m,t)]);list.push(['torch',drawTorchIcon()]);list.push(['furnace',drawFurnace()]);
  {const p=new Px(16,14),Y=pal(['#8a6a10','#c89a1a','#f0c830','#fff070']);for(let y=4;y<12;y++)for(let x=1;x<15;x++){const dx=(x-7.5)/7,dy=(y-11)/7;if(dx*dx+dy*dy>1)continue;p.set(x,y,Y[shadeIdx(.7-dx*.3-dy*.2,4,x,y)]);}
    for(let x=0;x<16;x++)p.set(x,12,Y[0]);for(let y=2;y<7;y++)for(let x=6;x<10;x++)p.set(x,y,hex(y<4?'#fffbe0':'#c8c8c8'));outline(p);list.push(['molehelm',p.done()]);}}

let craftStation='';
function openFurnace(){openCraft(true);craftStation='furnace';$('craftTitle').textContent='Schmelzofen';$('craftSub').textContent='Erze und Kohle werden hier zu Barren geschmolzen.';renderCraft();}

/* =========================================================
   Teil 2b: Höhlen – Eingänge, Generierung, Licht, Erze, Monster, Maulwürfe
   ========================================================= */
const CAVE_X0=63000,CAVE_SP=700,CN=72,CC=3,CAVE_COUNT=18;
const CAVES=[];let caveCur=null,caveBuiltI=-1;
const caveIdx=x=>Math.round((x-CAVE_X0)/CAVE_SP);
const CX=i=>CAVE_X0+i*CAVE_SP;
ITEMS.silk={name:'Spinnenseide',plural:'Spinnenseide'};ITEM_DESC.silk='Reißfest und klebrig';
/* ---- Eingänge in der Oberwelt ---- */
function placeCaveEntrances(){const r=mulberry32(31415),regions=[['old',2,-110,110,-110,110],['plain',3,-110,110,150,560],['west',5,-1020,-140,-110,820],['red',2,150,580,-110,110],['nord',3,-800,800,-800,-140],['desert',3,180,980,150,820]];
  const bad=(x,z)=>{if(!inWorld(x,z)||nearWater(x,z)||getHeight(x,z)<WATER+.6)return true;if(pathDist(x,z)<16)return true;if(Math.abs(x)<130&&z>590)return true;
    if(Math.hypot(x-FROG.x,z-FROG.z)<70||Math.hypot(x-WITCH.x,z-WITCH.z)<25)return true;for(const S of DSITES)if(Math.hypot(x-S.x,z-S.z)<S.r+25)return true;for(const k in NESTS)if(Math.hypot(x-NESTS[k].x,z-NESTS[k].z)<45)return true;
    if(Math.abs(x)<200&&z<WALL_Z+200&&z>MZ0-50)return true;for(const c of CAVES)if(Math.hypot(c.ex-x,c.ez-z)<120)return true;
    let n=0;for(const t of tgridNear(x,z))if(t.r>0&&Math.hypot(t.x-x,t.z-z)<4)n++;return n>0;};
  for(const[reg,n,x0,x1,z0,z1]of regions)for(let k=0;k<n;k++){for(let t=0;t<80;t++){const x=x0+r()*(x1-x0),z=z0+r()*(z1-z0);if(bad(x,z))continue;const a=r()*Math.PI*2;CAVES.push({i:CAVES.length,ex:x,ez:z,ea:a,reg});break;}}
  // seltene Maulwurfsdörfer
  CAVES.forEach(c=>{c.village=c.i===4||c.i===13;c.spiders=c.i%3===1;c.moles=c.i%5===2||c.i%5===4;c.mine=c.i%2===0;});}
function buildCaveEntrances(){const rock=new THREE.MeshPhongMaterial({color:0x6a6864,flatShading:true,shininess:0,specular:0}),moss=new THREE.MeshPhongMaterial({color:0x4a5a34,flatShading:true,shininess:0,specular:0}),
    dark=new THREE.MeshBasicMaterial({color:0x050404}),grp=new THREE.Group();
  for(const c of CAVES){const y=getHeight(c.ex,c.ez),fx=Math.cos(c.ea),fz=Math.sin(c.ea),rx=-fz,rz=fx,r=mulberry32(500+c.i);c.ey=y;
    const add=(ox,oy,oz,s,m)=>{const g=new THREE.DodecahedronGeometry(s,0),me=new THREE.Mesh(g,m||rock);me.position.set(c.ex+ox,y+oy,c.ez+oz);me.rotation.set(r()*3,r()*3,r()*3);me.scale.y=.8+r()*.4;grp.add(me);};
    // Felsbogen um die Öffnung
    for(let k=0;k<7;k++){const a=-Math.PI*.5+k/6*Math.PI,ox=Math.cos(a)*2.1,oy=Math.sin(Math.max(0,a+Math.PI*.5))*0+(1.2+Math.sin(k/6*Math.PI)*1.6);add(rx*ox-fx*.6,oy,rz*ox-fz*.6,1.1+r()*.5,k===3?moss:null);}
    add(-fx*2.4,1.2,-fz*2.4,2.4);add(-fx*2.6+rx*1.8,.6,-fz*2.6+rz*1.8,1.8);add(-fx*2.6-rx*1.8,.6,-fz*2.6-rz*1.8,1.8);
    const op=new THREE.Mesh(new THREE.PlaneGeometry(2.4,2.5),dark);op.position.set(c.ex-fx*.4,y+1.1,c.ez-fz*.4);op.rotation.y=Math.atan2(fx,fz);grp.add(op);
    frogProp(c.ex-fx*2.6,c.ez-fz*2.6,2.4,3);frogProp(c.ex-fx*.6+rx*2.1,c.ez-fz*.6+rz*2.1,.9,2.5);frogProp(c.ex-fx*.6-rx*2.1,c.ez-fz*.6-rz*2.1,.9,2.5);}
  scene.add(grp);}
function caveDoorLooked(){if(P.x>IN_X)return null;for(const c of CAVES){if(Math.abs(c.ex-P.x)>5||Math.abs(c.ez-P.z)>5)continue;const ox=c.ex-Math.cos(c.ea)*.3,oz=c.ez-Math.sin(c.ea)*.3;
    if(Math.hypot(ox-P.x,oz-P.z)<3.4&&lookingAt(ox,c.ey+1,oz,4,.5))return{kind:'caveEnter',i:c.i};}return null;}
function useCaveDoor(d){if(d.kind==='caveEnter'){const c=CAVES[d.i],D=caveData(d.i),[x,z]=cellW(d.i,D.ex,D.ez-1);enterInterior(x,z,0);caveEnterT=time;spawnCaveMobs(d.i);toast('Es ist dunkel hier unten …');}
  else if(d.kind==='caveExit'){const c=CAVES[d.i],x=c.ex+Math.cos(c.ea)*3.8,z=c.ez+Math.sin(c.ea)*3.8;P.x=x;P.z=z;P.y=getHeight(x,z)+.05;P.vx=P.vy=P.vz=0;P.yaw=Math.atan2(-Math.cos(c.ea),-Math.sin(c.ea))+Math.PI;P.safe=[x,z];curArea=null;setTimeout(checkArea,150);Snd.click();}}
let caveEnterT=0;
/* ---- Generierung ---- */
const cellW=(i,ix,iz)=>[CX(i)+(ix-CN/2+.5)*CC,(iz-CN/2+.5)*CC];
const caveFloorRaw=(i,x,z)=>(vnoise(x*.13,z*.13,700+i)-.5)*.9+(vnoise(x*.04,z*.04,720+i)-.5)*1.4;
function caveData(i){const c=CAVES[i];if(c.data)return c.data;const r=mulberry32(77000+i*991),N=CN,G=new Uint8Array(N*N),tag=new Uint8Array(N*N);
  const inb=(x,z)=>x>=2&&z>=2&&x<N-2&&z<N-2,open=(x,z,t)=>{if(!inb(x,z))return;G[z*N+x]=1;if(t)tag[z*N+x]=t;};
  const blob=(x,z,rad,t)=>{for(let dz=-rad;dz<=rad;dz++)for(let dx=-rad;dx<=rad;dx++)if(dx*dx+dz*dz<=rad*rad+.5+(r()-.5)*2)open(x+dx,z+dz,t);};
  const walk=(x,z,dir,steps,w,t)=>{const pts=[];for(let s=0;s<steps;s++){if(r()<.22)dir+=(r()<.5?-1:1)*Math.PI/2*(r()<.5?.5:1);x=Math.round(x+Math.cos(dir));z=Math.round(z+Math.sin(dir));
      if(!inb(x,z)){dir+=Math.PI;x=clamp(x,3,N-4);z=clamp(z,3,N-4);}open(x,z,t);if(w>1){open(x+1,z,t);open(x,z+1,t);}if(w>2){open(x-1,z,t);open(x,z-1,t);}pts.push([x,z]);}return pts;};
  const ex=N/2|0,ez=N-4;for(let k=0;k<3;k++)open(ex,ez-k);
  let trunk=walk(ex,ez-2,-Math.PI/2,55+((r()*20)|0),2);
  const all=[...trunk];
  for(let b=0;b<9;b++){const p=all[(r()*all.length)|0],d=(r()*4|0)*Math.PI/2,len=18+((r()*45)|0),w=r()<.4?2:1;all.push(...walk(p[0],p[1],d,len,w));}
  for(let k=0;k<7;k++){const p=all[(r()*all.length)|0];blob(p[0],p[1],2+((r()*2.4)|0));}
  // versteckte Taschen
  for(let k=0;k<6;k++){const p=all[(r()*all.length)|0];const pts=walk(p[0],p[1],(r()*4|0)*Math.PI/2,5+((r()*6)|0),1);const e=pts[pts.length-1];blob(e[0],e[1],1);}
  // Minenschacht
  let minePts=[];if(c.mine){const p=all[(r()*all.length)|0];let d=(r()*4|0)*Math.PI/2,x=p[0],z=p[1];for(let s=0;s<40;s++){if(s%10===9&&r()<.6)d+=(r()<.5?1:-1)*Math.PI/2;const nx=x+Math.round(Math.cos(d)),nz=z+Math.round(Math.sin(d));if(!inb(nx,nz))break;x=nx;z=nz;open(x,z,2);minePts.push([x,z]);}}
  // Maulwurfsdorf: großer Saal am Ende eines langen Ganges
  let vil=null;if(c.village){let best=null,bd=-1;for(const p of all){const d=Math.hypot(p[0]-ex,p[1]-ez);if(d>bd&&inb(p[0],p[1])){bd=d;best=p;}}
    const vx=clamp(best[0],12,N-13),vz=clamp(best[1],12,N-13);for(let z=vz-9;z<=vz+9;z++)for(let x=vx-10;x<=vx+10;x++){const q=((x-vx)/10.5)**2+((z-vz)/9.5)**2;if(q<1+(r()-.5)*.08)open(x,z,3);}
    walk(best[0],best[1],Math.atan2(vz-best[1],vx-best[0]),Math.ceil(Math.hypot(vx-best[0],vz-best[1]))+2,2,0);
    {let x=best[0],z=best[1];while(Math.abs(x-vx)+Math.abs(z-vz)>0){if(x!==vx)x+=Math.sign(vx-x);else z+=Math.sign(vz-z);open(x,z);open(x+1,z);}}vil={x:vx,z:vz};}
  // Tiefe per Breitensuche
  const dist=new Int16Array(N*N).fill(-1),Q=[ez*N+ex];dist[ez*N+ex]=0;let maxD=1;
  while(Q.length){const q=Q.shift(),x=q%N,z=(q/N)|0;for(const[dx,dz]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,nz=z+dz,k=nz*N+nx;if(nx<0||nz<0||nx>=N||nz>=N||!G[k]||dist[k]>=0)continue;dist[k]=dist[q]+1;if(dist[k]>maxD)maxD=dist[k];Q.push(k);}}
  for(let k=0;k<N*N;k++)if(G[k]&&dist[k]<0)G[k]=0;
  const D={G,tag,dist,maxD,ex,ez,mine:minePts,vil,r};c.data=D;genDeposits(i,D);return D;}
const caveSolidIdx=(D,ix,iz)=>ix<0||iz<0||ix>=CN||iz>=CN||!D.G[iz*CN+ix];
function caveCell(x,z){const i=caveIdx(x),ix=Math.floor((x-CX(i))/CC+CN/2),iz=Math.floor(z/CC+CN/2);return[i,ix,iz];}
function caveSolid(x,z){const[i,ix,iz]=caveCell(x,z);const c=CAVES[i];if(!c||!c.data)return true;return caveSolidIdx(c.data,ix,iz);}
function caveFloor(x,z){const i=caveIdx(x);return caveFloorRaw(i,x,z);}
function caveCollide(o,R){const[i,ix,iz]=caveCell(o.x,o.z),c=CAVES[i];if(!c||!c.data)return;const D=c.data,x0=CX(i)-CN/2*CC,z0=-CN/2*CC;
  for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){const cx=ix+dx,cz=iz+dz;if(!caveSolidIdx(D,cx,cz))continue;const bx0=x0+cx*CC,bz0=z0+cz*CC,bx1=bx0+CC,bz1=bz0+CC;
    const nx=clamp(o.x,bx0,bx1),nz=clamp(o.z,bz0,bz1),ddx=o.x-nx,ddz=o.z-nz,d=Math.hypot(ddx,ddz);
    if(d<R){if(d>1e-4){o.x=nx+ddx/d*R;o.z=nz+ddz/d*R;}else{const pen=[o.x-bx0,bx1-o.x,o.z-bz0,bz1-o.z],m=Math.min(...pen),k=pen.indexOf(m);if(k===0)o.x=bx0-R;else if(k===1)o.x=bx1+R;else if(k===2)o.z=bz0-R;else o.z=bz1+R;}o.hit=true;}}}
function caveLOS(ax,az,bx,bz){const d=Math.hypot(bx-ax,bz-az),n=Math.ceil(d/.6);for(let k=1;k<n;k++){const t=k/n;if(caveSolid(ax+(bx-ax)*t,az+(bz-az)*t))return false;}return true;}
/* ---- Erzvorkommen ---- */
const DEP_KIND={coal:{p:.035,vein:[2,5],d0:0},iron_ore:{p:.028,vein:[2,4],d0:.05},bauxite:{p:.03,vein:[2,5],d0:0},gold_ore:{p:.0065,vein:[1,3],d0:.3},silver_ore:{p:.0065,vein:[1,3],d0:.3},
  mythril_ore:{p:.0022,vein:[1,2],d0:.6},adamant_ore:{p:.0014,vein:[1,2],d0:.7},sapphire:{p:.0007,vein:[1,1],d0:.35,pocket:1},emerald:{p:.0007,vein:[1,1],d0:.35,pocket:1},ruby:{p:.0007,vein:[1,1],d0:.35,pocket:1},
  opal:{p:.0006,vein:[1,1],d0:.4,pocket:1},diamond:{p:.00035,vein:[1,1],d0:.55,pocket:1},blackdia:{p:.00007,vein:[1,1],d0:.8,pocket:1}};
function genDeposits(i,D){const r=mulberry32(91000+i*37),N=CN,faces=[];D.deps=[];
  for(let iz=0;iz<N;iz++)for(let ix=0;ix<N;ix++){if(!D.G[iz*N+ix])continue;const dd=D.dist[iz*N+ix]/D.maxD,nOpen=[[1,0],[-1,0],[0,1],[0,-1]].filter(([a,b])=>!caveSolidIdx(D,ix+a,iz+b)).length;
    for(const[dx,dz]of[[1,0],[-1,0],[0,1],[0,-1]])if(caveSolidIdx(D,ix+dx,iz+dz))faces.push({ix,iz,dx,dz,dd,dead:nOpen<=1});}
  const used=new Set(),key=f=>f.ix+','+f.iz+','+f.dx+','+f.dz;
  for(const f of faces){if(used.has(key(f))||D.tag[f.iz*N+f.ix]===3)continue;for(const k in DEP_KIND){const K=DEP_KIND[k];if(f.dd<K.d0)continue;let p=K.p*(1+f.dd*.8);if(K.pocket&&f.dead)p*=5;if(r()>=p)continue;
      const n=K.vein[0]+((r()*(K.vein[1]-K.vein[0]+1))|0);let cur=f;for(let v=0;v<n&&cur;v++){used.add(key(cur));D.deps.push({k,ix:cur.ix,iz:cur.iz,dx:cur.dx,dz:cur.dz,y:.5+r()*1.6,s:r()});
        const nb=faces.find(g=>!used.has(key(g))&&g.dx===cur.dx&&g.dz===cur.dz&&Math.abs(g.ix-cur.ix)+Math.abs(g.iz-cur.iz)===1);cur=nb;}break;}}
  D.deps.forEach((d,j)=>d.j=j);}
/* ---- Licht ---- */
const CAVE_LIGHTS=[];
function initCaveLights(){for(let k=0;k<8;k++){const l=new THREE.PointLight(0xffb060,0,12,1.6);l.position.set(0,-5000,0);scene.add(l);CAVE_LIGHTS.push(l);}}
function caveSources(){const L=[];if(!caveCur)return L;const C=caveCur,D=C.D;
  for(const t of C.torches)L.push({x:t.x,y:t.y+1.15,z:t.z,col:0xffa050,I:1.7,dist:13,flick:1});
  for(const s of C.lamps)L.push(s);
  for(const m of caveMobs)if(!m.dead&&m.type==='mole'&&m.helmet)L.push({x:m.x,y:m.y+1.4,z:m.z,col:0xfff0b0,I:1.1,dist:9});
  for(const q of storyCaveSrc())L.push(q);return L;}
function playerLightSrc(){const h=inv[HOT0+sel],torch=h&&h.id==='torch',lamp=equip.helm&&ITEMS[equip.helm.id].lamp;if(!torch&&!lamp)return null;
  return{x:P.x,y:P.y+(torch?1.4:1.75),z:P.z,col:torch?0xffa050:0xfff0c0,I:torch?1.6:1.3,dist:torch?12:10,flick:torch?1:0};}
