    for(let q=0;q<3;q++){const sl=new THREE.Mesh(new THREE.BoxGeometry(along==='z'?1.2:.18,.06,along==='x'?1.2:.18),wood);sl.position.set(x+(along==='x'?(q-1):0),fy+.04,z+(along==='z'?(q-1):0));caveGroup.add(sl);}
