function caveMobSprites(list){for(const f of[0,1,2,'a']){list.push(['skel_'+f,drawSkeleton(f)]);list.push(['spid_'+f,drawSpider(f)]);const rp=drawRat(f);outline(rp);list.push(['rat_'+f,rp.done()]);for(let v=0;v<4;v++)list.push(['mole'+v+'_'+f,drawMole(f,v)]);}
  {const p=new Px(14,12);for(let y=1;y<11;y++)for(let x=1;x<13;x++){const dx=(x-6.5)/6,dy=(y-6)/5;if(dx*dx+dy*dy>1)continue;p.set(x,y,hex(((x+y*2)%5===0)?'#c8c8d0':((x*3+y)%4===0)?'#ffffff':'#e4e4ec'));}outline(p);list.push(['silk',p.done()]);}
  list.push(['web',drawWeb()]);list.push(['cmush',drawCMush()]);list.push(['lantern',drawLantern()]);{const c=drawTorchIcon();list.push(['torchbb',c]);}}
function mobSpr(m){return m.type==='skeleton'?'skel_':m.type==='spider'?'spid_':m.type==='rat'?'rat_':'mole'+m.var+'_';}
function newMob(type,x,z,ex){const s=SPR[mobSpr({type,var:ex&&ex.var||0})+'0'],T=MOB[type],h=T.h,w=h*s.w/s.h;const m=Object.assign({type,x,z,y:caveFloor(x,z),h,w,hp:T.hp,frame:0,anim:0,atkT:0,tx:x,tz:z,wait:Math.random()*3,var:0,flip:false},ex||{});caveMobs.push(m);return m;}
function spawnCaveMobs(i){const c=CAVES[i];if(caveBuiltI!==i)buildCave(i);caveMobs.length=0;const D=c.data,r=mulberry32((FLAGS.day||0)*31+i*7+((time*10)|0)),open=[];
  for(let k=0;k<CN*CN;k++)if(D.G[k]&&D.dist[k]>8&&D.tag[k]!==3)open.push(k);const pick=()=>{const k=open[(r()*open.length)|0];const[x,z]=cellW(i,k%CN,(k/CN)|0);return[x+(r()-.5)*1.5,z+(r()-.5)*1.5,D.dist[k]/D.maxD];};
  const n=(a,b)=>a+((r()*(b-a+1))|0);
  for(let k=n(6,10);k>0;k--){const[x,z]=pick();newMob('skeleton',x,z);}for(let k=n(4,7);k>0;k--){const[x,z]=pick();newMob('rat',x,z);}
  if(c.spiders)for(let k=n(4,6);k>0;k--){const[x,z,d]=pick();newMob('spider',x,z);}
  if(c.moles)for(let k=n(2,4);k>0;k--){const[x,z]=pick();const nm=MOLE_NAMES[(r()*MOLE_NAMES.length)|0]+' ('+(k)+')';addMoleNPC(nm,x,z,{helmet:true,var:0,trader:r()<.5,seed:r()});}
  if(D.vil)spawnMoleVillage(i,D);
  renderCaveMobs();}
function addMoleNPC(name,x,z,o){const m=newMob('mole',x,z,Object.assign({name,role:o.role||'Minenmaulwurf',d:{id:'mole'},talk:0},o));const pc=document.createElement('canvas');pc.width=pc.height=22;const cx=pc.getContext('2d');cx.imageSmoothingEnabled=false;
  cx.drawImage(SPR['mole'+(o.var||0)+'_0'].c,8,2,24,24,0,0,22,22);m.portrait=pc;
  if(o.shop)SHOPS[name]=o.shop;else if(o.trader){const rr=mulberry32((o.seed*1e6)|0),ks=Object.keys(ORES).filter(k=>rr()<.55||k==='coal').slice(0,3);SHOPS[name]={title:name+', Minenmaulwurf',greet:'Erze? Hab ich. Billig? Nö.',
    buy:ks.map(k=>[k,Math.round(ORES[k].v*(1.7+rr()*.4))]),sell:Object.keys(ORES).map(k=>[k,Math.max(1,Math.round(ORES[k].v*.4))])};}
  DIALOGS[name]={start:()=>'hello',nodes:{hello:()=>({text:m.angry?'Grrr! Du hast mich angegriffen! Verschwinde!':o.text||(o.trader||o.shop?'Glück auf! Ich bin '+name.replace(/ \(.*\)/,'')+'. Willst du handeln? Meine Preise sind fair. Für mich.':'Glück auf! Heute handle ich nicht. Vorsicht, weiter hinten klappern die Skelette.'),
    opts:[...((o.trader||o.shop)&&!m.angry?[{label:'Lass uns handeln.',act:()=>{openShop(name);return null;}}]:[]),{label:'Was machst du hier unten?',go:'what'},{label:'Glück auf!',go:null}]}),
    what:()=>({text:o.what||'Graben! Was sonst? Die Erze singen, wenn man genau hinhört. Je tiefer, desto schöner der Gesang. Ganz tief unten soll es sogar schwarze Diamanten geben.',opts:[{label:'Zurück',go:'hello'}]})}};return m;}
let mobMesh=null;
function initCaveMobs(atlas){caveBBMat=bbMaterial(atlas,0,0);caveBBMat.uniforms.plOn.value=0;caveRockMat=caveTriMat();
  const L=[];for(let k=0;k<MOB_N;k++)L.push({x:0,y:-999,z:0,w:.01,h:.01,spr:'skel_0',tint:1});mobMesh=makeBillboards(L,caveBBMat);mobMesh.geometry.instanceCount=0;scene.add(mobMesh);}
function renderCaveMobs(){if(!mobMesh)return;const g=mobMesh.geometry.attributes;const n=Math.min(MOB_N,caveMobs.length);for(let k=0;k<n;k++){const m=caveMobs[k],s=SPR[mobSpr(m)+m.frame];
  g.offset.array[k*3]=m.x;g.offset.array[k*3+1]=m.y+(m.yo||0);g.offset.array[k*3+2]=m.z;g.size.array[k*2]=m.h*s.w/s.h;g.size.array[k*2+1]=m.h;g.rot.array[k]=m.rot||0;
  g.uvr.array[k*4]=m.flip?s.u+s.du:s.u;g.uvr.array[k*4+1]=s.v;g.uvr.array[k*4+2]=m.flip?-s.du:s.du;g.uvr.array[k*4+3]=s.dv;g.tint.array[k]=m.hurt>0?-1.3:lightAt(m.x,m.y+1,m.z)*(m.dead?.7:1);}
  mobMesh.geometry.instanceCount=n;g.offset.needsUpdate=g.size.needsUpdate=g.uvr.needsUpdate=g.tint.needsUpdate=g.rot.needsUpdate=true;}
function hurtCaveMob(m,n,by){if(m.dead)return;m.hp-=n;m.hurt=.22;if(m.type==='mole'){if(by==='player'){m.angry=true;m.talk=0;}}else if(by==='player')m.chase=true;
  if(m.hp<=0){m.dead=true;m.deadT=0;m.fallDir=Math.random()<.5?-1:1;Snd.thud();if(by==='player')gainXP(MOB[m.type].xp);
    if(m.type==='skeleton'){if(Math.random()<.6)spawnDrop('bones',1+(Math.random()<.4?1:0),m.x,m.y+.5,m.z);if(Math.random()<.25)spawnDrop('coal',1,m.x,m.y+.5,m.z);if(Math.random()<.3)spawnDrop('copper',rint(1,6),m.x,m.y+.5,m.z);}
    else if(m.type==='spider'){spawnDrop('silk',1+(Math.random()<.5?1:0),m.x,m.y+.5,m.z);}
    else if(m.type==='rat'){if(Math.random()<.35)spawnDrop('meat',1,m.x,m.y+.5,m.z);}
    else{if(Math.random()<.15)spawnDrop('molehelm',1,m.x,m.y+.5,m.z);spawnDrop('copper',rint(2,8),m.x,m.y+.5,m.z);if(Math.random()<.4)spawnDrop('coal',1+(Math.random()*2|0),m.x,m.y+.5,m.z);}}}
function updateCaveMobs(dt){if(!caveCur||P.x<CAVE_X0-400){if(mobMesh)mobMesh.geometry.instanceCount=0;return;}const alive=state!=='dead';
  for(const m of caveMobs){const T=MOB[m.type];if(m.hurt>0)m.hurt-=dt;if(m.atkT>0)m.atkT-=dt;
    if(m.dead){m.deadT+=dt;const k=Math.min(1,m.deadT/.45);m.rot=m.fallDir*k*k*Math.PI/2;m.yo=m.deadT>4?-Math.min(1,(m.deadT-4)/1.5)*.8:0;continue;}
    const dp=Math.hypot(P.x-m.x,P.z-m.z);let tgt=null,tx=null,tz=null,sp=0;
    if(m.type==='mole'){if(m.talk>0){m.talk-=dt;m.frame=0;continue;}
      if(m.angry&&alive&&dp<20)tgt='player';else{let best=null,bd=9;for(const o of caveMobs)if(o!==m&&!o.dead&&o.type!=='mole'){const d=Math.hypot(o.x-m.x,o.z-m.z);if(d<bd){bd=d;best=o;}}tgt=best;}}
    else{m.losT=(m.losT||0)-dt;if(m.losT<=0){m.losT=.25;m.sees=alive&&dp<24&&caveLOS(m.x,m.z,P.x,P.z);}
      if(m.sees&&dp<T.aggro)m.chase=true;if(m.chase){if(m.sees){m.lx=P.x;m.lz=P.z;m.lost=0;}else m.lost=(m.lost||0)+dt;if(m.lost>6||dp>28||!alive)m.chase=false;}
      if(m.chase)tgt='player';else{let best=null,bd=6;for(const o of caveMobs)if(o.type==='mole'&&!o.dead){const d=Math.hypot(o.x-m.x,o.z-m.z);if(d<bd){bd=d;best=o;}}tgt=best;}}
    if(tgt==='player'){tx=m.type==='mole'||m.sees?P.x:m.lx;tz=m.type==='mole'||m.sees?P.z:m.lz;sp=T.spd;if(dp<T.reach){sp=0;if(m.atkT<=0&&state==='playing'){m.atkT=1.3;m.swing=.35;}}}
    else if(tgt){const d=Math.hypot(tgt.x-m.x,tgt.z-m.z);tx=tgt.x;tz=tgt.z;sp=T.spd*.9;if(d<T.reach+.2){sp=0;if(m.atkT<=0){m.atkT=1.4;hurtCaveMob(tgt,T.dmg,'mob');}}}
    else{if(m.wait>0){m.wait-=dt;}else{if(Math.hypot(m.tx-m.x,m.tz-m.z)<.4){m.wait=1+Math.random()*4;const a=Math.random()*6.283,r=2+Math.random()*7,nx=(m.hx??m.x)+Math.cos(a)*r,nz=(m.hz??m.z)+Math.sin(a)*r;if(!caveSolid(nx,nz)){m.tx=nx;m.tz=nz;}}else{tx=m.tx;tz=m.tz;sp=T.spd*.35;}}}
    if(m.swing>0){m.swing-=dt;if(m.swing<=0&&dp<T.reach+.6&&state==='playing'){takeDamage(T.dmg);Snd.hit('sword');}}
    if(tx!=null&&sp>0){const dx=tx-m.x,dz=tz-m.z,d=Math.hypot(dx,dz);if(d>.05){const st=Math.min(d,sp*dt),ox=m.x,oz=m.z;m.x+=dx/d*st;m.z+=dz/d*st;caveCollide(m,.35);if(dp<.7&&tgt==='player'){m.x=ox;m.z=oz;}
        const moved=Math.hypot(m.x-ox,m.z-oz);if(moved<st*.3&&tgt!=='player'){m.tx=m.x;m.tz=m.z;}m.anim+=moved*(m.type==='rat'?2.4:1.6);m.frame=1+(Math.floor(m.anim)%2);m.flip=m.type==='rat'&&((dx*Math.cos(P.yaw)-dz*Math.sin(P.yaw))<0);}}
    else m.frame=0;if(m.swing>0||m.atkT>1)m.frame='a';
    m.y=caveFloor(m.x,m.z);
    if(m.type!=='mole'&&m.sees&&dp<12&&Math.random()<dt*.15)mobSound(m);}
  for(let k=caveMobs.length-1;k>=0;k--)if(caveMobs[k].dead&&caveMobs[k].deadT>6)caveMobs.splice(k,1);
  renderCaveMobs();}
function mobSound(m){const c=Snd.ctx;if(!c)return;const t=c.currentTime;if(m.type==='skeleton'){for(let k=0;k<4;k++)Snd.tone('square',900+Math.random()*400,t+k*.05,.03,.03,null,3000);}
  else if(m.type==='rat'){const{o}=Snd.tone('square',1800,t,.08,.02,null,4000);o.frequency.exponentialRampToValueAtTime(2600,t+.08);}else{const{o}=Snd.tone('sawtooth',140,t,.3,.03,null,600);o.frequency.linearRampToValueAtTime(90,t+.3);}}
const caveNPCLooked=()=>caveCur&&P.x>CAVE_X0-400?lookNPC(caveMobs.filter(m=>m.type==='mole'&&!m.dead&&!m.angry)):null;
