function realmLightSrc(){const L=[];for(const b of realmBraziers)L.push({x:b.x,y:b.y+1.8,z:b.z,col:b.fountain?0xff5a10:0xff8a30,I:b.fountain?2:1.6,dist:b.fountain?16:12,flick:1});return L;}
function realmMood(){sky.visible=false;hemi.color.setRGB(1,.5,.4);hemi.intensity=1.05;sun.color.setRGB(1,.5,.32);sun.intensity=.62;scene.fog.color.setRGB(.3,.06,.04);LIGHT_COL.setRGB(1,.7,.6);setBBLight(1);realmSetFog(30,430);}
function realmSetFog(near,far){scene.fog.near=near;scene.fog.far=far;for(const m of[decorMat,pickMat,waterMat,villMat,nordMat,westMat,stormMat,guardMat,playerMat,animalMat,dropMat,mountMesh&&mountMesh.material,riderMesh&&riderMesh.material,spyMesh&&spyMesh.material,miniMesh&&miniMesh.material,...EXTRA_BB]){if(!m)continue;m.uniforms.fogNear.value=near;m.uniforms.fogFar.value=far;}}
function updateRealm(dt){if(!realmBuilt)return;const inR=P.x>REALM_X0-60&&P.x<REALM_X1+60&&state!=='menu';realmGrp.visible=inR;const wf=inR?950:Math.max(260,(settings.renderDist||140)*1.6);if(Math.abs(camera.far-wf)>1){camera.far=wf;camera.updateProjectionMatrix();}if(!inR)return;
  const F=camera.far*.9;realmSky.scale.setScalar(F);realmSky.position.copy(camera.position);realmMoon.position.set(camera.position.x+F*.3,camera.position.y+F*.5,camera.position.z-F*.7);realmMoon.scale.setScalar(F*.28);lavaTex.offset.x=(time*.012)%1;lavaTex.offset.y=(time*.007)%1;
  for(const b of realmBraziers)if(Math.abs(b.x-P.x)<60&&Math.abs(b.z-P.z)<60&&Math.random()<dt*6)spawnParticle(b.x+(Math.random()-.5)*.5,b.y+(b.fountain?.3:1.7),b.z+(Math.random()-.5)*.5,(Math.random()-.5)*.3,1+Math.random()*1.5,(Math.random()-.5)*.3,Math.random()<.5?0xff6a10:0xffd040,.7,.25);
  if(Math.random()<dt*3){const x=P.x+(Math.random()-.5)*60,z=P.z+(Math.random()-.5)*60;if(realmFloor(x,z)<LAVA_Y+.3)for(let k=0;k<6;k++)spawnParticle(x,LAVA_Y+.2,z,(Math.random()-.5),2+Math.random()*3,(Math.random()-.5),0xffb030,.9,.3);}
  // Lava verbrennt
  if(state==='playing'&&P.y<LAVA_Y+.35&&realmFloor(P.x,P.z)<LAVA_Y+.2){P.lavaT=(P.lavaT||0)+dt;if(P.lavaT>.4){P.lavaT=0;takeDamage(9);P.burnT=Math.max(P.burnT||0,2);}}
  if(portcullis){const want=FLAGS.gateOpen?CY+9.5:CY;portcullis.position.y+=(want-portcullis.position.y)*Math.min(1,dt*1.2);}}

/* ---- Ritual am Steinkreis ---- */
let malE=null,ritualFx=0,portalK=0;
const altarLooked=()=>Math.hypot(P.x-CIRCLE.x,P.z-CIRCLE.z)<3.8&&lookingAt(CIRCLE.x,CIRCLE.y,CIRCLE.z,4.5,.55);
const portalLooked=()=>FLAGS.portalOpen&&Math.hypot(P.x-CIRCLE.x,P.z-CIRCLE.z)<4.5&&lookingAt(CIRCLE.x,CIRCLE.y+3,CIRCLE.z,6,.45);
const rPortalLooked=()=>Math.hypot(P.x-R_ARRIVE.x,P.z-R_ARRIVE.z)<4.5&&lookingAt(R_ARRIVE.x,realmFloor(R_ARRIVE.x,R_ARRIVE.z)+3,R_ARRIVE.z,6,.45);
function startRitual(){FLAGS.hearts=Math.max(0,(FLAGS.hearts||0)-3);ritualFx=1;
  playCine([{t:'(Du legst die drei Dämonenherzen auf den Altar. Sie beginnen zu schlagen, langsam, dann immer schneller.)',fn:()=>Snd.demonRoar(.6,.6)},
    {who:'Kreak',t:'Der Blutmond trinkt sie. Gleich … gleich ist es so weit.'},
    {t:'(Ein roter Strahl schießt in den Himmel. Über dem Altar reißt die Luft auf wie Stoff. Dahinter: Feuer.)',fn:()=>{portalK=.01;Snd.boom(.3);}},
    {t:'(Aus dem Riss tritt ein Ritter in schwarzer Rüstung. Seine Flügel verdunkeln den Mond.)',fn:()=>spawnMalphas()},
    {who:'Malphas',t:'Niemand betritt das Reich der Königin. Nicht ohne über meine Klinge zu gehen.'},
    {who:'Kreak',t:'Malphas. Ich erinnere mich an dich. Letztes Mal hast du auch so groß getönt.'}],()=>{Snd.demonRoar(.9,1.2);mqSet(9);});}
function spawnMalphas(){malE=spawnEnt('malphas',CIRCLE.x,CIRCLE.z-5,{home:{x:CIRCLE.x,z:CIRCLE.z}});const e=malE;
  e.special=(e,dt)=>{const pd=Math.hypot(P.x-e.x,P.z-e.z);e.fl=(e.fl||5)-dt;e.lp=(e.lp||9)-dt;
    if(!e.sum&&e.hp<e.max*.5){e.sum=1;Snd.demonRoar(1,1);for(let k=0;k<2;k++)spawnEnt('warrior',e.x+(k?3:-3),e.z+2,{aggro:60});say(e,'Zu mir, meine Krieger!',3);}
    if(e.act==='line'){e.actT-=dt;e.frame='a';if(e.actT<=0&&e.lk<9){e.actT=.11;const d=2+e.lk*2.1,x=e.lx0+e.ldx*d,z=e.lz0+e.ldz*d,y=groundAt(x,z,99);e.lk++;Snd.whoosh(300,.06);
        for(let k=0;k<10;k++)spawnParticle(x+(Math.random()-.5)*1.2,y+.2,z+(Math.random()-.5)*1.2,(Math.random()-.5)*1.5,2+Math.random()*4,(Math.random()-.5)*1.5,Math.random()<.5?0xff4a10:0xffc040,.6,.35);
        if(Math.hypot(P.x-x,P.z-z)<1.7&&P.y-y<1.5)meleeHit(e,'player',20);for(const o of DEM)if(o.fac==='ally'&&!o.dead&&Math.hypot(o.x-x,o.z-z)<1.7)hurtEnt(o,20,'demon');}
      if(e.lk>=9)e.act=null;return true;}
    if(e.act==='leap'){e.actT+=dt;const u=Math.min(1,e.actT/1.1);e.x=e.jx0+(e.jx1-e.jx0)*u;e.z=e.jz0+(e.jz1-e.jz0)*u;e.flyOff=Math.sin(u*Math.PI)*7;e.frame='c';
      if(u>=1){e.act=null;e.flyOff=0;Snd.boom(.3);for(let k=0;k<50;k++){const a=k/50*6.28;spawnParticle(e.x+Math.cos(a)*2,e.gy+.3,e.z+Math.sin(a)*2,Math.cos(a)*8,1.5,Math.sin(a)*8,0xff6a20,.6,.35);}
        if(pd<4.8)meleeHit(e,'player',28);for(const o of DEM)if(o.fac==='ally'&&!o.dead&&Math.hypot(o.x-e.x,o.z-e.z)<4.8)hurtEnt(o,28,'demon');}return true;}
    if(e.tgt==='player'&&pd>5&&pd<16&&e.fl<=0){e.fl=8+Math.random()*3;e.act='line';e.actT=.6;e.lk=0;e.lx0=e.x;e.lz0=e.z;const d=pd||1;e.ldx=(P.x-e.x)/d;e.ldz=(P.z-e.z)/d;Snd.demonRoar(1.3,.6);return true;}
    if(e.tgt==='player'&&pd>9&&pd<26&&e.lp<=0){e.lp=11+Math.random()*4;e.act='leap';e.actT=0;e.jx0=e.x;e.jz0=e.z;e.jx1=P.x;e.jz1=P.z;Snd.whoosh(200,.2);return true;}
    return false;};
  e.onDeath=()=>{FLAGS.portalOpen=1;setTimeout(()=>{playCine([{t:'(Malphas sinkt auf die Knie. Seine Rüstung zerfällt zu Asche, die der rote Wind davonträgt.)'},{who:'Kreak',t:'Das Tor steht offen. Dahinter wartet sie.'},{who:'Kreak',t:'Bist du bereit? Wenn nicht, ist das in Ordnung. Das Tor schließt sich nicht mehr. Aber lange warten will ich nicht.'}],()=>mqSet(10));},1800);};}
function enterRealm(){const h=realmFloor(R_ARRIVE.x,R_ARRIVE.z);P.x=R_ARRIVE.x;P.z=R_ARRIVE.z-5;P.y=h+.2;P.vx=P.vy=P.vz=0;P.yaw=0;P.safe=[P.x,P.z];curArea=null;Snd.boom(.2);
  if(P.riding)dismount(true);setTimeout(checkArea,150);realmSpawnWave('path');
  if(mqIs('portal'))setTimeout(()=>playCine([{t:'(Hitze schlägt dir entgegen. Der Himmel ist rot, der Boden schwarz, und in der Ferne glüht ein Schloss aus dunklem Stein.)'},{who:'Kreak',t:'Die Unterwelt. Ich war schon einmal hier. Ich … erinnere mich an den Geruch.'},{who:'Kreak',t:'Ihr Schloss. Das Tor wird bewacht sein. Lass uns gehen.'}],()=>mqSet(11)),400);}
function leaveRealm(){const x=CIRCLE.x+4,z=CIRCLE.z+6;P.x=x;P.z=z;P.y=getHeight(x,z)+.2;P.vx=P.vy=P.vz=0;P.safe=[x,z];curArea=null;setTimeout(checkArea,150);Snd.boom(.15);for(const e of DEM.slice())if(e.fac==='demon'&&inRealm(e.x))removeEnt(e);realmWaves={};}
/* ---- Gegner der Unterwelt ---- */
let realmWaves={},shkE=null;
function realmSpawnWave(id){if(realmWaves[id])return;realmWaves[id]=1;const W=[];
  if(id==='path'){for(const[z,list]of[[240,['imp','imp','imp']],[150,['hound','hound','warrior']],[60,['warrior','warrior','imp','imp']]])list.forEach((t,k)=>W.push([t,realmPathX(z)+(k-1)*4,z-(k%2)*3]));}
  if(id==='gate'&&!FLAGS.gateOpen){W.push(['knight',RX-5,-22,{gateG:1,scale:1}],['knight',RX+5,-22,{gateG:1}],['hound',RX-9,-14],['hound',RX+9,-14]);}
  if(id==='yard'){[['warrior',-10,-60],['warrior',10,-70],['warrior',0,-85],['imp',-20,-55],['imp',20,-55],['imp',-6,-92],['imp',6,-92]].forEach(([t,dx,z])=>W.push([t,RX+dx,z]));}
  if(id==='hall'){[['warrior',-6,-120],['warrior',6,-125],['warrior',-6,-145],['warrior',6,-150],['hound',-3,-135],['hound',3,-138]].forEach(([t,dx,z])=>W.push([t,RX+dx,z]));}
  for(const[t,x,z,o]of W)spawnEnt(t,x,z,Object.assign({aggro:t==='knight'?24:34,always:false},o||{}));}
function realmGateCheck(){if(FLAGS.gateOpen)return;const G=DEM.filter(e=>e.gateG);if(realmWaves.gate&&G.length&&G.every(e=>e.dead)||realmWaves.gate&&!G.length&&realmWaves.gateSeen){FLAGS.gateOpen=1;gateColl.hw=.01;Snd.gate&&Snd.gate();toast('Das Fallgitter hebt sich!');if(kreakNear())say(kreakE,'Das Tor ist offen! Weiter!',3);if(mqIs('castle'))mqSet(12);}
  if(G.length)realmWaves.gateSeen=1;}
/* ---- Thronsaal ---- */
function throneScene(){cineMus('ereignisse/enthuellung');const k=kreakE;shkE=spawnEnt('shikaya',RX,-190,{inv:true,noHostile:true,noLeash:true,home:{x:RX,z:-180}});shkE.frame=0;
  if(k){k.scene=true;k.sceneFrame=0;k.x=RX-2;k.z=-172;}
  playCine([{t:'(Am Ende des Saals, vor einem Thron aus schwarzem Eisen, steht eine Frau mit Hörnern und Flügeln. Sie lächelt.)'},
    {who:'Shikaya',t:'Endlich. Ich habe euch gerochen, kaum dass ihr den ersten Teil des Schwertes berührt habt.'},
    {who:'Kreak',t:'Shikaya! Heute endet es. Für Coda. Für alle, die du verbrannt hast.'},
    {who:'Shikaya',t:'(lacht leise) Du erinnerst dich an mich … aber nicht an alles. Nicht wahr?'},
    {who:'Kreak',t:'Ich erinnere mich an genug. Du bist ein Monster!'},
    {who:'Shikaya',t:'(Sie steigt die Stufen herab. Ihre Augen glühen.) Nein …',fn:()=>{shkE.frame='f';Snd.demonRoar(1.6,.5);}},
    {who:'Shikaya',t:'Ich bin dein Nerra.'},
    {t:'(Kreak erstarrt. Das Akuma Senso zittert in seiner Hand.)',fn:()=>{if(k)k.sceneFrame=0;}},
    {who:'Kreak',t:'… Nerra. Die Suppe. Der Fieberwinter. Der rote Mond über unserem Haus …'},
    {who:'Kreak',t:'Du … du bist meine Schwester.'},
    {t:'(Kreak bricht zusammen. Das Akuma Senso fällt klirrend zu Boden und schlittert dir vor die Füße.)',fn:()=>{if(k)k.sceneFrame='k';FLAGS.kreakBroken=1;Snd.hit('sword');}},
    {who:'Shikaya',t:'Er war schon immer zu weich. Und du? Du hebst sein Spielzeug auf?'}],
    ()=>{if(addItem('akuma',1))spawnDrop('akuma',1,P.x,P.y+1,P.z);toast('Du hebst das Akuma Senso auf. Nur damit kannst du Shikaya verletzen!');selectAkuma();shkE.inv=false;shikayaAI(shkE);mqSet(13);});}
function selectAkuma(){for(let i=HOT0;i<INV_N;i++)if(inv[i]&&inv[i].id==='akuma'){select(i-HOT0);return;}const j=inv.findIndex(s=>s&&s.id==='akuma');if(j>=0){const t=inv[HOT0+sel];inv[HOT0+sel]=inv[j];inv[j]=t;renderInv();}}
function shikayaAI(e){e.special=(e,dt)=>{const pd=Math.hypot(P.x-e.x,P.z-e.z);e.bt=(e.bt||4)-dt;e.bl=(e.bl||8)-dt;e.frame=e.frame==='f'?0:e.frame;if(e.cast>0)return castShk(e,dt);
    if(e.phase2)return shikaya2(e,dt,pd);
    if(!e.s1&&e.hp<e.max*.85){e.s1=1;for(let k=0;k<3;k++)spawnEnt('imp',e.x+(k-1)*3,e.z+3,{aggro:60});say(e,'Kommt, meine Kleinen!',2.5);}
    if(!e.s2&&e.hp<e.max*.68){e.s2=1;for(let k=0;k<3;k++)spawnEnt('imp',e.x+(k-1)*3,e.z+3,{aggro:60});for(let k=0;k<2;k++)spawnEnt('hound',e.x+(k?4:-4),e.z+5,{aggro:60});}
    if(e.hp<=e.max*.5&&!e.twist){e.twist=1;e.inv=true;twistScene();return true;}
    if(e.act==='blink'){e.actT-=dt;if(e.actT<=0){const a=P.yaw,x=P.x+Math.sin(a)*2.6,z=P.z+Math.cos(a)*2.6;e.x=x;e.z=z;e.act=null;e.inv=false;e.hidden=false;e.wind=.35;e.atk=e.d.cd;e.tgt='player';
        for(let k=0;k<30;k++)spawnParticle(x,e.y+1.5,z,(Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4,0xa01020,.7,.3);Snd.whoosh(1200,.12);}return true;}
    if(pd>5&&e.bt<=0){e.bt=6.5+Math.random()*2;e.cast=.6;e.castShots=5;return true;}
    if(e.bl<=0&&pd<18){e.bl=9+Math.random()*3;e.act='blink';e.actT=.5;e.inv=true;e.hidden=true;for(let k=0;k<30;k++)spawnParticle(e.x,e.y+1.5,e.z,(Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4,0xa01020,.7,.3);e.hideT=.5;return true;}
    return false;};}
function castShk(e,dt){e.cast-=dt;e.frame='c';if(e.cast<=0){const n=e.castShots||5;for(let k=0;k<n;k++)shoot(e,P.x,P.y+1,P.z,{n:1,spread:0,spd:8,dmg:10,orb:'orb_blood',col:0xff3a4a,home:1.6,sy:.9,life:5});e.castShots=0;}return true;}
function twistScene(){const e=shkE;playCine([{who:'Shikaya',t:'Genug!',fn:()=>{e.frame='f';Snd.demonRoar(1.4,1.2);}},
  {t:'(Sie breitet die Flügel aus. Der Thronsaal bebt, Steine fallen von der Decke.)'},
  {who:'Shikaya',t:'Du willst mich vernichten, Kleines? Dann sieh zu, wie das brennt, was dir lieb ist.'},
  {t:'(Sie packt dich am Kragen. Rotes Licht. Der Boden verschwindet unter deinen Füßen.)',fn:()=>{Snd.boom(.35);}}],()=>{startFinale(false);});}
/* ---- Hooks ---- */
function storyUse2(){if(mqIs('bloodmoon')&&altarLooked()){if(!bloodTonight()){toast('Der Altar ist kalt. Warte auf den Blutmond.');Snd.click();return true;}if((FLAGS.hearts||0)<3){toast('Du brauchst drei Dämonenherzen.');return true;}startRitual();return true;}
  if(portalLooked()&&mqAt('portal')&&!mqAt('coda')){enterRealm();return true;}if(P.x>REALM_X0-60&&P.x<REALM_X1+60&&rPortalLooked()){leaveRealm();return true;}return false;}
function storyPrompt2(){if(mqIs('bloodmoon')&&altarLooked())return bloodTonight()?'Die drei Dämonenherzen auf den Altar legen':'Altar untersuchen';if(portalLooked()&&mqAt('portal')&&!mqAt('coda'))return 'Durch das Portal in die Unterwelt treten';
  if(P.x>REALM_X0-60&&P.x<REALM_X1+60&&rPortalLooked())return 'Durch das Portal zurück zum Steinkreis';return null;}
function storyGlow2(glow){const ok=FLAGS.portalOpen||portalK>0;if(ok&&Math.hypot(camera.position.x-CIRCLE.x,camera.position.z-CIRCLE.z)<220){if(portalK>0&&portalK<1)portalK=Math.min(1,portalK+.01);const k=FLAGS.portalOpen?1:portalK,w=4.6*k,s=1+Math.sin(time*2)*.03;glow(CIRCLE.x,CIRCLE.y+.6,CIRCLE.z,w*s,w*1.33*s,'portal',1.1);}
  if(inRealm(camera.position.x)){const h=realmFloor(R_ARRIVE.x,R_ARRIVE.z);glow(R_ARRIVE.x,h+.1,R_ARRIVE.z,4.4,5.8,'portal',1.1);}
  if(typeof storyGlow3==='function')storyGlow3(glow);}
function mqObjective2(id){switch(id){
  case'malphas':return{t:'Besiege Malphas, den Torwächter',at:malE&&!malE.dead?[malE.x,malE.z]:[CIRCLE.x,CIRCLE.z]};
  case'portal':return{t:'Tritt durch das Portal am Steinkreis in die Unterwelt',at:inRealm(P.x)?null:[CIRCLE.x,CIRCLE.z]};
  case'castle':return{t:FLAGS.gateOpen?'Betritt Shikayas Schloss':'Brich durch das Tor von Shikayas Schloss',at:inRealm(P.x)?[RX,CAS.z1+10]:[CIRCLE.x,CIRCLE.z]};
  case'throne':return{t:'Finde den Thronsaal im Bergfried',at:inRealm(P.x)?[RX,-175]:[CIRCLE.x,CIRCLE.z]};
  case'shikaya':return{t:'Besiege Shikaya',at:inRealm(P.x)?(shkE&&!shkE.dead?[shkE.x,shkE.z]:[RX,-175]):[CIRCLE.x,CIRCLE.z]};
  default:return typeof mqObjective3==='function'?mqObjective3(id):null;}}
function updateStory2(dt){updateRealm(dt);const st=MQ[mqStage()]&&MQ[mqStage()].id,inR=inRealm(P.x);
  if(st==='malphas'&&!malE&&Math.hypot(P.x-CIRCLE.x,P.z-CIRCLE.z)<40){portalK=1;spawnMalphas();}
  if(malE&&!malE.dead&&Math.hypot(P.x-CIRCLE.x,P.z-CIRCLE.z)>160){removeEnt(malE);malE=null;}
  if(inR){if(P.z<20)realmSpawnWave('gate');if(P.z<-45&&FLAGS.gateOpen)realmSpawnWave('yard');if(P.z<-106&&Math.abs(P.x-RX)<26)realmSpawnWave('hall');realmGateCheck();
    if(st==='castle'&&FLAGS.gateOpen)mqSet(12);
    if((st==='throne'||st==='shikaya')&&P.z<KEEP.div+1&&Math.abs(P.x-RX)<24&&!shkE){if(st==='throne')throneScene();else{shkE=spawnEnt('shikaya',RX,-190,{noHostile:true,noLeash:true,home:{x:RX,z:-180}});shikayaAI(shkE);if(kreakE){kreakE.scene=true;kreakE.sceneFrame='k';kreakE.x=RX-2;kreakE.z=-172;}say(shkE,'Zurück, um zu sterben?',3);if(countItem('akuma')<1&&addItem('akuma',1)===0)selectAkuma();}}
    if(shkE&&!shkE.dead&&!shkE.twist&&P.z>KEEP.div+12){shkE.hp=Math.min(shkE.max,shkE.hp+shkE.max*.05*dt);}}
  else if(st==='coda'||st==='end'){}
  if(typeof updateStory3==='function')updateStory3(dt);}
function resetStory2(){malE=null;shkE=null;realmWaves={};portalK=0;if(gateColl)gateColl.hw=FLAGS.gateOpen?.01:5.2;if(portcullis)portcullis.position.y=FLAGS.gateOpen?CY+9.5:CY;if(typeof resetStory3==='function')resetStory3();}
function initStory2(atlas){buildRealm();}

function storyBlockNPC(){return(mqIs('bloodmoon')&&altarLooked())||(portalLooked()&&mqAt('portal')&&!mqAt('coda'))||(inRealm(P.x)&&rPortalLooked());}

