const FIN={on:false};const METEORS=[];
function codaSpot(side){const r=Math.random;if(side==='n')return[(r()-.5)*70,632+r()*10];if(side==='s')return[(r()-.5)*60,805+r()*12];if(side==='w')return[-80-r()*15,690+r()*60];return[80+r()*15,690+r()*60];}
function finSpawn(list){for(const[t,n,side,o]of list)for(let k=0;k<n;k++){const[x,z]=codaSpot(side);spawnEnt(t,x,z,Object.assign({aggro:80,always:true,fin:1},o||{}));}}
function finAlive(){return DEM.filter(e=>e.fin&&e.fac==='demon'&&!e.dead&&e!==FIN.shk).length;}
function startFinale(resume){for(const e of DEM.slice())if(e.fac==='demon')removeEnt(e);SHOTS.length=0;METEORS.length=0;shkE=null;
  const x=4,z=700;P.x=x;P.z=z;P.y=getHeight(x,z)+.3;P.vx=P.vy=P.vz=0;P.yaw=0;P.pitch=.08;P.safe=[x,z];curArea=null;if(P.riding)dismount(true);
  FLAGS.clock=21*60;const n=FLAGS.day;FLAGS.moonForce={n,phase:4,ev:'blood'};FLAGS.akumaPlayer=1;
  Object.assign(FIN,{on:true,t:0,wave:0,allies:0,descend:false,kreakIn:false,metT:3,shoutT:0,done:false});
  const s=spawnEnt('shikaya',0,720,{noHostile:true,noLeash:true,inv:true,always:true,home:{x:0,z:720},fin:1});s.hp=s.max*.5;s.flyOff=13;s.frame='f';FIN.shk=s;shkE=s;s.special=finShk;
  if(kreakE){kreakE.scene=true;kreakE.hidden=true;kreakE.x=0;kreakE.z=640;}
  if(countItem('akuma')<1&&addItem('akuma',1)===0)selectAkuma();
  if(!mqIs('coda'))mqSet(14);
  const go=()=>{finSpawn([['imp',8,'n'],['hound',4,'n'],['warrior',4,'n'],['hound',2,'w'],['imp',3,'e']]);FIN.wave=1;};
  if(resume){go();toast('Coda steht unter Angriff!');return;}
  setTimeout(()=>playCine([{t:'(Du schlägst hart auf dem Pflaster von Coda auf. Über dir hängt der Blutmond. Überall Schreie.)'},
    {who:'Shikaya',t:'(über den Dächern schwebend) Sieh hin! Das ist dein kleines Coda. Meine Armee wird es dem Erdboden gleichmachen!'},
    {t:'(Aus dem Wald und von den Feldern strömen Dämonen heran. Hunderte glühende Augen.)'}],go),500);}
function finShk(e,dt){const pd=Math.hypot(P.x-e.x,P.z-e.z);
  if(e.final)return true;
  if(!FIN.descend){e.frame='f';e.inv=true;e.flyOff=13+Math.sin(time*.8)*1.2;const tx=P.x*.3,tz=700+Math.sin(time*.3)*14;e.x+=(tx-e.x)*dt*.3;e.z+=(tz-e.z)*dt*.3;return true;}
  if(e.flyOff>0){e.flyOff=Math.max(0,e.flyOff-dt*6);e.frame='f';e.inv=e.flyOff>0;return true;}
  e.bt=(e.bt||3)-dt;e.bl=(e.bl||7)-dt;
  if(!e.p2a&&e.hp<e.max*.4){e.p2a=1;finSpawn([['imp',6,'n'],['hound',3,'s']]);say(e,'Steht auf, meine Kinder!',3);}
  if(!e.p2b&&e.hp<e.max*.25){e.p2b=1;finSpawn([['imp',6,'e'],['warrior',3,'w']]);say(e,'Warum fällst du nicht endlich?!',3);}
  if(!FIN.kreakIn&&e.hp<e.max*.35){FIN.kreakIn=true;kreakArrives();return true;}
  if(e.hp<=1&&!e.final){e.final=true;e.hp=1;e.inv=true;finalScene();return true;}
  if(e.cast>0)return castShk(e,dt);
  if(e.act==='blink'){e.actT-=dt;if(e.actT<=0){const a=P.yaw,x=P.x+Math.sin(a)*2.6,z=P.z+Math.cos(a)*2.6;e.x=x;e.z=z;e.act=null;e.inv=false;e.hidden=false;e.wind=.35;e.atk=e.d.cd;e.tgt='player';
      for(let k=0;k<30;k++)spawnParticle(x,e.y+1.5,z,(Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4,0xa01020,.7,.3);Snd.whoosh(1200,.12);}return true;}
  if(pd>5&&e.bt<=0){e.bt=5.5+Math.random()*2;e.cast=.55;e.castShots=6;return true;}
  if(e.bl<=0&&pd<20){e.bl=8+Math.random()*3;e.act='blink';e.actT=.45;e.inv=true;e.hidden=true;for(let k=0;k<30;k++)spawnParticle(e.x,e.y+1.5,e.z,(Math.random()-.5)*4,(Math.random()-.5)*4,(Math.random()-.5)*4,0xa01020,.7,.3);return true;}
  return false;}
{const he0=hurtEnt;hurtEnt=function(e,n,by){if(e===FIN.shk&&FIN.on&&!e.final&&e.hp-n<=1&&by==='player'&&!e.inv){e.hp=1;e.hurt=.2;return;}he0(e,n,by);};}
function meteor(x,z){METEORS.push({x,z,t:0,T:1.5});}
function updateMeteors(dt){for(let i=METEORS.length-1;i>=0;i--){const m=METEORS[i];m.t+=dt;const g=groundAt(m.x,m.z,99);
  if(Math.random()<dt*14){const a=Math.random()*6.283;spawnParticle(m.x+Math.cos(a)*3,g+.15,m.z+Math.sin(a)*3,0,.4,0,0xff2a1a,.35,.3);}
  if(m.t>=m.T){METEORS.splice(i,1);Snd.boom(.2);for(let k=0;k<40;k++){const a=Math.random()*6.283,v=2+Math.random()*6;spawnParticle(m.x,g+.3,m.z,Math.cos(a)*v,2+Math.random()*5,Math.sin(a)*v,Math.random()<.5?0xff3a1a:0xffb030,.8,.4);}
    if(Math.hypot(P.x-m.x,P.z-m.z)<3.2&&P.y-g<2)takeDamage(22),P.burnT=Math.max(P.burnT||0,2);for(const o of DEM)if(o.fac==='ally'&&!o.dead&&Math.hypot(o.x-m.x,o.z-m.z)<3.2)hurtEnt(o,30,'demon');}}}
function storyGlow3(glow){if(FIN.on)for(const f of finFireList())glow(f.x,f.y-.6,f.z,3.6,3,'campfire',1.5);for(const m of METEORS){const g=groundAt(m.x,m.z,99),k=m.t/m.T,y=g+30*(1-k*k);glow(m.x,y,m.z,1.6,1.6,'orb_big',1.6);}}
function finAllies(){const shout=(e,t,d)=>setTimeout(()=>say(e,t,d||4),300);
  if(FIN.allies===0&&FIN.t>7){FIN.allies=1;let cap=null;for(let k=0;k<8;k++){const x=pathX(612)+(k%4-1.5)*2,z=605-Math.floor(k/4)*2.5;const e=spawnEnt('guardA',x,z,{gi:k,always:true,fin:1,home:{x:0,z:690}});if(!k)cap=e;}
    cap.name='Hauptmann';shout(cap,'Sturmburg hat den roten Himmel gesehen! Stadtwache, haltet die Linie!');toast('Die Stadtwache von Sturmburg kommt zu Hilfe!');Snd.levelUp();}
  if(FIN.allies===1&&FIN.t>14){FIN.allies=2;const nf=typeof FROG_FOLK!=='undefined'?FROG_FOLK.length:4;let f0=null;for(let k=0;k<6;k++){const e=spawnEnt('frogA',-95-(k%3)*2,705+Math.floor(k/3)*3,{fi:k%nf,always:true,fin:1,home:{x:-10,z:715}});if(!k)f0=e;}
    shout(f0,'Quaaak! Die Froschleute kämpfen mit! Murgla hat uns geschickt!');toast('Die Froschleute greifen ein!');Snd.levelUp();}
  if(FIN.allies===2&&FIN.t>21){FIN.allies=3;const a=spawnEnt('dragonA',-6,712,{di:0,always:true,fin:1,flyOff:30,name:'Drakon',home:{x:0,z:700}}),b=spawnEnt('dragonA',8,716,{di:1,always:true,fin:1,flyOff:34,name:'Vesra',home:{x:0,z:705}});
    FIN.dragons=[a,b];shout(a,'Ihr habt euch einen schlechten Abend für einen Krieg ausgesucht, Dämonen!',4.5);setTimeout(()=>say(b,'Für den Himmel! Für die Drachenmenschen!',3.5),2600);toast('Zwei Drachenmenschen stürzen vom Himmel!');Snd.demonRoar(1.6,.6);}}
function kreakArrives(){const e=FIN.shk;playCine([{t:'(Am Nordrand von Coda reißt ein Portal auf. Eine Gestalt taumelt heraus. Orange Haut, grünes Haar.)',fn:()=>{if(kreakE){kreakE.hidden=false;kreakE.scene=true;kreakE.sceneFrame=0;kreakE.x=2;kreakE.z=660;}}},
  {who:'Kreak',t:'SHIKAYA!'},{who:'Shikaya',t:'Du kommst zu spät, kleiner Bruder.'},
  {who:'Kreak',t:'Nein. Diesmal bin ich da. Und diesmal lasse ich dich nicht allein im Dunkeln.'}],()=>{if(kreakE){kreakE.scene=false;kreakE.mode='follow';kreakE.down=0;kreakE.hp=kreakE.max;}FLAGS.kreakBroken=0;toast('Kreak kämpft wieder an deiner Seite!');});}
function finalScene(){cineMus('ereignisse/abschied');const e=FIN.shk,k=kreakE;e.frame='k';e.flyOff=0;
  for(const d of DEM)if(d.fac==='demon'&&d!==e&&!d.dead){d.sink=true;d.sinkT=0;d.inv=true;}
  if(k){k.scene=true;k.hidden=false;k.sceneFrame='k';k.x=e.x-1.6;k.z=e.z+1.2;}
  playCine([{t:'(Das Akuma Senso trifft. Shikaya sinkt zu Boden. Das Rot in ihren Augen erlischt, und die Dämonen um Coda zerfallen zu Asche.)',fn:()=>{e.frame='k';Snd.demonRoar(1.8,.6);}},
    {t:'(Kreak lässt sich neben ihr auf die Knie fallen.)'},
    {who:'Shikaya',t:'(leise) Weißt du noch … die Suppe? Sie war … angebrannt.'},
    {who:'Kreak',t:'Sie war die beste Suppe der Welt.'},
    {who:'Shikaya',t:'Ich wollte dich doch nur … beschützen. Damals. Vor dem Fieber. Vor allem.',fn:()=>{e.frame='r';}},
    {who:'Shikaya',t:'… Nerra.'},
    {t:'(Ihr Körper zerfällt zu Licht. Der Blutmond verblasst. Über Coda geht die Sonne auf.)',fn:()=>{for(let q=0;q<120;q++)spawnParticle(e.x+(Math.random()-.5)*2,e.y+Math.random()*3,e.z+(Math.random()-.5)*2,(Math.random()-.5)*2,1+Math.random()*4,(Math.random()-.5)*2,Math.random()<.5?0xffd0e0:0xffffff,2.5,.3);
      e.hidden=true;e.dead=true;e.alive=false;e.deadT=99;FLAGS.moonForce=null;FLAGS.clock=5*60+50;Snd.chime();if(dmBoss===e)dmBossHide();}}],
  ()=>{gainXP(3000);setTimeout(epilogue,1200);});}
function epilogue(){cineMus('ereignisse/abschied');const cap=DEM.find(d=>d.name==='Hauptmann'&&!d.dead),dr=FIN.dragons&&FIN.dragons[0];if(kreakE){kreakE.sceneFrame=0;}
  playCine([{t:'(Die Sonne steht über Coda. Zum ersten Mal seit Tagen ist der Himmel klar.)'},
    {who:'Hauptmann',t:'Sie ist fort. Wirklich fort. Sturmburg wird noch in hundert Jahren davon singen.'},
    {who:'Drakon',t:'Die Drachenmenschen vergessen das nicht. Ruft, wenn ihr uns braucht. Wir hören euch.'},
    {who:'Kreak',t:'Ich habe sie verloren. Zweimal.'},
    {who:'Kreak',t:'Aber diesmal habe ich mich an sie erinnert. An die echte Shikaya. Die Suppe. Das Lachen. Das nimmt mir keiner mehr.'},
    {who:'Kreak',t:'Behalte das Akuma Senso. Du hast es dir verdient. Und wenn du nichts dagegen hast … ziehe ich noch ein Stück mit dir. Ich habe ja jetzt einen Namen.'}],
  ()=>{if(kreakE){kreakE.scene=false;kreakE.mode='follow';}FIN.on=false;FIN.done=true;FIN.leaveT=50;mqSet(15);addLetter(5);showCredits();});}
function showCredits(){Mus.cine='ereignisse/abspann';const el=$('credits');el.hidden=false;el.classList.remove('on');void el.offsetWidth;el.classList.add('on');state='journal';if(document.pointerLockElement){suppressPause=true;document.exitPointerLock();}updateLockHint();}
