LETTERS.push({t:'Ein letzter Brief',src:'Gefunden in Coda, am Morgen danach',text:'Nerra,\n\nwenn du das liest, bin ich fort. Ich habe es nie geschafft, dir zu sagen, dass es mir leidtut. Also schreibe ich es auf, wie früher.\n\nEs tut mir leid.\n\nIss etwas Ordentliches. Und lass die Wölfe in Ruhe.\n\n– S.'});
function mqObjective3(id){if(id==='coda')return{t:!FIN.descend?'Verteidige Coda gegen die Dämonenarmee!':'Besiege Shikaya mit dem Akuma Senso!',at:FIN.shk&&FIN.descend&&!FIN.shk.dead?[FIN.shk.x,FIN.shk.z]:null};
  if(id==='end')return{t:'Die Geschichte ist erzählt. Die Welt gehört dir.',at:null};return null;}
function updateStory3(dt){updateMeteors(dt);NIGHT_EV.blood.light=FIN.on?.66:.4;NIGHT_EV.blood.moon=FIN.on?.52:.32;
  if(FIN.on)for(const f of finFireList())if(Math.random()<dt*14)spawnParticle(f.x+(Math.random()-.5)*2.4,f.y+Math.random(),f.z+(Math.random()-.5)*2.4,(Math.random()-.5)*.6,1.5+Math.random()*2,(Math.random()-.5)*.6,Math.random()<.5?0xff6a10:Math.random()<.5?0xffd040:0x3a3030,1.1,.4);const st=MQ[mqStage()]&&MQ[mqStage()].id;
  if(st==='coda'&&!FIN.on&&!FIN.done&&state==='playing'){startFinale(true);return;}
  if(FIN.done&&FIN.leaveT>0){FIN.leaveT-=dt;if(FIN.leaveT<=0)for(const e of DEM.slice())if(e.fin)removeEnt(e);}
  for(const e of DEM.slice())if(e.sink&&e.sinkT>1.6)removeEnt(e);
  if(!FIN.on||state!=='playing')return;FIN.t+=dt;finAllies();
  // Dorfbewohner geraten in Panik
  FIN.panT=(FIN.panT||0)-dt;if(FIN.panT<=0){FIN.panT=1;for(const v of villagers)if(!v.dead&&!v.inside&&v.z>PLAIN_END){v.flee=Math.max(v.flee||0,2);if(Math.random()<.02)say(v,['Hilfe!','Die Dämonen!','Rennt!','In die Häuser!'][(Math.random()*4)|0],2);}}
  // Wellen
  const alive=finAlive();
  if(FIN.wave===1&&alive<6&&FIN.t>10){FIN.wave=2;finSpawn([['knight',2,'n'],['warrior',6,'n'],['hound',4,'w'],['hound',2,'e'],['imp',6,'s']]);toast('Eine zweite Welle!');}
  else if(FIN.wave===2&&alive<6){FIN.wave=3;finSpawn([['knight',3,'n'],['warrior',8,'s'],['imp',8,'e'],['hound',6,'w']]);toast('Es werden immer mehr!');const al=DEM.filter(e=>e.fin&&e.fac==='ally'&&!e.dead);if(al[0])say(al[0],'Es sind zu viele! Wir können sie nicht ewig halten!',4);}
  else if(FIN.wave===3&&alive<9&&!FIN.descend){FIN.descend=true;const s=FIN.shk;say(s,'Genug gespielt. Ich mache das selbst.',4);Snd.demonRoar(1.4,1.2);s.barShown=false;}
  // Blutmeteore
  FIN.metT-=dt;if(FIN.metT<=0){FIN.metT=FIN.descend?6:3.2;const tg=Math.random()<.6?P:DEM.filter(e=>e.fin&&e.fac==='ally'&&!e.dead)[0]||P;meteor(tg.x+(Math.random()-.5)*6,tg.z+(Math.random()-.5)*6);if(FIN.shk&&!FIN.descend)FIN.shk.frame='c';}}
function resetStory3(){FIN.on=false;FIN.done=false;METEORS.length=0;}
/* ---- Tod in den Story-Kämpfen: kein Verlust, nur zurück ---- */
function storyDeath(){const inR=inRealm(P.x);if(!inR&&!FIN.on)return false;state='dead';keys.clear();rightDown=false;Snd.thud();promptEl.hidden=true;
  $('deathText').textContent=FIN.on?'Du rappelst dich wieder auf. Coda braucht dich!':'Die Dunkelheit wirft dich zurück. Du verlierst nichts.';const ds=$('deathScreen');ds.hidden=false;ds.classList.remove('on');void ds.offsetWidth;ds.classList.add('on');
  setTimeout(()=>{const S=P.stats;S.hp=S.maxHp;S.st=S.maxSt;P.burnT=0;P.lastDmg=time;
    if(FIN.on){const x=(Math.random()-.5)*8,z=712;P.x=x;P.z=z;P.y=getHeight(x,z)+.2;}
    else{const sh=shkE&&!shkE.dead&&!shkE.twist;if(sh){shkE.hp=shkE.max;shkE.s1=shkE.s2=0;for(const e of DEM.slice())if(e.fac==='demon'&&e!==shkE&&inRealm(e.x)&&Math.hypot(e.x-RX,e.z+180)<40)removeEnt(e);}
      const x=sh?RX:R_ARRIVE.x,z=sh?-112:R_ARRIVE.z-5;P.x=x;P.z=z;P.y=realmFloor(x,z)+.2;}
    P.vx=P.vy=P.vz=0;ds.hidden=true;ds.classList.remove('on');state='playing';renderStats();updateLockHint();saveGame();},3200);return true;}

