const BOSS_MUSIC={vargoth:'bosskampf/vargoth',ssylra:'bosskampf/ssylra',gruumak:'bosskampf/gruumak',malphas:'bosskampf/malphas'};
const Mus={missing:new Set(),ok:new Set(),els:[],cur:null,vol:0,fadeT:0,cine:null};
function musEl(){const a=new Audio();a.loop=true;a.preload='auto';a.volume=0;return a;}
function musicVol(){return Math.pow((settings.music==null?45:settings.music)/100,1.4)*.85;}
function musicWant(){
  if(state==='menu'||state==='loading'||(state==='settings'&&settingsReturn==='menu'))return'ereignisse/titelbild';
  if(Mus.cine)return Mus.cine;
  if(typeof FIN!=='undefined'&&FIN.on)return'bosskampf/shikaya_2';
  if(typeof shkE!=='undefined'&&shkE&&!shkE.dead&&!shkE.twist&&!shkE.inv&&inRealm(P.x))return'bosskampf/shikaya_1';
  if(dmBoss&&!dmBoss.dead&&BOSS_MUSIC[dmBoss.type])return BOSS_MUSIC[dmBoss.type];
  if(phAwake())return'bosskampf/pharao';
  if(typeof boss!=='undefined'&&boss&&!boss.dead&&Math.hypot(boss.x-P.x,boss.z-P.z)<80)return'bosskampf/ameisenkoenigin';
  if(DEM.some(e=>e.fac==='demon'&&!e.dead&&!e.dormant&&e.tgt==='player'))return'ereignisse/kampf';
  if(P.x<60000&&typeof bloodTonight==='function'&&bloodTonight())return'ereignisse/blutmond';
  const a=curArea||areaAt(P.x,P.z);if(P.x<60000&&(FLAGS.clock>=20*60||FLAGS.clock<330)&&!Mus.missing.has('orte/nacht'))return'orte/nacht';
  return AREA_MUSIC[a]||null;}
// Fällt ein Wunsch aus (Datei fehlt), auf den Ort zurückfallen
const MUSIC_FALLBACK={'orte/froschdorf':'orte/coda','orte/wirtshaus':'orte/coda','orte/ebene':'orte/wald','orte/kueste':'orte/wald','orte/redwood':'orte/wald'};
function musicPick(){let k=musicWant();while(k&&Mus.missing.has(k)&&MUSIC_FALLBACK[k])k=MUSIC_FALLBACK[k];if(k&&Mus.missing.has(k)){const a=curArea||areaAt(P.x,P.z);k=AREA_MUSIC[a]||null;if(k&&Mus.missing.has(k))k=null;}return k;}
function musicPlay(k){if(Mus.cur&&Mus.cur.k===k)return;const old=Mus.cur;if(old){old.fade=-1;}
  if(!k){Mus.cur=null;return;}const el=musEl();const m={k,el,v:0,fade:1};Mus.cur=m;Mus.els.push(m);
  const fail=()=>{Mus.missing.add(k);m.fade=-1;if(Mus.cur===m)Mus.cur=null;};
  el.addEventListener('error',fail,{once:true});el.addEventListener('canplay',()=>Mus.ok.add(k),{once:true});
  const go=src=>{el.src=src;const p=el.play();if(p&&p.catch)p.catch(()=>{m.retry=true;});};
  // Desktop-Version: Musik liegt im Ordner "musik" neben der .exe
  if(typeof DESKTOP==='function'&&DESKTOP()&&nlInit()&&window.NL_PATH){if(Mus.blob&&Mus.blob[k]){go(Mus.blob[k]);return;}
    Neutralino.filesystem.readBinaryFile(NL_PATH+'/musik/'+k+'.mp3').then(buf=>{(Mus.blob=Mus.blob||{})[k]=URL.createObjectURL(new Blob([buf],{type:'audio/mpeg'}));if(Mus.cur===m)go(Mus.blob[k]);}).catch(fail);return;}
  go(MUSIC_DIR+k+'.mp3');}
function updateMusic(dt){const want=musicPick();if(!Mus.cur||Mus.cur.k!==want){if(!(Mus.cur&&Mus.cur.k===want))musicPlay(want);}
  const V=musicVol();for(let i=Mus.els.length-1;i>=0;i--){const m=Mus.els[i];if(m.retry&&m===Mus.cur&&(Snd.ctx||Mus.user)){m.retry=false;const p=m.el.play();if(p&&p.catch)p.catch(()=>{m.retry=true;});}
    m.v=clamp(m.v+m.fade*dt/1.6,0,1);m.el.volume=clamp(m.v*V,0,1);if(m.fade<0&&m.v<=0){m.el.pause();m.el.removeAttribute('src');try{m.el.load();}catch(e){}Mus.els.splice(i,1);}}}
