let cineMusNext=null;function cineMus(k){cineMusNext=k;}
{const pc0=playCine;playCine=function(lines,onEnd,mus){Mus.cine=mus||cineMusNext||null;cineMusNext=null;pc0(lines,()=>{Mus.cine=null;if(onEnd)onEnd();});};}
