const FPW={wood:pal(['#1e1008','#3a2212','#5a3a1c','#7a5228','#9a6a36','#c08a4c']),grip:pal(['#140a06','#2a160c','#4a2a14','#6e4220','#8e5a2e']),
  stone:pal(['#1c1d20','#34363a','#4e5156','#6c7076','#8e9298','#b0b4ba']),steel:pal(['#14161a','#2e3238','#50565e','#7a828c','#a8b0ba','#dfe6ee']),
  gold:pal(['#4a3008','#7a5210','#b0801c','#dcaa2c','#f4cc4a','#fff0a0']),cloth:pal(['#2a1c10','#4a3420','#6e5234','#8e7048','#b09060']),
  fire:pal(['#a01c04','#e04a08','#ff8a14','#ffc030','#ffe890','#fffbe8']),leaf:pal(['#2a1a0a','#4a3014','#6e4a20'])};
