// Holzstiel mit Maserung
function fpHandle(p,cx,y0,y1,w,P){P=P||FPW.wood;for(let y=y0;y<=y1;y++)for(let x=Math.round(cx-w/2);x<Math.round(cx+w/2);x++){const t=(x-(cx-w/2))/w;let L=.78-t*.55+(hash2(x,(y>>2)+x*7,311)-.5)*.12+(Math.sin(y*.45+x*1.7)>.85?-.18:0);p.set(x,y,P[shadeIdx(L,P.length,x,y)]);}}
