  fPoly(p,[[1,by1+1],[W-1,by1+1],[W-3,by1+6],[cx+3,by1+5],[cx,by1+7],[cx-3,by1+5],[3,by1+6]],G,{b:.08});
  for(const s of[-1,1])fEll(p,cx+s*15,by1+3,2.4,2.8,G,{b:.12});
  // Griff und Knauf
