// Pixel-Vergrößerung (EPX), damit kleine Symbole weich und detaillierter wirken
function fpEPX(cv){const w=cv.width,h=cv.height,s=cv.getContext('2d').getImageData(0,0,w,h).data,o=document.createElement('canvas');o.width=w*2;o.height=h*2;const oc=o.getContext('2d'),im=oc.createImageData(w*2,h*2),d=im.data;
  const px=(x,y)=>{x=clamp(x,0,w-1);y=clamp(y,0,h-1);const i=(y*w+x)*4;return s[i]|s[i+1]<<8|s[i+2]<<16|(s[i+3]>127?1:0)<<24;};
  const put=(x,y,c)=>{const i=(y*w*2+x)*4;d[i]=c&255;d[i+1]=c>>8&255;d[i+2]=c>>16&255;d[i+3]=(c>>>24)?255:0;};
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){const P=px(x,y),A=px(x,y-1),B=px(x+1,y),C=px(x-1,y),D=px(x,y+1);let a=P,b=P,c=P,e=P;
    if(C===A&&C!==D&&A!==B)a=A;if(A===B&&A!==C&&B!==D)b=B;if(D===C&&D!==B&&C!==A)c=C;if(B===D&&B!==A&&D!==C)e=D;put(x*2,y*2,a);put(x*2+1,y*2,b);put(x*2,y*2+1,c);put(x*2+1,y*2+1,e);}
  oc.putImageData(im,0,0);return o;}
function fpGeneric(id){const ic=SPR[id].c;let c=fpEPX(fpEPX(ic));const sc=Math.min(84/c.width,84/c.height,1.6);
  const o=document.createElement('canvas');o.width=o.height=128;const x=o.getContext('2d');x.imageSmoothingEnabled=false;const w=c.width*sc,h=c.height*sc;x.drawImage(c,Math.round(100-w),Math.round(114-h),Math.round(w),Math.round(h));return o.toDataURL();}
function initFPItems(){for(const id in ITEMS){const it=ITEMS[id];if(it.fp||!SPR[id])continue;let u=null;
  try{const m=it.mat;
    if(id==='sword')u=fpSword('metal','iron');else if(id==='dagger')u=fpSword('dagger','silver');else if(id==='wsword')u=fpSword('wood');else if(id==='ssword')u=fpSword('stone');
    else if(m&&id.endsWith('_sword'))u=fpSword('metal',m);else if(id==='axe')u=fpAxe('metal','iron',1);else if(id==='waxe')u=fpAxe('wood');else if(id==='saxe')u=fpAxe('stone');else if(m&&id.endsWith('_axe'))u=fpAxe('metal',m);
    else if(id==='wpick')u=fpPick('wood');else if(id==='spick')u=fpPick('stone');else if(m&&id.endsWith('_pick'))u=fpPick('metal',m);else if(id==='spear')u=fpSpear();else if(id==='torch')u=fpTorch();
    else if(/^(hpot|hpot2|pstr|pspeed|pregen|pstam|pmana|pmregen)$/.test(id))u=fpPotion(id);else u=fpGeneric(id);}catch(e){console.warn('fp',id,e);}
  if(u)it.fp=u;}}

/* =========================================================
   Kampfbewegung: umkreisen, flankieren, zurückweichen, neu ansetzen
   Gibt true zurück, wenn sich das Wesen bewegt hat; false = jetzt zuschlagen
   ========================================================= */
function combatMove(e,tx,tz,dist,reach,dt,spMul){if(e.frame==='a'&&!(e.wind>0))e.frame=0;const d=e.d,sp=d.spd*(e.speedMul||1)*(spMul||1);
  if(e.sdir==null){e.sdir=Math.random()<.5?1:-1;e.slot=(Math.random()-.5)*2.4;e.cs='approach';e.csT=0;}
  e.csT-=dt;const ang=Math.atan2(e.z-tz,e.x-tx);
  // kurz zurückweichen und neu positionieren
  if(e.cs==='retreat'){if(e.csT>0){const a=ang+e.sdir*.75,R=reach+3.5;if(entMove(e,tx+Math.cos(a)*R,tz+Math.sin(a)*R,sp*1.05,dt)<.001)e.csT=0;return true;}
    e.cs='approach';e.slot=(Math.random()-.5)*2.4;}
  // seitlich um den Gegner herum, solange die Waffe noch nicht bereit ist
  if(e.cs==='strafe'){if(e.csT>0&&e.atk>0&&dist<reach+2.2){const a=ang+e.sdir*.55,R=clamp(dist,reach*.8,reach*.98);
      if(entMove(e,tx+Math.cos(a)*R,tz+Math.sin(a)*R,sp*.55,dt)<.001)e.sdir*=-1;if(Math.random()<dt*.35)e.sdir*=-1;return true;}
    e.cs='approach';}
  // anlaufen, von der Seite statt immer frontal
  if(dist>reach){let gx=tx,gz=tz;if(dist>reach+1){const k=Math.min(1,(dist-reach)/7),a=ang+e.slot*.55*k,R=reach*.9;gx=tx+Math.cos(a)*R;gz=tz+Math.sin(a)*R;}
    entMove(e,gx,gz,sp,dt);return true;}
  if(e.atk>0){if(Math.random()<.24){e.cs='retreat';e.csT=.45+Math.random()*.7;}else{e.cs='strafe';e.csT=.7+Math.random()*1.3;if(Math.random()<.5)e.sdir*=-1;}
    const a=ang+e.sdir*.55;entMove(e,tx+Math.cos(a)*reach*.9,tz+Math.sin(a)*reach*.9,sp*.5,dt);return true;}
  return false;}

