{const pd=mqPharaohDead;mqPharaohDead=function(){if(!partIs('hilt'))return;pd();partDone();};}
{const mc=mqCheckAll;mqCheckAll=function(){mc();if(mqIs('search')&&!allFound())partDone();};}
