  for(let k=0;k<16;k++){const a=base+(Math.random()-.5)*(side?1.3:6.283),x=Math.cos(a)*(98+Math.random()*14),z=722+Math.sin(a)*(108+Math.random()*10);if(inWorld(x,z)&&!nearWater(x,z)&&!collHitXZ(x,z))return[x,z];}
