/* =========================================================
   Der ferne Osten: Savanne, Big Bongo River, Kaiserebene, Kaiserstadt
   x 1000 .. 2760, z -100 .. 1060
   ========================================================= */
const FX0=600,FX1=2760,FZ0=-760,FZM=-120,FZ1=1080,FCELL=2,FSX=(FX1-FX0)/FCELL,FSZ=(FZ1-FZ0)/FCELL,FR1=FSX+1;
// Kaiserstadt: Karte von Kernavė, um 90° gedreht (unterer Bildrand = Westen)
const KS=.62,KX1=2665,KZ0=229,KX0=KX1-KMAP.h*KS,KZ1=KZ0+KMAP.w*KS;
const KCAT=(()=>{const a=new Uint8Array(KMAP.w*KMAP.h),s=KMAP.rle;let p=0;for(let i=0;i<s.length;i+=3){const c=s.charCodeAt(i)-97,n=parseInt(s.substr(i+1,2),36);a.fill(c,p,p+n);p+=n;}return a;})();
const kUV=(x,z)=>[(z-KZ0)/KS,(KX1-x)/KS];
const kWorld=(u,v)=>[KX1-v*KS,KZ0+u*KS];
function kCat(x,z){const u=Math.floor((z-KZ0)/KS),v=Math.floor((KX1-x)/KS);if(u<0||v<0||u>=KMAP.w||v>=KMAP.h)return-1;return KCAT[v*KMAP.w+u];}
// weiches Wasserfeld für den See
const KWAT=(()=>{const W=KMAP.w,H=KMAP.h;let a=new Float32Array(W*H);for(let i=0;i<a.length;i++)a[i]=KCAT[i]===6?1:0;
  for(let it=0;it<3;it++){const b=new Float32Array(W*H);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let s=0,n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=W||yy>=H)continue;s+=a[yy*W+xx];n++;}b[y*W+x]=s/n;}a=b;}return a;})();
function kWater(x,z){const fu=(z-KZ0)/KS-.5,fv=(KX1-x)/KS-.5,u=Math.floor(fu),v=Math.floor(fv);if(u<0||v<0||u>=KMAP.w-1||v>=KMAP.h-1)return 0;const a=fu-u,b=fv-v,W=KMAP.w;
  return(KWAT[v*W+u]*(1-a)+KWAT[v*W+u+1]*a)*(1-b)+(KWAT[(v+1)*W+u]*(1-a)+KWAT[(v+1)*W+u+1]*a)*b;}
// Burgberge von Kernavė (Bildkoordinaten)
const KMOUNDS=[[352,334,26,9],[398,352,22,8],[437,322,18,7],[300,360,20,6],[470,365,16,6]].map(([u,v,r,h])=>{const[x,z]=kWorld(u,v);return{x,z,r:r*KS*1.6,h};});
// Big Bongo River
const BG_HW=38,BG_X=z=>2205+20*Math.sin(z*.0055+.8)+7*Math.sin(z*.021+2);
const BG_BR={z:595,w:3.2};BG_BR.x0=BG_X(BG_BR.z)-BG_HW-7;BG_BR.x1=BG_X(BG_BR.z)+BG_HW+7;
// Handelsstraße: verlassenes Dorf -> Savanne -> Brücke -> Kaiserstadt
// Wege nur auf der Kaiserebene: Brücke -> Westtor, Hafen -> Stadt (kein offizieller Weg durch Wüste und Savanne)
const HARB={x:2362,z:834,r:21};
const HARB_ARM=(()=>{const z0=786,x0=BG_X(z0)+BG_HW-8;const P=[[x0,z0],[x0+30,z0+6],[x0+62,z0+12],[x0+95,z0+24],[HARB.x-14,HARB.z-4]];const out=[];
  for(let i=0;i<P.length-1;i++){const[a,b]=[P[i],P[i+1]],n=Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/6);for(let k=0;k<n;k++){const t=k/n;out.push([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t+Math.sin((a[0]+(b[0]-a[0])*t)*.05)*3]);}}out.push(P[P.length-1]);return out;})();
const segD=(x,z,P)=>{let best=1e9;for(let i=0;i<P.length-1;i++){const[ax,az]=P[i],[bx,bz]=P[i+1],dx=bx-ax,dz=bz-az,t=clamp(((x-ax)*dx+(z-az)*dz)/(dx*dx+dz*dz),0,1),d=Math.hypot(x-ax-dx*t,z-az-dz*t);if(d<best)best=d;}return best;};
const harbD=(x,z)=>x<BG_X(z)||x>HARB.x+60||z<760||z>900?1e9:Math.min(segD(x,z,HARB_ARM)-9,Math.hypot(x-HARB.x,z-HARB.z)-HARB.r);
const EROADS=[[[BG_BR.x1-1,BG_BR.z],[KX0+6,BG_BR.z]],[[HARB.x+HARB.r+3,HARB.z-8],[2400,800],[2452,760],[2488,733]]];
const farRoadD=(x,z)=>{if(x<BG_BR.x1-3||x>2500||z<560||z>870)return 1e9;let b=1e9;for(const R of EROADS)b=Math.min(b,segD(x,z,R));return b;};
// Flüsse der Savanne
function mkRiver(pts,seed,hw){const out=[];for(let i=0;i<pts.length-1;i++){const[a,b]=[pts[i],pts[i+1]],L=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.ceil(L/8);
    for(let k=0;k<n;k++){const t=k/n,x=a[0]+(b[0]-a[0])*t,z=a[1]+(b[1]-a[1])*t,nx=-(b[1]-a[1])/L,nz=(b[0]-a[0])/L,o=(vnoise(x*.012,z*.012,seed)-.5)*36;out.push([x+nx*o,z+nz*o]);}}
  out.push(pts[pts.length-1]);return{p:out,hw};}
const SRIVERS=[mkRiver([[1180,-130],[1260,30],[1420,130],[1600,235],[1800,300],[1990,330],[2190,345]],611,8),
  mkRiver([[1130,1090],[1250,930],[1420,860],[1600,800],[1820,760],[2000,722],[2190,705]],612,9),
  mkRiver([[1380,470],[1440,560],[1500,660],[1560,760],[1600,800]],613,5)];
function sRiverD(x,z){let best=1e9,hw=6;for(const R of SRIVERS){const P=R.p;for(let i=0;i<P.length-1;i++){const[ax,az]=P[i],[bx,bz]=P[i+1];if(Math.abs(x-ax)>60&&Math.abs(x-bx)>60)continue;
      const dx=bx-ax,dz=bz-az,t=clamp(((x-ax)*dx+(z-az)*dz)/(dx*dx+dz*dz),0,1),d=Math.hypot(x-ax-dx*t,z-az-dz*t)-R.hw;if(d<best){best=d;hw=R.hw;}}}return best;}
// Gebirge und Kopjes
const MTN=[{x:1900,z:40,rx:330,rz:150,h:58,s:621},{x:1340,z:1000,rx:170,rz:90,h:30,s:622},{x:1150,z:120,rx:110,rz:120,h:22,s:623}];
const KOPJES=[[1300,420,26,9],[1560,520,20,7],[1720,640,30,11],[1980,520,18,6],[1440,280,22,8],[1850,880,24,9],[1120,700,18,6],[2050,180,20,8]];
const ridgeN=(x,z,s)=>{let t=0,a=.5,f=1;for(let o=0;o<4;o++){t+=(1-Math.abs(vnoise(x*.012*f,z*.012*f,s+o)*2-1))*a;a*=.5;f*=2.1;}return t/.94;};
function mtnMask(x,z){let m=0;for(const M of MTN){const d=Math.hypot((x-M.x)/M.rx,(z-M.z)/M.rz)+(vnoise(x*.01,z*.01,M.s)-.5)*.5;if(d<1)m=Math.max(m,smooth(1-d));}return m;}
// Feuchte: Steppe (trocken) bis Grasland (feucht)
const farMoist=(x,z)=>clamp(.5+(fbm(x*.0025+4,z*.0025+9,3,631)-.5)*1.6+(x-1700)/1400+smooth(clamp((40-sRiverD(x,z))/40,0,1))*.35,0,1);
function savH(x,z){let h=4.2+(fbm(x*.003,z*.003,3,601)-.5)*7+(fbm(x*.012,z*.012,2,602)-.5)*1.8;
  for(const M of MTN){const d=Math.hypot((x-M.x)/M.rx,(z-M.z)/M.rz)+(vnoise(x*.01,z*.01,M.s)-.5)*.5;if(d<1){const k=smooth(1-d);h+=Math.pow(k,1.4)*(M.h*Math.pow(ridgeN(x,z,M.s),1.5)+M.h*.25);}}
  for(const[kx,kz,kr,kh]of KOPJES){const d=Math.hypot(x-kx,z-kz)/kr;if(d<1.4){const k=Math.max(0,1-d*d/1.96);h+=Math.pow(k,1.6)*kh*(.8+vnoise(x*.15,z*.15,640)*.5);}}
  h=Math.max(h,1.6);
  // Flüsse
  const rd=sRiverD(x,z);if(rd<BANK_W){let bed=-1.6+(vnoise(x*.1,z*.1,641)-.5)*.3;h=Math.min(h,riverBank(rd,h,bed));}
  return h;}
function plainEH(x,z){let h=3.3+(fbm(x*.006+3,z*.006,2,651)-.5)*1.6;
  {const hd=harbD(x,z);if(hd<10){const t=smooth(clamp((hd+1)/9,0,1));h=-2.6*(1-t)+Math.max(h,3)*t;}}
  if(x>KX0-30&&x<KX1+30&&z>KZ0-30&&z<KZ1+30){const c=kCat(x,z);const inK=smooth(clamp(Math.min(x-KX0+30,KX1+30-x,z-KZ0+30,KZ1+30-z)/30,0,1));
    let kh=3.5+(c===1||c===0?(vnoise(x*.05,z*.05,652)-.5)*1.2:0);
    for(const M of KMOUNDS){const d=Math.hypot(x-M.x,z-M.z)/M.r;if(d<1){const k=1-d;kh+=M.h*Math.min(1,k*2.6)*(.9+vnoise(x*.2,z*.2,653)*.2);}}
    const w=kWater(x,z);if(w>0)kh=kh*(1-smooth(clamp(w*1.6,0,1)))-1.5*smooth(clamp(w*1.6,0,1));
    h=h*(1-inK)+kh*inK;}
  return h;}
// Ränder der Fernregion: dort, wo nebenan die Hauptwelt beginnt, läuft die Höhe sanft in deren Gelände über
function farEdgeD(x,z){let d=1e9;
  if(x<=860)d=Math.min(d,Math.max(0,z+120)+Math.max(0,x-840)*3);  // Tiefer Wald im Norden (z<-120, x<840)
  if(x<=1060)d=Math.min(d,Math.max(0,120-z)+Math.max(0,x-1000)*3+Math.max(0,z-840)*3);  // Wüste im Süden (z>120)
  if(z>=-122&&z<=122)d=Math.min(d,Math.max(0,x-600));                     // Redwood im Westen (x<600)
  return d;}
function farRaw(x,z){const h=farRaw0(x,z);if(x>1060)return h;const e=farEdgeD(x,z);if(e>=40)return h;const t=smooth(clamp(e/40,0,1));return rawHeight(x,z)*(1-t)+h*t;}
function farRaw0(x,z){const jw=jungleW(x,z);if(jw>=.999)return jungleH(x,z);const ho=farRawOld(x,Math.max(z,-120));if(jw<=0)return ho;const t=jw*jw*(3-2*jw);return ho*(1-t)+jungleH(x,z)*t;}
function farStrip(x,z){// Übergang Redwood -> Savanne
  const ho=rawHeight(x,z),hs=savH(x,z),w=smooth(clamp((x-600)/130,0,1))*smooth(clamp((120-z)/70,0,1))*(x<860?smooth(clamp((z+120)/45,0,1)):1);return ho*(1-w)+hs*w;}
function farRawOld(x,z){if(x<960&&z<=121)return farStrip(x,z);if(x>=1000||z>121)return farMain(x,z);const k=smooth(clamp((x-960)/40,0,1));return farStrip(x,z)*(1-k)+farMain(x,z)*k;}
function farMain(x,z){
  const bx=BG_X(z),bd=Math.abs(x-bx);let h;
  const sav=x<bx?savH(x,z):0,pla=x>bx-BG_HW-40?plainEH(x,z):0;
  if(x<bx)h=sav;else h=pla;
  // Ufer und Flussbett
  if(bd<BG_HW+30){const bank=x<bx?sav:pla,t=smooth(clamp((bd-BG_HW+6)/30,0,1)),bed=-5.5*(1-Math.pow(bd/(BG_HW+6),2))-.8;h=Math.min(bank,bed*(1-t)+Math.max(bank,1.8)*t);}
  // Straße: leicht geebnet
  const rdd=farRoadD(x,z);if(rdd<5&&bd>BG_HW+2){const t=smooth(clamp((5-rdd)/3,0,1));h=h*(1-t*.6)+Math.max(h,1.5)*t*.6;}
  // Übergang zur Wüste
  const dw=(1-smooth(clamp((x-1000)/70,0,1)))*smooth(clamp((z-100)/40,0,1))*smooth(clamp((860-z)/40,0,1));
  if(dw>0)h=desH(x,z)*dw+h*(1-dw);
  return h;}
const heightsF=new Float32Array(FR1*(FSZ+1)).fill(NaN);
const hFg=(ix,iz)=>{const k=iz*FR1+ix;let v=heightsF[k];if(v!==v){v=heightsF[k]=farRaw(FX0+ix*FCELL,FZ0+iz*FCELL);}return v;};
function getHeightF(x,z){const fx=clamp((x-FX0)/FCELL,0,FSX-1e-4),fz=clamp((z-FZ0)/FCELL,0,FSZ-1e-4),ix=Math.floor(fx),iz=Math.floor(fz),u=fx-ix,v=fz-iz;
  const ha=hFg(ix,iz),hd=hFg(ix+1,iz),hb=hFg(ix,iz+1),hc=hFg(ix+1,iz+1);
  if(u+v<=1)return ha+(hd-ha)*u+(hb-ha)*v;return hc+(hb-hc)*(1-u)+(hd-hc)*(1-v);}
function inFar(x,z){return(x>1000&&x<=2760&&z>=-120&&z<=1080)||(x>600&&x<=1000&&z>=-120&&z<120)||(x>840&&x<=1640&&z>=-760&&z<-120);}
function farInside(x,z){return Math.max(Math.min(2760-x,x-1000+(z<845?60:0),z+120,1080-z),Math.min(1060-x,x-540,z+120+(x<840?60:0),180-z),Math.min(1640-x,x-840,z+760,-60-z));}
// Brücke über den Big Bongo
function bongeDeck(x){const t=clamp((x-BG_BR.x0)/(BG_BR.x1-BG_BR.x0),0,1);return BG_BR.hA+(BG_BR.hB-BG_BR.hA)*t+.15+3.2*Math.sin(Math.PI*t);}
const onBongeBridge=(x,z)=>Math.abs(z-BG_BR.z)<BG_BR.w&&x>BG_BR.x0&&x<BG_BR.x1;
// Wasser im Fluss: nur über die Brücke
function clampFar(o){const bx=BG_X(o.z),bd=Math.abs(o.x-bx);if(bd<BG_HW-3&&!onBongeBridge(o.x,o.z)){const side=o.px!=null?Math.sign(o.px-bx)||1:Math.sign(o.x-bx)||1;o.x=bx+side*(BG_HW-3);}
  if(onBongeBridge(o.x,o.z)||Math.abs(o.z-BG_BR.z)<BG_BR.w+.6&&o.x>BG_BR.x0+6&&o.x<BG_BR.x1-6)o.z=clamp(o.z,BG_BR.z-BG_BR.w+.35,BG_BR.z+BG_BR.w-.35);}
function farArea(x,z){if(z<-40&&jungleW(x,z)>.55)return jArea(x,z);if(x<1000&&z<120)return x<700+(vnoise(x*.02,z*.02,1407)-.5)*60?'redwood':farMoist(x,z)<.36?'steppe':'savanna';if(x>KX0-25&&x<KX1+25&&z>KZ0-25&&z<KZ1+25){const c=kCat(x,z);if(c===7)return'kpalace';if(c>=0&&c!==1&&c!==0&&c!==8&&c!==9)return'kaiser';if(c===8)return'krice';
    if(c>=0)return'kaiser';}
  if(Math.hypot(x-HARB.x,z-HARB.z)<HARB.r+38)return'khafen';const bx=BG_X(z);if(Math.abs(x-bx)<BG_HW+18)return'bonge';if(x>bx)return'kplain';
  if(mtnMask(x,z)>.35)return'smtn';return farMoist(x,z)<.36?'steppe':'savanna';}

var FAR_READY=true;

/* =========================================================
   Der Dschungel: x 840..1640, z -760..-120 (nördlich der Savanne, östlich des Nordwalds)
   Übergang zum Redwood im Südwesten, zur Savanne im Süden
   ========================================================= */
const JX0=840,JX1=1640,JZ0=-760,JZ1=-120;
const JVIL={x:1385,z:-470,r:30,h:6.4},JCAVE={x:1012,z:-628,a:0},JRUIN={x:1508,z:-652,r:26,h:15.5},JTERM={x:985,z:-232};
const JHILLS=[[1000,-660,80,17],[1510,-652,62,13],[1240,-300,55,7],[1570,-300,50,9],[905,-455,55,10],[1290,-690,60,9]];
// Dschungelfluss: mündet in den Savannenfluss
const JRIV=(()=>{const R=mkRiver([[1085,-780],[1108,-650],[1160,-525],[1150,-405],[1172,-285],[1176,-190]],1501,7);const S0=SRIVERS[0].p;for(let i=0;i<3;i++)R.p.push(S0[i]);return R;})();
SRIVERS.push(JRIV);
function jungleW(x,z){if(x<690||x>1700||z>-40)return 0;let w=smooth(clamp((-40-z)/110,0,1))*smooth(clamp((x-690)/90,0,1))*smooth(clamp((1700-x)/60,0,1));
  if(w>0&&w<1)w=clamp(w+(vnoise(x*.02,z*.02,1530)-.5)*w*(1-w)*1.6,0,1);return w;}
function jSiteD(x,z){return Math.min(Math.hypot(x-JVIL.x,z-JVIL.z)-JVIL.r,Math.hypot(x-JRUIN.x,z-JRUIN.z)-JRUIN.r,Math.hypot(x-JCAVE.x,z-JCAVE.z)-10,Math.hypot(x-JTERM.x,z-JTERM.z)-9);}
function jMud(x,z){if(z>-60)return 0;const v=vnoise(x*.022,z*.022,1525)*.75+vnoise(x*.09,z*.09,1526)*.25;let m=smooth(clamp((v-.6)/.12,0,1));if(m>0){const sd=jSiteD(x,z);if(sd<25)m*=smooth(clamp(sd/25,0,1));}return m;}
function jungleH(x,z){let h=5.8+(fbm(x*.004+11,z*.004,3,1511)-.5)*8+(fbm(x*.02,z*.02,2,1512)-.5)*2.2;
  for(const[hx,hz,hr,hh]of JHILLS){const d=Math.hypot(x-hx,z-hz)/hr;if(d<1.3){const k=Math.max(0,1-d*d/1.69);h+=Math.pow(k,1.4)*hh*(.86+vnoise(x*.06,z*.06,1513)*.28);}}
  // Tempelberg: Plateau
  {const d=Math.hypot(x-JRUIN.x,z-JRUIN.z);if(d<JRUIN.r+18){const t=smooth(clamp((d-JRUIN.r)/18,0,1));h=JRUIN.h*(1-t)+h*t;}}
  // Dorfplatz
  {const d=Math.hypot(x-JVIL.x,z-JVIL.z);if(d<JVIL.r+16){const t=smooth(clamp((d-JVIL.r)/16,0,1));h=JVIL.h*(1-t)+h*t;}}
  // Lichtung vor der Höhle
  {const d=Math.hypot(x-JCAVE.x-8,z-JCAVE.z-14);if(d<16){const t=smooth(clamp((d-8)/8,0,1));h=Math.min(h,7.2)*(1-t)+h*t;}}
  h-=jMud(x,z)*1.5;h=Math.max(h,.35);
  // Fluss
  const rd=sRiverD(x,z);if(rd<BANK_W){const bed=-1.5+(vnoise(x*.1,z*.1,1514)-.5)*.3;h=Math.min(h,riverBank(rd,h,bed));}
  // Naht zum Nordwald
  if(x<900&&z<-80){let ne=h;try{ne=getHeightN(839.5,Math.min(z,-121));}catch(e){}const t=smooth(clamp((x-840)/60,0,1)),fz=z<-120?1:1-smooth(clamp((z+120)/40,0,1)),w=(1-t)*fz;h=ne*w+h*(1-w);}
  return h;}
function jArea(x,z){if(Math.hypot(x-JVIL.x,z-JVIL.z)<JVIL.r+14)return'jvillage';if(Math.hypot(x-JRUIN.x,z-JRUIN.z)<JRUIN.r+12)return'jruin';
  if(Math.hypot(x-JCAVE.x,z-JCAVE.z)<26)return'jcave';if(Math.hypot(x-JTERM.x,z-JTERM.z)<24)return'jtermite';return jMud(x,z)>.5?'jmud':'jungle';}
Object.assign(AREAS,{jungle:'Der Dschungel',jvillage:'Das Dorf der Affenmenschen',jruin:'Die vergessene Tempelruine',jcave:'Die Höhle des Urmenschen',jtermite:'Der Termitenhügel',jmud:'Die Schlammsenke'});
