// ---------- Bodenfarben ----------
const JP_={FLOOR:pal(['#1a2410','#223016','#2c3c1c','#364a22','#425828','#50682e']),LIT:pal(['#2a1e12','#382816','#48341c','#584224','#6a522e']),MOSS:pal(['#24401a','#2e5220','#3a6626','#48782c']),
  MUD:pal(['#1c140c','#271b10','#332416','#40301e','#4e3c28']),EARTH:pal(['#4a3a26','#5a4830','#6a563a','#7a6444','#8a744e']),RSTONE:pal(['#3a3e34','#4a4e42','#5a5e50','#6c6e5e','#7e8070'])};
function jColor(wx,wz,gx,gy,h,F){const rv=F.r(wx,wz);if(rv<4+(h-.5)*2){const g=getHeightF(wx,wz);return g<-.2?JP_.MUD[shadeIdx(.35+(h-.5)*.4,5,gx,gy)]:JP_.MUD[shadeIdx(.6+(h-.5)*.5,5,gx,gy)];}
  const dv=Math.hypot(wx-JVIL.x,wz-JVIL.z);if(dv<JVIL.r+(h-.5)*3){const n=vnoise(wx*.2,wz*.2,1561);return n>.7?JP_.FLOOR[shadeIdx(.5+(h-.5)*.4,6,gx,gy)]:JP_.EARTH[shadeIdx(.5+(n-.5)*.6+(h-.5)*.3,5,gx,gy)];}
  const dr=Math.hypot(wx-JRUIN.x,wz-JRUIN.z);if(dr<JRUIN.r-2){const sx=Math.floor(wx/1.8),sz=Math.floor(wz/1.8),edge=((wx/1.8)%1+1)%1<.08||((wz/1.8)%1+1)%1<.08,moss=vnoise(wx*.15,wz*.15,1562)>.55;
    return moss&&hash2(gx,gy,1563)<.7?JP_.MOSS[shadeIdx(.5+(h-.5)*.4,4,gx,gy)]:JP_.RSTONE[shadeIdx(.55+(hash2(sx,sz,1564)-.5)*.3-(edge?.3:0)+(h-.5)*.2,5,gx,gy)];}
  const m=jMud(wx,wz);if(m>.3+(h-.5)*.3){const shine=vnoise(wx*.3,wz*.3,1565)>.72;return shine?hex('#5e5040'):JP_.MUD[shadeIdx(.45+(vnoise(wx*.1,wz*.1,1566)-.5)*.6+(h-.5)*.3,5,gx,gy)];}
  const n=vnoise(wx*.06,wz*.06,1567),L=.5+(vnoise(wx*.25,wz*.25,1568)-.5)*.5+(h-.5)*.3;
  if(n>.66)return JP_.MOSS[shadeIdx(L,4,gx,gy)];if(n<.32||hash2(gx>>1,gy>>1,1569)<.18)return JP_.LIT[shadeIdx(L,5,gx,gy)];return JP_.FLOOR[shadeIdx(L,6,gx,gy)];}
{const ftc0=farTexColor;farTexColor=function(ch,wx,wz,gx,gy,F){if(wz<-40){const jw=jungleW(wx,wz);if(jw>0&&vnoise(wx*.12,wz*.12,1542)*.6+hash2(gx>>1,gy>>1,1543)*.4<jw*1.12-.04)return jColor(wx,wz,gx,gy,hash2(gx,gy,1541),F);}return ftc0(ch,wx,wz,gx,gy,F);};}
// ---------- Bewuchs ----------
function jungleDeco(ch,deco){if(ch.z0>-40||ch.x0+FCH<690||ch.x0>1700)return;const r=mulberry32(91000+ch.i*313+ch.j*2711),F=farFields(ch);
  const put=(n,fn)=>{for(let k=0;k<n;k++){const x=ch.x0+r()*FCH,z=ch.z0+r()*FCH;if(!inFar(x,z))continue;const jw=jungleW(x,z);if(jw<=0||r()>jw)continue;const gh=getHeightF(x,z);if(gh<WATER+.35)continue;
      const o=fn(x,z,gh,jw);if(o){if(o.x==null){o.x=x;o.z=z;}if(o.y==null)o.y=gh-(o.sink||.06);deco.push(o);}}};
  const ok=(x,z,m)=>F.r(x,z)>m&&jSiteD(x,z)>m&&jMud(x,z)<.25;
  // Urwaldriesen mit Lianen
  put(24,(x,z,gh)=>{if(!ok(x,z,7))return null;const h=26+r()*18,v=(r()*3)|0,s=SPR['jtree'+v];frogProp(x,z,1.5,h);
    for(let l=0;l<2;l++){if(r()<.4)continue;const lh=9+r()*8,lx=x+(r()-.5)*9,lz=z+(r()-.5)*9;deco.push({x:lx,z:lz,y:gh+h*.62-lh,w:lh*18/128,h:lh,spr:'liana'+(r()*2|0),sway:.03,tint:.85+r()*.2});}
    return{w:h*s.w/s.h,h,spr:'jtree'+v,sway:.006,tint:.82+r()*.24,sink:.6};});
  put(34,(x,z,gh)=>{if(!ok(x,z,3))return null;const h=9+r()*6;frogProp(x,z,.35,h);return{w:h*64/120,h,spr:'jpalm'+(r()*2|0),sway:.04,tint:.85+r()*.2,sink:.2};});
  put(26,(x,z,gh)=>{if(!ok(x,z,3)||vnoise(x*.03,z*.03,1571)<.6)return null;const h=6+r()*3;return{w:h*30/80,h,spr:'bamboo'+(r()*2|0),sway:.08,tint:.9+r()*.1};});
  put(230,(x,z,gh)=>{if(jSiteD(x,z)<2)return null;const w=2+r()*2.4;return{w,h:w*34/56,spr:'jbush'+(r()*3|0),sway:.04,tint:.8+r()*.3};});
  put(140,(x,z,gh)=>{if(jSiteD(x,z)<1)return null;const w=1.1+r()*1;return{w,h:w*32/40,spr:'jleaf'+(r()*2|0),sway:.07,tint:.85+r()*.25};});
  put(110,(x,z,gh)=>{const w=1+r()*.7;return{w,h:w*15/26,spr:'fern'+(r()*2|0),sway:.06,tint:.7+r()*.2};});
  put(60,(x,z,gh)=>{if(F.r(x,z)>8&&jMud(x,z)<.2)return null;return{w:1,h:1.3,spr:'reed'+(r()*2|0),sway:.12,tint:.85};});}
{const fd0=farData;farData=function(ch){const D=fd0(ch);try{jungleDeco(ch,D.deco);}catch(e){console.error(e);}return D;};}
// ---------- Teleport ----------
Object.assign(TP,{dschungel:{n:'Der Dschungel',p:()=>[1250,-380],yaw:0},affendorf:{n:'Das Dorf der Affenmenschen',p:()=>[JVIL.x,JVIL.z+JVIL.r+6],yaw:0},
  tempel:{n:'Die vergessene Tempelruine',p:()=>[JRUIN.x-JRUIN.r-10,JRUIN.z+10],yaw:-Math.PI/2},urmensch:{n:'Die Höhle des Urmenschen',p:()=>[JCAVE.x+10,JCAVE.z+22],yaw:0},termiten:{n:'Der Termitenhügel',p:()=>[JTERM.x+12,JTERM.z+10],yaw:0}});
