// Kreuzkragen, Schärpe, Haarnadel
function asianDress(cv,L){if(!cv.headBox||cv.waist==null)return cv;const x=cv.getContext('2d'),[h0,h1,t,b]=cv.headBox,cx=Math.round((h0+h1)/2),w=cv.waist,top=b+2;
  const d=x.getImageData(0,0,cv.width,cv.height),D=d.data,on=(px,py)=>D[(py*cv.width+px)*4+3]>0;
  const put=(px,py,col)=>{if(!on(px,py))return;const c=hex(col),i=(py*cv.width+px)*4;D[i]=c[0];D[i+1]=c[1];D[i+2]=c[2];};
  if(L.collar&&!L.helm){for(let k=0;k<=w-top-2;k++){put(cx-3+Math.round(k*3/(w-top-2)),top+k,L.collar);if(k<4)put(cx+3-k,top+k,L.collar);}}
  if(L.sash)for(let px=cx-7;px<=cx+7;px++)for(let py=w-1;py<=w+1;py++){const shade=py===w+1?.75:1,c=hex(L.sash);if(on(px,py)){const i=(py*cv.width+px)*4;D[i]=c[0]*shade;D[i+1]=c[1]*shade;D[i+2]=c[2]*shade;}}
  x.putImageData(d,0,0);if(L.pin){x.fillStyle='#e8c040';x.fillRect(cx+2,t-2,3,1);x.fillStyle='#c02030';x.fillRect(cx+4,t-3,1,1);}return cv;}
function citizenHat(cv,L){if(!L.hat||!cv.headBox)return cv;const x=cv.getContext('2d'),[h0,h1,t]=cv.headBox,cx=(h0+h1)/2;const c=s=>{x.fillStyle=s;};
  if(L.hat==='kasa'){for(let k=0;k<5;k++){c(['#6a5228','#8a6c36','#a88a48','#c2a45c','#d6ba70'][Math.min(4,k)]);const w=4+k*2.4;x.fillRect(Math.round(cx-w/2),t-4+k,Math.round(w),1);}c('#4a3a1c');x.fillRect(Math.round(cx-8),t+1,16,1);}
  else if(L.hat==='crest'){c('#c8a030');x.fillRect(Math.round(cx-1),t-5,2,4);c('#b02020');x.fillRect(Math.round(cx-2),t-7,4,2);}
  else if(L.hat==='scholar'){c('#141418');x.fillRect(Math.round(cx-4),t-3,8,3);x.fillRect(Math.round(cx-1),t-5,3,2);}
  return cv;}

