function wGroup(sp,x,z,r,mn,mx,ex){const g=Object.assign({sp,x,z,r,min:mn,max:mx,cx:x,cz:z,tx:x,tz:z,t:Math.random()*20,flee:0,fx:0,fz:0,hunger:Math.random()*.5,st:'rest',respawnT:60+Math.random()*120,angry:0,drinkT:120+Math.random()*240,id:WG.length},ex||{});WG.push(g);return g;}
