  const H=(sp,x,z,r,mn,mx,ex)=>{const g=wGroup(sp,x,z,r,mn,mx,ex);const n=mn+Math.floor(Math.random()*(mx-mn+1));for(let i=0;i<n;i++){const q=wPickNear(g,x,z,14);if(q)wSpawn(g,sp,q[0],q[1]);}return g;};
  H('zebra',1450,150,230,6,11);H('zebra',1600,780,220,6,11);H('zebra',2000,480,170,5,9);
