  for(const[ri,f]of[[0,.3],[0,.8],[1,.25],[1,.7],[2,.5]]){const[x,z]=rp(ri,f);const g=wGroup('croc',x,z,6,1,1,{lurk:{x,z}});wSpawn(g,'croc',x,z,{inWater:1});}
  for(const z of[380,820]){const x=BG_X(z)-BG_HW+6;const g=wGroup('croc',x,z,6,1,1,{lurk:{x,z}});wSpawn(g,'croc',x,z,{inWater:1});}
  // Löwenrudel auf dem Felsen
  {const g=wGroup('lion',PROCK.x,PROCK.z,520,5,7,{home:PROCK,st:'rest',hunger:.3});wSpawn(g,'lion',PROCK.lx-PROCK.c*4,PROCK.lz-PROCK.s*4,{male:1,spot:'ledge'});
    for(let i=0;i<5;i++)wSpawn(g,'lioness',PROCK.x+(Math.random()-.5)*12,PROCK.z+(Math.random()-.5)*12);}
