    for(const[ox,oz]of[[-1.5,-.6],[1.5,-.6],[-1.5,.6],[1.5,.6]]){const p=new THREE.Mesh(new THREE.BoxGeometry(.14,2.6,.14),tm);p.position.set(JSTALL.x+ox,y+1.3,JSTALL.z+oz);grp.add(p);}
