  if(e.job==='stay'){if(Math.hypot(e.home.x-e.x,e.home.z-e.z)>.6)entMove(e,e.home.x,e.home.z,1.2,dt);else{e.frame=0;const rx=Math.cos(P.yaw),rz=-Math.sin(P.yaw);e.flip=((P.x-e.x)*rx+(P.z-e.z)*rz)<0;}return true;}
