{const n0=storyLooked;storyLooked=function(){const v=n0();if(v)return v;const L=[];if(apes)L.push(...apes.filter(e=>!e.dead));if(grok&&!grok.dead&&!grok.sleep)L.push(grok);return L.length?lookNPC(L):null;};}
