// Platzhalter, bis die Ruine geladen ist
function ruinStage(){const R=FLAGS.ruin||{};if(R.heart)return'done';if(!R.gate)return'gate';if(!R.plates)return'plates';if(!R.scale)return'scale';if(!R.statues)return'statues';if(!R.braz)return'braz';return'shrine';}

