  for(let x=-22;x<-3.4;x+=4)rBox(x,Math.min(x+4,-3.4),0,wallH(),21.4,22.6,M());for(let x=3.4;x<22;x+=4)rBox(x,Math.min(x+4,22),0,wallH(),21.4,22.6,M());
