  rPlane(0,2.2,23,2.6,1.6,plaqueCanvas(3),0);rInt(0,2,23.2,2,()=>'Inschrift lesen',()=>ruinRead('Über dem Tor ist eingeritzt: „Nur wer die Bilder der Alten kennt, darf eintreten. Vier Zeichen, so wie sie gemalt wurden.“'));
