  // Treppe: sichtbar in Stufen, begehbar als feine Scheiben
  for(let k=0;k<18;k++){const y1=(k+1)*.5,z0=-(k+1)*.511;rBox(-1.5,1.5,0,y1,z0,z0+.511,ruinMatS,false);}
  
  RU.doors.stair=rBox(-1.7,1.7,0,2.6,.15,.55,ruinMatM);
  rBox(-2.2,-1.8,9,11.5,-14.4,-10.6,ruinMatS);rBox(1.8,2.2,9,11.5,-14.4,-10.6,ruinMatS);rBox(-2.2,2.2,11.5,12,-14.4,-10.6,ruinMatM,false);rBox(-2.2,2.2,9,11.5,-14.8,-14.4,ruinMatS);
  rBox(-.7,.7,9,10,-13.6,-12.6,ruinMatS);rInt(0,10.2,-13.1,2,()=>R.heart?null:R.tabs?'Die Fragen des Tempels beantworten':'Steintafeln einsetzen',()=>useShrine());
  // Feuerschalen
  const BP=[[-8,.5],[-4.5,1.8],[0,2.6],[4.5,1.8],[8,.5]],bdeco=[];BP.forEach(([dx,dz],i)=>{const[x,z]=RW(dx,dz);bdeco.push({x,y:RU.y,z,w:1.1,h:1.5,spr:'brazier',tint:1});RU.braz.push({dx,dz,x,z,lit:0});
    rInt(dx,1.2,dz,1.8,()=>R.braz||!(R.scale&&R.statues)?null:'Feuerschale entzünden',()=>lightBrazier(i));});
  RU.brazMesh=makeBillboards(bdeco,decorMat);RU.grp.add(RU.brazMesh);
  rPlane(0,1.3,3.6,1.6,1,SPR.glyph_sun.c,0);rBox(-.8,.8,0,.8,3.3,3.9,ruinMatS);rInt(0,1.2,3.8,2,()=>R.braz?null:!(R.scale&&R.statues)?'Der Sonnenstein schweigt noch':'Sonnenstein berühren',()=>showFireSeq());
  // Gelöste Rätsel: Türen offen
  if(R.gate)openDoor('gate',true);if(R.plates){openDoor('west',true);openDoor('east',true);}if(R.braz)openDoor('stair',true);
