function openDoor(k,instant){const d=RU.doors[k];if(!d||d.open)return;d.open=true;const i=COLL.indexOf(d.c);if(i>=0)COLL.splice(i,1);if(instant){d.m.position.y-=6;return;}d.sink=0;RU.sinking=(RU.sinking||[]).concat([d]);try{Snd.gate();}catch(e){}}
function ruinRead(t){toast(t.length>90?t.slice(0,90)+'…':t);ruinMsg(t);}
function ruinMsg(t){let el=$('ruinMsg');if(!el){el=document.createElement('div');el.id='ruinMsg';el.style.cssText='position:fixed;left:50%;bottom:22vh;transform:translateX(-50%);max-width:min(640px,86vw);background:rgba(20,18,12,.86);color:#f0e6c8;border:1px solid #8a7a50;padding:12px 16px;font:15px/1.4 serif;text-align:center;z-index:40;border-radius:4px;transition:opacity .4s';document.body.appendChild(el);}
  el.textContent=t;el.style.opacity=1;el.hidden=false;clearTimeout(ruinMsg.t);ruinMsg.t=setTimeout(()=>{el.style.opacity=0;},Math.max(4500,t.length*70));}
// ---------- Rätsel 1: Glyphentor ----------
function turnDial(i){const R=RF(),d=RU.dials[i];d.st=(d.st+1)%GLYPHS.length;R.dials=RU.dials.map(x=>x.st);const t=new THREE.CanvasTexture(SPR['glyph_'+GLYPHS[d.st]].c);t.magFilter=t.minFilter=THREE.NearestFilter;d.pl.material.map=t;d.pl.material.needsUpdate=true;try{Snd.clink(.6);}catch(e){}
  if(RU.dials.every((x,k)=>GLYPHS[x.st]===GLYPH_ORDER[k])){R.gate=1;setTimeout(()=>{openDoor('gate');ruinMsg('Die Zeichen leuchten auf. Mit tiefem Grollen versinkt das Tor im Boden.');gainXP(25);saveGame();},500);}}
// ---------- Rätsel 2: Druckplatten ----------
function plateToggle(st,k){const i=k%3,j=(k/3)|0;for(const[a,b]of[[0,0],[1,0],[-1,0],[0,1],[0,-1]]){const ii=i+a,jj=j+b;if(ii<0||jj<0||ii>2||jj>2)continue;st[jj*3+ii]^=1;}}
function syncPlates(){const R=RF();RU.plates.forEach((p,k)=>{const on=R.plates||R.plateSt[k];p.mat.color.setHex(on?0x8a8a5a:0x4a4c42);p.mat.emissive.setHex(on?0x5a4a10:0x000000);});}
function stepPlates(){const R=RF();if(R.plates||!R.gate)return;let cur=-1;if(P.ground&&Math.abs(P.y-RU.y)<.6)RU.plates.forEach((p,k)=>{const[x,z]=RW(p.dx,p.dz);if(Math.abs(P.x-x)<1.1&&Math.abs(P.z-z)<1.1)cur=k;});
  if(cur!==RU.onPlate){RU.onPlate=cur;if(cur>=0){plateToggle(R.plateSt,cur);syncPlates();try{Snd.clink(.4);Snd.thud();}catch(e){}if(R.plateSt.every(Boolean)){R.plates=1;syncPlates();setTimeout(()=>{openDoor('west');openDoor('east');ruinMsg('Alle neun Steine leuchten. Irgendwo im Westen und Osten rumpelt es: Die Kammern sind offen.');gainXP(25);saveGame();},400);}}}}
// ---------- Rätsel 3: Opferwaage ----------
function offerBanana(){const R=RF();if(R.scale)return;if(countItem('banana')<1){ruinMsg('Die Schale ist leer. Was wächst hier am Baum?');return;}removeItem('banana',1);RU.scaleN=(RU.scaleN||0)+1;RU.scaleT=3.5;try{Snd.pop();}catch(e){}toast('Banane in die Schale gelegt ('+RU.scaleN+')');}
function tickScale(dt){const R=RF();if(R.scale||!RU.scaleT)return;RU.scaleT-=dt;if(RU.scaleT>0)return;RU.scaleT=0;const n=RU.scaleN;RU.scaleN=0;const[x,z]=RW(-15,4);
  if(n===7){R.scale=1;ruinMsg('Die Schale senkt sich langsam. Ein Fach öffnet sich im Altar: das Jaguarzahn-Amulett!');spawnDrop('jaguartooth',1,x,RU.y+1.3,z);try{Snd.levelUp();}catch(e){}gainXP(40);saveGame();}
  else if(n>7){ruinMsg('Die Schale kippt und wirft alles heraus. Zu viel!');spawnDrop('banana',n,x+1,RU.y+1,z);try{Snd.thud();}catch(e){}}
  else ruinMsg('Die Schale bewegt sich nicht. Die Bananen verschwinden im Dunkel des Altars …');}
// ---------- Rätsel 4: Statuen ----------
function syncStatues(instant){const R=RF();RU.statues.forEach((s,i)=>{s.target=-R.sdir[i]*Math.PI/2;if(instant)s.g.rotation.y=s.target;});}
function turnStatue(i){const R=RF();R.sdir[i]=(R.sdir[i]+1)%4;syncStatues();try{Snd.gate();}catch(e){}
  if(RU.statues.every((s,k)=>R.sdir[k]===s.want)){R.statues=1;setTimeout(()=>{const[x,z]=RW(15.5,4.1);ruinMsg('Die vier Tiere blicken in ihre Richtungen. Der kleine Altar in der Mitte öffnet sich: ein Smaragd-Idol!');spawnDrop('emeraldidol',1,x,RU.y+1.2,z);try{Snd.levelUp();}catch(e){}gainXP(40);saveGame();},900);}}
// ---------- Rätsel 5: Feuerschalen ----------
function showFireSeq(){const R=RF();if(R.braz||!(R.scale&&R.statues))return;if(RU.seqShow>0)return;RU.round=RU.round||1;if(!RU.seq||RU.seq.length<RU.round+2){RU.seq=RU.seq&&RU.seq.length?RU.seq:[];while(RU.seq.length<RU.round+2)RU.seq.push((Math.random()*5)|0);}
  RU.input=[];RU.seqShow=.01;RU.seqI=-1;ruinMsg('Runde '+RU.round+' von 3: Die Feuerschalen flackern auf. Merk dir die Reihenfolge!');}
function lightBrazier(i){const R=RF();if(R.braz||!(R.scale&&R.statues))return;if(!RU.seq||RU.seqShow>0){ruinMsg('Berühre zuerst den Sonnenstein vor der Treppe.');return;}flareBrazier(i,.5);RU.input.push(i);const k=RU.input.length-1;
  if(RU.seq[k]!==i){ruinMsg('Die Flammen erlöschen zischend. Ein Pfeil schießt aus der Wand! Fang noch einmal an.');takeDamage(5);RU.round=1;RU.seq=null;RU.input=[];try{Snd.hit('bow');}catch(e){}return;}
  if(RU.input.length===RU.seq.length){if(RU.round>=3){R.braz=1;ruinMsg('Alle fünf Feuer brennen hell. Das Gitter vor der Treppe versinkt.');setTimeout(()=>openDoor('stair'),600);gainXP(50);saveGame();RU.braz.forEach(b=>b.lit=999);}
    else{RU.round++;ruinMsg('Richtig! Berühre den Sonnenstein für die nächste Runde.');try{Snd.chime();}catch(e){}}}}
function flareBrazier(i,t){const b=RU.braz[i];b.lit=Math.max(b.lit,t);try{Snd.tone('triangle',[392,440,523,587,659][i],Snd.ctx.currentTime,.5,.06);}catch(e){}}
function tickBraziers(dt){if(RU.seqShow>0){RU.seqShow+=dt;const k=Math.floor((RU.seqShow-.6)/.9);if(k!==RU.seqI&&k>=0&&k<RU.seq.length){RU.seqI=k;flareBrazier(RU.seq[k],.6);}if(k>=RU.seq.length)RU.seqShow=0;}
  const R=RF(),g=RU.brazMesh&&RU.brazMesh.geometry.attributes;RU.braz.forEach((b,i)=>{if(b.lit>0&&b.lit<900)b.lit-=dt;const on=b.lit>0||R.braz;if(on&&Math.random()<dt*14)spawnParticle(b.x+(Math.random()-.5)*.3,RU.y+1.45,b.z+(Math.random()-.5)*.3,(Math.random()-.5)*.3,1.6+Math.random(),(Math.random()-.5)*.3,Math.random()<.5?0xff7a1a:0xffd040,.5,.25);
    if(g){g.tint.array[i]=on?1.5:.8;}});if(g)g.tint.needsUpdate=true;}
// ---------- Rätsel 6: Schrein ----------
const SHRINE_Q=[['Was fällt dem Geduldigen vom Baum?',['Bananen','Kokosnüsse','Blätter'],0],['Wer lauert im Fluss und wartet auf die Durstigen?',['Das Nilpferd','Das Krokodil','Der Fisch'],1],['Wer baut Türme aus Erde, ohne Hände zu haben?',['Die Affen','Die Erdmännchen','Die Termiten'],2]];
Object.assign(ITEM_DESC,{tablet1:'„Der Geduldige wartet unter dem Baum, und der Baum gibt ihm Gold.“',tablet2:'„Im Wasser wartet der Geduldige mit vielen Zähnen.“',tablet3:'„Ohne Hände bauen die Kleinen Türme aus Erde.“'});
const shrineV={name:'Der Schrein',role:'Herz des Dschungels',x:0,z:0,y:0,h:1,talk:0,d:{id:'shrine'}};
function useShrine(){const R=RF();if(R.heart)return;if(!R.tabs){const have=[1,2,3].filter(k=>countItem('tablet'+k)>0);if(have.length<3){ruinMsg('Drei Vertiefungen im Altar, geformt wie Bruchstücke einer Tafel. Du hast '+have.length+' von 3 Stücken.');return;}
    for(const k of[1,2,3])removeItem('tablet'+k,1);R.tabs=1;ruinMsg('Die drei Tafeln fügen sich zusammen. Eine Stimme hallt durch den Schrein …');saveGame();}
  if(!shrineV.portrait){const c=document.createElement('canvas');c.width=c.height=22;c.getContext('2d').drawImage(SPR.jungleheart.c,4,4);shrineV.portrait=c;}RU.q=0;openDialog(shrineV);}
DIALOGS['Der Schrein']={start:()=>'q',nodes:{q:()=>{const Q=SHRINE_Q[RU.q||0];return{text:'„'+Q[0]+'“',opts:Q[1].map((a,i)=>({label:a,act:()=>shrineAnswer(i),go:i===Q[2]?((RU.q||0)>=2?'win':'next'):'fail'}))};},
  next:()=>({text:'„Gut.“ Die Stimme wird lauter.',opts:[{label:'Weiter.',act:()=>{RU.q=(RU.q||0)+1;},go:'q'}]}),
  fail:()=>({text:'„Falsch!“ Der Boden bebt, und aus den Ritzen kriechen Schlangen!',opts:[{label:'Oh nein.',go:null}]}),
  win:()=>({text:'„Du kennst den Dschungel. Nimm sein Herz und trage es weise.“',opts:[{label:'Das Herz nehmen.',go:null,act:()=>shrineWin()}]})}};
function shrineAnswer(i){const Q=SHRINE_Q[RU.q||0];if(i!==Q[2]){RU.q=0;setTimeout(()=>{for(let k=0;k<3;k++){const g=WG.find(g=>g.sp==='snake');if(g){const[x,z]=RW((Math.random()-.5)*6,-6+Math.random()*3);wSpawn(g,'snake',x,z);}}},300);}}
function shrineWin(){const R=RF();if(R.heart)return;R.heart=1;const[x,z]=RW(0,-12);spawnDrop('jungleheart',1,x,RU.y+9.6,z);P.stats.maxHp+=25;P.stats.hp=P.stats.maxHp;renderStats();gainXP(150);try{Snd.fanfare();}catch(e){}
  setTimeout(()=>ruinMsg('Das Herz des Dschungels pocht in deiner Hand. Du fühlst dich stärker (+25 Leben).'),400);saveGame();}
