function ruinLooked(){if(!RU.built||Math.abs(P.x-RU.x)>30||Math.abs(P.z-RU.z)>30)return null;let best=null,bd=1e9;
  for(const o of RU.ints){const d=Math.hypot(o.x-P.x,o.z-P.z);if(d>o.r+.6)continue;const lab=o.label();if(!lab)continue;if(!lookingAt(o.x,o.y,o.z,o.r+2,.75))continue;if(d<bd){bd=d;best=o;}}return best;}
{const s0=storyPrompt;storyPrompt=function(){if(s0())return true;const o=ruinLooked();if(o){promptEl.innerHTML=`<b>[Rechtsklick]</b>${o.label()}`;promptEl.hidden=false;return true;}return false;};}
{const r0=rightClickUse;rightClickUse=function(){if(state==='playing'){const o=ruinLooked();if(o){P.lastAction=time;o.use();return true;}}return r0();};}
function updateRuin(dt){if(!RU.built){if(Math.hypot(P.x-RU.x,P.z-RU.z)<260&&P.x<60000&&jLifeInit)buildRuin();return;}RU.grp.visible=P.x<60000;
  if(RU.sinking)for(const d of RU.sinking){if(d.sink<6){const s=Math.min(dt*1.6,6-d.sink);d.sink+=s;d.m.position.y-=s;if(Math.random()<dt*20)spawnParticle(d.m.position.x+(Math.random()-.5)*3,RU.y+.3,d.m.position.z+(Math.random()-.5)*1,(Math.random()-.5),1+Math.random(),(Math.random()-.5),0x8a8470,1,.3);}}
  for(const s of RU.statues){const d=s.target-s.g.rotation.y;s.g.rotation.y+=Math.abs(d)<.01?d:Math.sign(d)*Math.min(Math.abs(d),dt*2.5);}
  if(Math.abs(P.x-RU.x)<30&&Math.abs(P.z-RU.z)<30){stepPlates();tickScale(dt);}tickBraziers(dt);
  if(countItem('jaguartooth')>0&&P.stats.st<P.stats.maxSt&&!P.sprinting)P.stats.st=Math.min(P.stats.maxSt,P.stats.st+dt*5);}
{const u0=updateAnimals;updateAnimals=function(dt){u0(dt);try{updateRuin(dt);}catch(e){if(!updateRuin.e){updateRuin.e=1;console.error(e);}}};}

// Treppe der Pyramide als Rampe für die Bewegung (Stufen nur optisch)
{const g0=groundAt;groundAt=function(x,z,feet){const g=g0(x,z,feet);if(!RU.built||Math.abs(x-RU.x)>2||z>RU.z+.2||z<RU.z-9.4)return g;const dz=RU.z-z;if(Math.abs(x-RU.x)>1.5)return g;
  const ramp=RU.y+clamp(dz,0,8.8)*(9.2/8.8);if(feet==null||feet>=ramp-1.6)return Math.max(g,ramp);return g;};}

/* ---- SpionGHG ruft ab und zu etwas, wenn er dich sieht (aus seiner Richtung, max. 7 s) ---- */
const SPY_CLIPS=['assets/sfx/spion/nicht_eingeladen.mp3','assets/sfx/spion/wo_ist_guam.mp3','assets/sfx/spion/amboss.mp3'];
const SpyV={el:null,t0:0,wait:3,last:-1};
function spyVoiceStop(){const v=SpyV;if(v.el){try{v.el.pause();}catch(e){}v.el.removeAttribute('src');try{v.el.load();}catch(e){}v.el=null;v.wait=5+Math.random()*10;}}
function spyVoiceVol(){const s=spy;if(!s)return 0;const d=Math.hypot(P.x-s.x,P.z-s.z),base=.5*Math.pow((settings.sound==null?80:settings.sound)/100,1.2);return clamp(base*(1-d/55)*(d<8?1:.55+.45*(1-(d-8)/47)),0,1);}
function updateSpyVoice(dt){const v=SpyV,s=spy;
  if(v.el){if(!s||s.dead||state==='menu'||v.el.currentTime>=7||v.el.ended||s.state==='flee'){spyVoiceStop();return;}v.el.volume=spyVoiceVol();return;}
  if(!s||s.dead||state!=='playing'||s.state==='flee')return;const d=Math.hypot(P.x-s.x,P.z-s.z);if(d>50)return;
  v.wait-=dt;if(v.wait>0)return;
  let k=(Math.random()*SPY_CLIPS.length)|0;if(k===v.last)k=(k+1)%SPY_CLIPS.length;v.last=k;
  const el=new Audio(SPY_CLIPS[k]);el.volume=spyVoiceVol();v.el=el;v.t0=time;el.addEventListener('error',()=>{if(v.el===el)spyVoiceStop();},{once:true});
  const p=el.play();if(p&&p.catch)p.catch(()=>{if(v.el===el)spyVoiceStop();});}
setInterval(()=>{try{updateSpyVoice(.1);}catch(e){}},100);
{const d0=despawnSpy;despawnSpy=function(){d0();spyVoiceStop();SpyV.wait=3;};}
/* ---- Wenn SpionGHG wegläuft: Zick-Zack ab Sekunde 6, aus seiner Richtung ---- */
