function spyRunStop(){if(SpyRun.el){try{SpyRun.el.pause();}catch(e){}SpyRun.el.removeAttribute('src');try{SpyRun.el.load();}catch(e){}SpyRun.el=null;}}
function updateSpyRun(){const s=spy;
  if(!s||s.dead||state==='menu'){spyRunStop();return;}
  if(s.state==='flee'&&!SpyRun.el){const el=new Audio('assets/sfx/spion/zick_zack.mp3');SpyRun.el=el;el.volume=0;
    const go=()=>{try{el.currentTime=6;}catch(e){}const p=el.play();if(p&&p.catch)p.catch(()=>{});};el.addEventListener('playing',()=>{if(el.currentTime<5.5)try{el.currentTime=6;}catch(e){}},{once:true});
    if(el.readyState>=1)go();else el.addEventListener('loadedmetadata',go,{once:true});el.addEventListener('error',()=>{if(SpyRun.el===el)SpyRun.el=null;},{once:true});}
  if(SpyRun.el){const d=Math.hypot(P.x-s.x,P.z-s.z),base=.45*Math.pow((settings.sound==null?80:settings.sound)/100,1.2);SpyRun.el.volume=clamp(base*Math.pow(clamp(1-d/90,0,1),1.4),0,1);}}
setInterval(()=>{try{updateSpyRun();}catch(e){}},100);
